/// Typed identity for the shared selector panel: behavior and background-load
/// guards key on this, never on the human title.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SelectorPanelKind {
    /// Thinking level, transcript files, trust, and goal pickers.
    Normal,
    /// Bare `/commit` recent-commit picker fed by `CommitListLoaded`.
    CommitList,
}

struct SelectorPanel {
    title: String,
    help: String,
    items: Vec<PanelItem>,
    selected: usize,
    query: String,
    kind: SelectorPanelKind,
}

impl SelectorPanel {
    fn visible_indices(&self) -> Vec<usize> {
        if self.query.is_empty() {
            return (0..self.items.len()).collect();
        }
        let query = self.query.to_lowercase();
        self.items
            .iter()
            .enumerate()
            .filter(|(_, item)| {
                subsequence_match(&item.label.to_lowercase(), &query)
                    || subsequence_match(&item.description.to_lowercase(), &query)
            })
            .map(|(index, _)| index)
            .collect()
    }

    fn selected_item(&self) -> Option<&PanelItem> {
        self.visible_indices()
            .get(self.selected)
            .and_then(|index| self.items.get(*index))
    }

    fn push_query(&mut self, character: char) {
        if self.title == "Goal" {
            return;
        }
        let retained = self.selected_original_index();
        self.query.push(character);
        self.restore_visible_selection(retained);
    }

    fn pop_query(&mut self) {
        if self.title == "Goal" {
            return;
        }
        let retained = self.selected_original_index();
        self.query.pop();
        self.restore_visible_selection(retained);
    }

    fn selected_original_index(&self) -> Option<usize> {
        self.visible_indices().get(self.selected).copied()
    }

    fn restore_visible_selection(&mut self, retained: Option<usize>) {
        let visible = self.visible_indices();
        self.selected = retained
            .and_then(|item_index| visible.iter().position(|&index| index == item_index))
            .unwrap_or(0);
        self.clamp_selection();
    }

    fn clamp_selection(&mut self) {
        self.selected = self
            .selected
            .min(self.visible_indices().len().saturating_sub(1));
    }
}

