fn hub_send_outcome_label(card: &ToolCardRows) -> &'static str {
    let Some(receipts) = card
        .details
        .get("receipts")
        .and_then(serde_json::Value::as_array)
        .filter(|receipts| !receipts.is_empty())
    else {
        return if card.is_error { "failed" } else { "delivered" };
    };

    let mut any_failed = false;
    let mut any_success = false;
    let mut unanimous: Option<&'static str> = None;
    for receipt in receipts {
        let label = match receipt
            .get("outcome")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
        {
            "queued" => "queued",
            "woken" => "injected",
            "revived" => "revived",
            "failed" => "failed",
            // Unknown delivery outcomes fail closed as delivered rather than
            // inventing a success state the operator cannot trust.
            _ => "delivered",
        };
        if label == "failed" {
            any_failed = true;
        } else {
            any_success = true;
        }
        unanimous = match unanimous {
            None => Some(label),
            Some(existing) if existing == label => Some(existing),
            Some(_) => Some(""),
        };
    }

    if any_failed && any_success {
        "partial"
    } else if any_failed {
        "failed"
    } else if let Some(label) = unanimous.filter(|label| !label.is_empty()) {
        label
    } else {
        "delivered"
    }
}

fn render_hub_send_card(
    lines: &mut Vec<Line<'static>>,
    card: &ToolCardRows,
    _expanded: bool,
    theme: Theme,
    width: u16,
) {
    let Some(to) = card.arguments.get("to").and_then(serde_json::Value::as_str) else {
        render_plain_tool_card(lines, card, theme, width);
        return;
    };
    let target = human_safe_label(to, "agent");
    render_hub_irc_metadata_card(
        lines,
        &format!("✉ IRC ➤ {target} {}", hub_send_outcome_label(card)),
        card.is_error,
        theme,
        width,
    );
    if let Some(reply) = card
        .details
        .get("reply")
        .and_then(orchestration_irc_view_from_json)
    {
        let sender = human_safe_label(reply.from.as_ref(), "agent");
        render_hub_irc_metadata_card(
            lines,
            &format!("✉ IRC ⟵ {sender} replied"),
            false,
            theme,
            width,
        );
    }
}

fn render_hub_irc_metadata_card(
    lines: &mut Vec<Line<'static>>,
    title: &str,
    is_error: bool,
    theme: Theme,
    width: u16,
) {
    let inner = usize::from(width.saturating_sub(2).max(1));
    let border = if is_error {
        theme.error
    } else {
        theme.tool_card_border
    };
    push_tool_card_top(
        lines,
        &compact_safe_text(title, inner.saturating_sub(2).max(1)),
        theme.tool_title,
        border,
        inner,
    );
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(inner)),
        Style::default().fg(border),
    )));
    lines.push(Line::default());
}

fn render_hub_compact_operation_row(
    lines: &mut Vec<Line<'static>>,
    title: &str,
    is_error: bool,
    theme: Theme,
    width: u16,
) {
    let available = usize::from(width.max(1));
    let marker = if is_error { "!" } else { "✓" };
    let text = compact_safe_text(&format!("{marker} {title}"), available);
    let color = if is_error {
        theme.error
    } else {
        theme.tool_title
    };
    lines.push(Line::from(Span::styled(text, Style::default().fg(color))));
}

fn render_hub_wait_card(
    lines: &mut Vec<Line<'static>>,
    card: &ToolCardRows,
    _expanded: bool,
    theme: Theme,
    width: u16,
) {
    let Some(view) = card
        .details
        .get("message")
        .and_then(orchestration_irc_view_from_json)
    else {
        render_plain_tool_card(lines, card, theme, width);
        return;
    };
    let sender = human_safe_label(view.from.as_ref(), "agent");
    let inner = usize::from(width.saturating_sub(2).max(1));
    let border = theme.tool_card_border;
    push_tool_card_top(
        lines,
        &compact_safe_text(
            &format!("✉ IRC ⟵ {sender} received"),
            inner.saturating_sub(2).max(1),
        ),
        theme.tool_title,
        border,
        inner,
    );
    for row in &card.rows {
        if row.role == ToolCardRowRole::Content {
            push_tool_box_row(lines, &row.text, theme.tool_output, border, inner);
        }
    }
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(inner)),
        Style::default().fg(border),
    )));
    lines.push(Line::default());
}

fn hub_operation_title(card: &ToolCardRows, operation: &str) -> String {
    let state = match card.status {
        ToolCallViewStatus::Running | ToolCallViewStatus::Streaming => "running",
        ToolCallViewStatus::Succeeded | ToolCallViewStatus::OrphanRepaired => "complete",
        ToolCallViewStatus::Failed => "failed",
        ToolCallViewStatus::Cancelled => "cancelled",
    };
    let label = match operation {
        "send" => "send",
        "ask" => "ask",
        "wait" => "wait",
        "inbox" => "inbox",
        "list" => "agents",
        "jobs" => "jobs",
        "cancel" => "cancel",
        "read_history" => "history",
        _ => "operation",
    };
    format!("Hub {label} · {state}")
}

fn render_hub_operation_card(
    lines: &mut Vec<Line<'static>>,
    card: &ToolCardRows,
    operation: &str,
    theme: Theme,
    width: u16,
) {
    if operation == "wait"
        && let Some(row) = card
            .rows
            .iter()
            .find(|row| matches!(row.role, ToolCardRowRole::Status | ToolCardRowRole::Error))
    {
        let status = row.text.strip_prefix("Wait ").unwrap_or(&row.text);
        let text = compact_safe_text(&format!("• Hub wait · {status}"), usize::from(width.max(1)));
        lines.push(Line::from(Span::styled(
            text,
            Style::default().fg(theme.tool_output),
        )));
        return;
    }
    render_hub_compact_operation_row(
        lines,
        &hub_operation_title(card, operation),
        card.is_error,
        theme,
        width,
    );
}

fn render_hub_failed_wait_card(
    lines: &mut Vec<Line<'static>>,
    card: &ToolCardRows,
    theme: Theme,
    width: u16,
) {
    let inner = usize::from(width.saturating_sub(2).max(1));
    let border = theme.error;
    let title = hub_operation_title(card, "wait");
    push_tool_card_top(
        lines,
        &compact_safe_text(&title, inner.saturating_sub(2).max(1)),
        theme.tool_title,
        border,
        inner,
    );
    for row in &card.rows {
        if matches!(row.role, ToolCardRowRole::Status | ToolCardRowRole::Error) {
            push_tool_box_row(lines, &row.text, theme.tool_output, border, inner);
        }
    }
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(inner)),
        Style::default().fg(border),
    )));
    lines.push(Line::default());
}

fn render_plain_tool_card(
    lines: &mut Vec<Line<'static>>,
    card: &ToolCardRows,
    theme: Theme,
    width: u16,
) {
    let inner = usize::from(width.saturating_sub(2).max(1));
    let border = if card.is_error {
        theme.error
    } else {
        theme.tool_card_border
    };
    let title = card
        .rows
        .iter()
        .find(|row| row.role == ToolCardRowRole::Command)
        .map_or(card.tool_name.as_str(), |row| row.text.as_str());
    push_tool_card_top(lines, title, theme.tool_title, border, inner);
    for row in &card.rows {
        if row.role != ToolCardRowRole::Command {
            push_tool_box_row(lines, &row.text, theme.tool_output, border, inner);
        }
    }
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(inner)),
        Style::default().fg(border),
    )));
    lines.push(Line::default());
}

fn render_tool_card(
    lines: &mut Vec<Line<'static>>,
    tool: &ToolTranscript,
    expanded: bool,
    theme: Theme,
    width: u16,
) {
    let card = if expanded {
        &tool.expanded
    } else {
        &tool.compact
    };
    if card.tool_name.eq_ignore_ascii_case("hub") {
        let operation = card
            .arguments
            .get("op")
            .and_then(serde_json::Value::as_str)
            .unwrap_or("operation");
        match operation {
            "send" => render_hub_send_card(lines, card, expanded, theme, width),
            "wait" if card.is_error => render_hub_failed_wait_card(lines, card, theme, width),
            "wait"
                if card
                    .details
                    .get("message")
                    .is_some_and(|message| !message.is_null()) =>
            {
                render_hub_wait_card(lines, card, expanded, theme, width);
            }
            _ => render_hub_operation_card(lines, card, operation, theme, width),
        }
        return;
    }
    let is_bash = card.tool_name.eq_ignore_ascii_case("bash");
    let border = card.frame_color(theme);
    let inner = usize::from(width.saturating_sub(2).max(1));
    // Render-time redaction: tool titles/arguments can carry inline tokens
    // (e.g. `--token=…`); the raw text stays in the session record.
    let tool_title = redact_secrets(
        card.rows
            .iter()
            .find(|row| row.role == ToolCardRowRole::Command)
            .map_or(card.tool_name.as_str(), |row| row.text.as_str()),
    );
    let marker = card.status_glyph();
    if card.tool_name.eq_ignore_ascii_case("glob") {
        let title = format!("{marker} {}", card.summary);
        let color = match card.status {
            ToolCallViewStatus::Cancelled => theme.warning,
            ToolCallViewStatus::Failed => theme.error,
            _ => theme.tool_title,
        };
        let wrap_width = usize::from(width.max(1));
        for line in wrap_styled_line(
            Line::from(Span::styled(
                clean_terminal_text(&title),
                Style::default().fg(color),
            )),
            wrap_width,
        ) {
            lines.push(line);
        }
        for row in &card.rows {
            if row.role == ToolCardRowRole::Command {
                continue;
            }
            let row_color = match row.role {
                ToolCardRowRole::Error => theme.error,
                ToolCardRowRole::Status => theme.muted,
                _ => theme.tool_output,
            };
            for line in wrap_styled_line(
                Line::from(Span::styled(
                    clean_terminal_text(&redact_secrets(&row.text)),
                    Style::default().fg(row_color),
                )),
                wrap_width,
            ) {
                lines.push(line);
            }
        }
        if card.truncated {
            let footer = if expanded {
                format!("… {} more lines", card.omitted_content_lines)
            } else {
                format!(
                    "… {} more lines ⟦Ctrl+O: Expand⟧",
                    card.omitted_content_lines
                )
            };
            for line in wrap_styled_line(
                Line::from(Span::styled(footer, Style::default().fg(theme.dim))),
                wrap_width,
            ) {
                lines.push(line);
            }
        }
        lines.push(Line::default());
        return;
    }

    if is_bash {
        // Bash cards carry no tool-name title — the `$` prefix identifies the
        // tool (OMP-style). Leading comment lines (`# …`) render on the card
        // frame instead of the command area: the first becomes the top-border
        // title, a second renders as a frame row above the command (deeper
        // ones are dropped, keeping the card bounded), and the `$` row starts
        // at the first real command line. Interior comments stay in the
        // command body, which renders line-by-line (each line kept, `$ ` on
        // the first row only), wraps, and is bounded to four rows with a `…`
        // marker; the card stays within its row budget.
        let command = clean_terminal_text(&redact_secrets(
            card.bash_command
                .as_deref()
                .unwrap_or(card.arguments_summary.as_str()),
        ));
        let (leading_comments, command_body) = split_leading_comments(&command);
        if let Some(title) = leading_comments.first() {
            push_bash_comment_top(lines, title, theme.dim, border, inner);
            if let Some(extra) = leading_comments.get(1) {
                push_bash_comment_row(lines, extra, theme.dim, border, inner);
            }
        } else {
            lines.push(Line::from(Span::styled(
                format!("╭{}╮", "─".repeat(inner)),
                Style::default().fg(border),
            )));
        }
        push_bash_command_lines(lines, command_body, theme.dim, border, inner);
        if card.rows.iter().any(|row| {
            matches!(
                row.role,
                ToolCardRowRole::Content | ToolCardRowRole::Status | ToolCardRowRole::Error
            )
        }) {
            push_tool_separator(lines, " Output ", border, inner);
        }
    } else {
        let is_todo = card.tool_name.eq_ignore_ascii_case("todo");
        let title = if is_todo {
            format!("{marker} {}", redact_secrets(&card.summary))
        } else if card.skill_name.is_some() {
            // Skill cards title with the frontmatter name; the description is
            // the first body paragraph below the separator.
            format!("{marker} {tool_title}")
        } else if !card.summary.is_empty() {
            format!("{marker} {}", redact_secrets(&card.summary))
        } else if card.arguments_summary.is_empty() {
            format!("{marker} {tool_title}")
        } else {
            format!(
                "{marker} {tool_title} {}",
                redact_secrets(&card.arguments_summary)
            )
        };
        push_tool_card_top(lines, &title, theme.tool_title, border, inner);
        if !is_todo
            && card
                .rows
                .iter()
                .any(|row| row.role != ToolCardRowRole::Command)
        {
            // Separator row between the title and the body.
            push_tool_separator(lines, "", border, inner);
        }
    }
    let code_styles = markdown_ratatui_styles(theme, theme.tool_output);
    for row in &card.rows {
        if row.role == ToolCardRowRole::Command {
            continue;
        }
        let color = match row.role {
            ToolCardRowRole::Command => theme.tool_title,
            ToolCardRowRole::Content => theme.tool_output,
            ToolCardRowRole::Details => theme.dim,
            ToolCardRowRole::Status => match card.status {
                ToolCallViewStatus::Cancelled => theme.warning,
                ToolCallViewStatus::Failed => theme.error,
                _ => theme.muted,
            },
            ToolCardRowRole::Error => theme.error,
        };
        if row.role == ToolCardRowRole::Content
            && let Some(language) = card.code_language.as_deref()
        {
            // Syntax-highlighted content (read/write/edit with a trusted
            // file extension): keep the existing hljs-style spans; the
            // text is cleaned of control sequences before highlighting.
            for text in clean_terminal_text(&redact_secrets(&row.text)).lines() {
                for line in wrap_styled_line(
                    Line::from(markdown_syntax_spans(text, Some(language), code_styles)),
                    inner.saturating_sub(2).max(1),
                ) {
                    push_tool_box_line(lines, line, border, inner);
                }
            }
        } else {
            // Output rows: ANSI SGR styling through the shared parser.
            // Newlines become separate card rows (style carries across),
            // each wrapped by the width-safe wrapper. Titles/args stay
            // cleaned plain text. Redaction is fail-closed inside
            // ansi_styled_lines (parse raw -> redact full plain).
            for line in ansi_styled_lines(
                &row.text,
                Style::default().fg(color),
                inner.saturating_sub(2).max(1),
            ) {
                push_tool_box_line(lines, line, border, inner);
            }
        }
    }
    if card.truncated {
        let footer = if expanded {
            format!("… {} more lines", card.omitted_content_lines)
        } else {
            format!(
                "… {} more lines ⟦Ctrl+O: Expand⟧",
                card.omitted_content_lines
            )
        };
        push_tool_box_row(lines, &footer, theme.dim, border, inner);
    }
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(inner)),
        Style::default().fg(border),
    )));
    lines.push(Line::default());
}

#[doc(hidden)]
pub fn render_tool_card_lines_for_test(
    compact: ToolCardRows,
    expanded: ToolCardRows,
    expand: bool,
    theme: Theme,
    width: u16,
) -> Vec<Line<'static>> {
    let mut lines = Vec::new();
    render_tool_card(
        &mut lines,
        &ToolTranscript { compact, expanded },
        expand,
        theme,
        width,
    );
    lines
}

/// Top border with the card title embedded, OMP-style (`╭── Bash ────╮`).
/// Falls back to a plain top border plus a wrapped title row when the title
/// does not fit on the border line.
fn push_tool_card_top(
    lines: &mut Vec<Line<'static>>,
    title: &str,
    color: Color,
    border: Color,
    inner: usize,
) {
    let title = clean_terminal_text(title);
    let title_width = usize::from(display_width(&title));
    if title_width <= inner.saturating_sub(6) {
        let fill = inner.saturating_sub(title_width.saturating_add(6));
        lines.push(Line::from(vec![
            Span::styled("╭── ", Style::default().fg(border)),
            Span::styled(title, Style::default().fg(color)),
            Span::styled(
                format!(" ──{}╮", "─".repeat(fill)),
                Style::default().fg(border),
            ),
        ]));
    } else {
        lines.push(Line::from(Span::styled(
            format!("╭{}╮", "─".repeat(inner)),
            Style::default().fg(border),
        )));
        push_tool_box_row(lines, &title, color, border, inner);
    }
}

/// Splits a bash command into its leading comment lines and the remaining
/// body. A leading comment is a line whose trimmed first character is `#`
/// and that appears before any other line; once the first non-comment line
/// is reached, the rest of the command — interior comments included — stays
/// in the body. Leading comments are trimmed and returned in order.
fn split_leading_comments(command: &str) -> (Vec<String>, &str) {
    let mut leading: Vec<String> = Vec::new();
    let mut body_start = 0usize;
    for chunk in command.split_inclusive('\n') {
        let line = chunk.strip_suffix('\n').unwrap_or(chunk);
        if line.trim_start().starts_with('#') {
            leading.push(line.trim().to_owned());
            body_start += chunk.len();
        } else {
            break;
        }
    }
    (leading, &command[body_start..])
}

/// Top border for a bash card carrying the first leading comment as the
/// title, OMP-style (`╭── # comment ────╮`). The comment is truncated to
/// the border width so the title always fits on the border line; when the
/// card is so narrow that no title fits, a plain top border renders instead.
fn push_bash_comment_top(
    lines: &mut Vec<Line<'static>>,
    comment: &str,
    color: Color,
    border: Color,
    inner: usize,
) {
    let title = truncate_status_text(comment, inner.saturating_sub(6));
    if title.is_empty() {
        lines.push(Line::from(Span::styled(
            format!("╭{}╮", "─".repeat(inner)),
            Style::default().fg(border),
        )));
        return;
    }
    let title_width = usize::from(display_width(&title));
    let fill = inner.saturating_sub(title_width.saturating_add(6));
    lines.push(Line::from(vec![
        Span::styled("╭── ", Style::default().fg(border)),
        Span::styled(title, Style::default().fg(color)),
        Span::styled(
            format!(" ──{}╮", "─".repeat(fill)),
            Style::default().fg(border),
        ),
    ]));
}

/// One additional leading comment rendered as a frame row above the command
/// (`│ # comment │`), truncated to the row width.
fn push_bash_comment_row(
    lines: &mut Vec<Line<'static>>,
    comment: &str,
    color: Color,
    border: Color,
    inner: usize,
) {
    let row = truncate_status_text(comment, inner.saturating_sub(2).max(1));
    let used = usize::from(display_width(&row));
    let fill = " ".repeat(inner.saturating_sub(used.saturating_add(2)));
    lines.push(Line::from(vec![
        Span::styled("│ ", Style::default().fg(border)),
        Span::styled(row, Style::default().fg(color)),
        Span::raw(fill),
        Span::styled(" │", Style::default().fg(border)),
    ]));
}

/// `$ <command>` rendered line-by-line (OMP-style bash card layout). Embedded
/// newlines become separate rows so a multi-line command keeps its original
/// line structure — comment lines (`# …`) included — instead of riding one
/// row as a raw line-feed control character. Leading comment lines are
/// expected to have been extracted by the caller (they render on the card
/// frame); the first row carries the `$` prefix, continuation rows do not,
/// long lines wrap (the first row reserves two columns for `$ `), and a
/// command longer than [`MAX_COMMAND_ROWS`] rows ends with a `…` marker. The
/// card keeps its 20-row total budget.
fn push_bash_command_lines(
    lines: &mut Vec<Line<'static>>,
    command: &str,
    color: Color,
    border: Color,
    inner: usize,
) {
    const MAX_COMMAND_ROWS: usize = 4;
    let inner_text = inner.saturating_sub(2).max(1);
    // Reserve two columns for the `$ ` prefix on the first row only.
    let first_width = inner_text.saturating_sub(2).max(1);
    // Redact + strip terminal control sequences up front; the raw command
    // (with its embedded newlines) stays in the session record.
    let command = clean_terminal_text(&redact_secrets(command));
    let mut rows: Vec<String> = Vec::new();
    let mut truncated = false;
    // Split on newlines first: each logical line wraps on its own, so a
    // multi-line command renders as one row per line. `str::lines` keeps
    // blank interior lines and drops only a single trailing terminator.
    for (logical_index, logical) in command.lines().enumerate() {
        let width = if logical_index == 0 {
            first_width
        } else {
            inner_text
        };
        for (wrap_index, wrapped) in wrap_display_line(logical, width).into_iter().enumerate() {
            if rows.len() >= MAX_COMMAND_ROWS {
                truncated = true;
                break;
            }
            let row = if logical_index == 0 && wrap_index == 0 {
                format!("$ {wrapped}")
            } else {
                wrapped
            };
            rows.push(row);
        }
        if truncated {
            break;
        }
    }
    if rows.is_empty() {
        // Empty command: keep the prompt row so the card still reads as a
        // command card.
        rows.push("$".to_owned());
    } else if truncated {
        // Bounded: keep the first rows and close with the `…` fold marker;
        // the dropped tail stays in the session record.
        rows.truncate(MAX_COMMAND_ROWS - 1);
        rows.push("…".to_owned());
    }
    for row in rows {
        let used = usize::from(display_width(&row));
        let fill = " ".repeat(inner.saturating_sub(used.saturating_add(2)));
        lines.push(Line::from(vec![
            Span::styled("│ ", Style::default().fg(border)),
            Span::styled(row, Style::default().fg(color)),
            Span::raw(fill),
            Span::styled(" │", Style::default().fg(border)),
        ]));
    }
}

fn push_tool_separator(lines: &mut Vec<Line<'static>>, label: &str, border: Color, inner: usize) {
    let fill = "─".repeat(inner.saturating_sub(label.chars().count().saturating_add(2)));
    lines.push(Line::from(vec![
        Span::styled("├──", Style::default().fg(border)),
        Span::styled(label.to_owned(), Style::default().fg(border)),
        Span::styled(fill, Style::default().fg(border)),
        Span::styled("┤", Style::default().fg(border)),
    ]));
}

fn wrap_styled_line(line: Line<'static>, width: usize) -> Vec<Line<'static>> {
    let width = width.max(1);
    if line.spans.is_empty() {
        return vec![Line::default()];
    }
    let mut concatenated = String::new();
    let mut boundaries: Vec<(usize, Style)> = Vec::new();
    for span in line.spans {
        concatenated.push_str(span.content.as_ref());
        boundaries.push((concatenated.len(), span.style));
    }
    if concatenated.is_empty() {
        return vec![Line::default()];
    }
    let style_at = |byte: usize| -> Style {
        for &(end, style) in &boundaries {
            if byte < end {
                return style;
            }
        }
        Style::default()
    };
    let mut rows: Vec<Line<'static>> = Vec::new();
    let mut current_row: Vec<Span<'static>> = Vec::new();
    let mut columns = 0usize;
    let mut byte_index = 0usize;
    let append_span = |spans: &mut Vec<Span<'static>>, text: &str, style: Style| {
        if let Some(last) = spans.last_mut().filter(|span| span.style == style) {
            last.content.to_mut().push_str(text);
        } else {
            spans.push(Span::styled(text.to_owned(), style));
        }
    };
    while byte_index < concatenated.len() {
        let Some(grapheme) = concatenated[byte_index..].graphemes(true).next() else {
            break;
        };
        let grapheme_len = grapheme.len();
        let grapheme_end = byte_index + grapheme_len;
        let grapheme_width = UnicodeWidthStr::width(grapheme);
        if columns > 0 && columns.saturating_add(grapheme_width) > width {
            rows.push(Line::from(std::mem::take(&mut current_row)));
            columns = 0;
        }
        let mut fragment_start = byte_index;
        let mut fragment_style = style_at(byte_index);
        let mut cursor = byte_index;
        while cursor < grapheme_end {
            let mut next_cut = grapheme_end;
            for &(end, _) in &boundaries {
                if end > cursor && end < next_cut {
                    next_cut = end;
                }
            }
            let style = style_at(cursor);
            if style != fragment_style {
                if fragment_start < cursor {
                    append_span(
                        &mut current_row,
                        &concatenated[fragment_start..cursor],
                        fragment_style,
                    );
                }
                fragment_start = cursor;
                fragment_style = style;
            }
            cursor = next_cut;
        }
        if fragment_start < grapheme_end {
            append_span(
                &mut current_row,
                &concatenated[fragment_start..grapheme_end],
                fragment_style,
            );
        }
        columns = columns.saturating_add(grapheme_width);
        byte_index = grapheme_end;
    }
    rows.push(Line::from(current_row));
    rows
}

fn push_tool_box_line(
    lines: &mut Vec<Line<'static>>,
    line: Line<'static>,
    border: Color,
    inner: usize,
) {
    let used = line.width();
    let fill = " ".repeat(inner.saturating_sub(used.saturating_add(2)));
    let mut spans = vec![Span::styled("│ ", Style::default().fg(border))];
    spans.extend(line.spans);
    spans.push(Span::raw(fill));
    spans.push(Span::styled(" │", Style::default().fg(border)));
    lines.push(Line::from(spans));
}
fn push_tool_box_row(
    lines: &mut Vec<Line<'static>>,
    text: &str,
    color: Color,
    border: Color,
    inner: usize,
) {
    for row in wrap_display_line(&clean_terminal_text(text), inner.saturating_sub(2).max(1)) {
        let used = usize::from(display_width(&row));
        let fill = " ".repeat(inner.saturating_sub(used.saturating_add(2)));
        lines.push(Line::from(vec![
            Span::styled("│ ", Style::default().fg(border)),
            Span::styled(row, Style::default().fg(color)),
            Span::raw(fill),
            Span::styled(" │", Style::default().fg(border)),
        ]));
    }
}

/// Render untrusted tool/bash output text as width-wrapped styled lines.
///
/// The one-pass ANSI parser ([`crate::ansi::parse_ansi_runs`]) turns SGR runs
/// into styled spans; newlines split into separate card rows (matching the
/// previous plain-text flattening), with SGR state carrying across the split
/// so a color opened on one logical line continues onto the next. Each row is
/// then wrapped with the existing width-safe wrapper and is ready for
/// [`push_tool_box_line`]. Titles, arguments, and metadata still go through
/// `clean_terminal_text` plain text; only this output path is styled.
///
/// Redaction is FAIL-CLOSED: the raw input is parsed first and the full
/// plain text is then redacted. If redaction changed anything, a credential
/// shape was present — possibly split across an SGR boundary in the raw
/// input — so the whole row collapses to one base-style plain run of the
/// redacted text; styled spans can never carry a secret.
fn ansi_styled_lines(text: &str, base: Style, width: usize) -> Vec<Line<'static>> {
    // `str::lines` drops a single trailing newline; mirror that so the styled
    // path renders the same rows as the old plain flattening.
    let text = text.strip_suffix('\n').unwrap_or(text);
    let runs = parse_ansi_runs(text);
    let plain: String = runs.iter().map(|run| run.text.as_str()).collect();
    let redacted = redact_secrets(&plain);
    let styled: Vec<(String, Style)> = if redacted != plain {
        if redacted.is_empty() {
            return Vec::new();
        }
        vec![(redacted, base)]
    } else {
        runs.into_iter()
            .map(|run| {
                let mut style = base;
                if let Some(fg) = run.fg {
                    style = style.fg(fg);
                }
                if let Some(bg) = run.bg {
                    style = style.bg(bg);
                }
                style = style.add_modifier(run.modifier);
                (run.text, style)
            })
            .collect()
    };
    let mut rows: Vec<Line<'static>> = Vec::new();
    let mut current_row: Vec<Span<'static>> = Vec::new();
    let mut saw_text = false;
    for (text, style) in styled {
        if text.is_empty() {
            continue;
        }
        saw_text = true;
        let mut segments = text.split('\n');
        if let Some(first) = segments.next() {
            if !first.is_empty() {
                current_row.push(Span::styled(first.to_owned(), style));
            }
        }
        for segment in segments {
            rows.push(Line::from(std::mem::take(&mut current_row)));
            if !segment.is_empty() {
                current_row.push(Span::styled(segment.to_owned(), style));
            }
        }
    }
    if !saw_text {
        return Vec::new();
    }
    rows.push(Line::from(current_row));
    rows.into_iter()
        .flat_map(|line| wrap_styled_line(line, width.max(1)))
        .collect()
}

fn transcript_block_has_content(block: &ContentBlock) -> bool {
    match block {
        ContentBlock::Text { text, .. } => !text.trim().is_empty(),
        ContentBlock::Thinking {
            thinking, redacted, ..
        } => !redacted && !thinking.trim().is_empty(),
        ContentBlock::Image { .. } | ContentBlock::ToolCall(_) => true,
    }
}

const ACTIVE_ANIMATION_FRAMES: &[&str] = &["◐", "◓", "◑", "◒"];
const ACTIVE_JOB_PREFIXES: &[&str] = &["Task ◐ ", "Task ◓ ", "Task ◑ ", "Task ◒ "];

/// Bound on the auto-vision analysis description shown inside a user card.
/// The Web renders it in a collapsed `<details>`; the TUI shows a bounded
/// fold card — the first rows plus an ellipsis marker, the full description
/// stays in the session record. Mirrors the tool-card output fold.
const IMAGE_ANALYSIS_LINE_LIMIT: usize = 6;

/// Maximum rows one user text block may render in the transcript. A large
/// pasted/fenced block (up to the 1 MiB `MAX_PASTE_BYTES` ceiling) would
/// otherwise materialize one row per payload line into the render buffer
/// every frame; the card keeps a bounded head plus a fold marker, and the
/// final row cap reserves slots for the optional frame bottom and the marker
/// so kept head + frame bottom + marker never exceed this limit (Web
/// large-paste-preview parity). Storage keeps the full text — only the
/// rendered card is bounded.
const USER_CARD_RENDER_ROW_LIMIT: usize = 120;

/// Maximum source lines of one user text block fed to the line-driven
/// markdown renderer. The fold applies it only over the byte-bounded head
/// ([`USER_CARD_TEXT_CHAR_BUDGET`] first), so the renderer never walks more
/// than this many lines AND never scans the payload tail to count them —
/// the omitted-line count is known exactly only when the head holds the
/// whole (at most 16 KiB) text.
const USER_CARD_TEXT_LINE_BUDGET: usize = 120;

/// Maximum bytes of one user text block's rendering head, regardless of
/// source-line count. The line budget alone cannot bound a megabyte block
/// that arrives as ONE line (a paste with no newlines): a line scan would
/// walk the whole payload, which would then survive into the cleaner and
/// the line-driven markdown pass and inflate to thousands of painted rows
/// during the grapheme re-wrap. So this budget is the FIRST cut, applied to
/// the raw text before any full-payload line scan, count, join, or markdown
/// work: it takes a grapheme-safe prefix (never splitting a multi-byte UTF-8
/// sequence or grapheme cluster) and the unbounded tail is never walked.
/// Bytes are the conservative unit — every grapheme is at least one byte,
/// so a byte cap is always a grapheme cap — and 16 KiB is comfortably above
/// any realistic multi-line message (the 120-line budget at 80 chars/line is
/// ~9.6 KiB), so normal content is unaffected.
const USER_CARD_TEXT_CHAR_BUDGET: usize = 16 * 1024;

/// The exact wire marker the backend's vision-delegation path emits when an
/// active model lacks image support and a vision model is configured: one
/// text block `[Image analyzed by {model}: {description}]` replaces the image
/// blocks in the MODEL context only (crates/pi-coding/src/session.rs
/// `delegate_vision_images_with`). The durable history keeps the ORIGINAL
/// images; when the marker does reach the client it is a legacy/old-binary or
/// transport artifact, never the user's own text. Recognized structurally —
/// the whole trimmed block must match — so a user who types a similar-looking
/// line is never misclassified (their caption survives verbatim). Mirrors the
/// Web `IMAGE_ANALYSIS_RE` (same lazy-model / greedy-description semantics).
///
/// Returns `(model, description)`.
fn parse_image_analysis(text: &str) -> Option<(&str, &str)> {
    let trimmed = text.trim();
    let rest = trimmed.strip_prefix("[Image analyzed by ")?;
    // The model is the shortest run up to the first `: ` (`.+?` in the Web
    // regex); the description is everything up to the final `]` (`.+` with
    // dotall, so newlines and `]` inside the description survive).
    let colon = rest.find(": ")?;
    let model = &rest[..colon];
    let description = &rest[colon + 2..];
    let close = description.rfind(']')?;
    if close + 1 != description.len() || model.is_empty() || description[..close].trim().is_empty()
    {
        return None;
    }
    Some((model, &description[..close]))
}

/// A legacy attachment-transport wrapper block: a text block that is ENTIRELY
/// a balanced `<attachment ...>...</attachment>` (or self-closing
/// `<attachment .../>`) XML element. Old binaries wrapped image transport in
/// this scaffolding; current code never emits it. Recognized structurally
/// (balanced tags over the whole block, mirroring the Web
/// `ATTACHMENT_WRAPPER_RE`/`ATTACHMENT_SELF_CLOSE_RE`) so a user who literally
/// types `<attachment>` as their message is preserved — the strip only applies
/// when the message also carries real image blocks, proving an attachment was
/// actually transported.
fn is_attachment_wrapper(text: &str) -> bool {
    // The Web regexes tolerate trailing whitespace only (`\s*$`); leading
    // whitespace would break the anchored `^<attachment`.
    let text = text.trim_end();
    let lower = text.to_ascii_lowercase();
    let Some(rest) = lower.strip_prefix("<attachment") else {
        return false;
    };
    // `<attachment` must be the complete tag name: what follows is `>`, `/>`,
    // or whitespace-led attributes. `<attachments>`/`<attachment-foo>` are a
    // different element and never transport wrappers.
    if let Some(after_open) = rest.strip_prefix('>') {
        return after_open.ends_with("</attachment>");
    }
    if let Some(after_self_close) = rest.strip_prefix("/>") {
        return after_self_close.is_empty();
    }
    if rest.starts_with(char::is_whitespace) {
        // Attribute section: everything up to the first `>` (Web `[^>]*`).
        let Some(gt) = rest.find('>') else {
            return false;
        };
        // Self-closing `<attachment …/>`: the attrs end with `/` and nothing
        // follows the closing `>` (trailing whitespace was already trimmed).
        // A `/` inside the attribute span (e.g. `<attachment src="a/>b">…`)
        // is NOT a self-close — fall through to the balanced-wrapper check.
        if rest[..gt].ends_with('/') && rest[gt + 1..].is_empty() {
            return true;
        }
        return rest[gt + 1..].ends_with("</attachment>");
    }
    false
}

/// Typed projection of a USER message's content blocks for transcript
/// rendering — parity with the Web's `userMessageProjection`
/// (web/src/transcript.ts) so both surfaces show the same user-visible
/// semantics: the user's real caption, real image previews (never reordered),
/// and an optional auto-vision analysis. Computed once over the WHOLE message
/// so the wrapper-strip decision sees every image block — a transport wrapper
/// before OR after the images is dropped the same way.
///
/// The renderer consumes the typed groups in the Web user-bubble order:
/// `images` (relative order preserved) first, then `caption` (text-relative
/// order preserved), then the `analysis` card — a caption that precedes its
/// image in the content blocks never renders above the preview.
struct UserMessageProjection<'a> {
    /// Real image blocks, in their original content order.
    images: Vec<&'a ContentBlock>,
    /// Text blocks that are genuinely the user's caption (transport
    /// scaffolding excluded), in their original content order.
    caption: Vec<&'a ContentBlock>,
    /// Non-text, non-image blocks (defensive — user messages are text+image
    /// by construction), in their original content order.
    other: Vec<&'a ContentBlock>,
    /// First vision-delegation marker as `(model, description)` — the backend
    /// emits one description for all images; later markers are ignored.
    analysis: Option<(&'a str, &'a str)>,
}

impl<'a> UserMessageProjection<'a> {
    fn new(content: &'a [ContentBlock]) -> Self {
        // First pass: collect the real image blocks so the wrapper-strip
        // decision is based on whether the WHOLE message carried a real
        // attachment transport, not on whether an image block happened to
        // precede the wrapper text.
        let images = content
            .iter()
            .filter(|block| matches!(block, ContentBlock::Image { .. }))
            .collect::<Vec<_>>();
        let mut caption = Vec::new();
        let mut other = Vec::new();
        let mut analysis = None;
        for block in content {
            match block {
                ContentBlock::Image { .. } => {}
                ContentBlock::Text { text, .. } => {
                    if let Some(parsed) = parse_image_analysis(text) {
                        // The first marker becomes the typed analysis; later
                        // markers are dropped, never kept as caption.
                        if analysis.is_none() {
                            analysis = Some(parsed);
                        }
                        continue;
                    }
                    if is_attachment_wrapper(text) && !images.is_empty() {
                        // A structurally-provable <attachment> wrapper is
                        // transport scaffolding (a reference marker / image
                        // transport envelope), never the user's own text —
                        // dropped entirely. The user's real caption lives in
                        // the other (non-wrapper) text blocks.
                        continue;
                    }
                    caption.push(block);
                }
                _ => other.push(block),
            }
        }
        Self {
            images,
            caption,
            other,
            analysis,
        }
    }

    /// Whether a text block is transport scaffolding and must never render as
    /// the user's own caption: the backend's `[Image analyzed by …]` marker,
    /// or — when the message carried real image blocks — a structurally
    /// provable `<attachment>` wrapper (its inner text is transport
    /// scaffolding, not the user's caption).
    fn is_transport_text(&self, text: &str) -> bool {
        parse_image_analysis(text).is_some()
            || (!self.images.is_empty() && is_attachment_wrapper(text))
    }
}

/// The auto-vision analysis card inside a user card, mirroring the Web's
/// `<details class="msg--user__analysis">` (summary "Image analysis" + model,
/// body = description). The description is a generated surface, so it obeys
/// the TUI bounded/redaction invariant: sanitized, redacted, and folded to
/// `IMAGE_ANALYSIS_LINE_LIMIT` rows with an ellipsis marker.
fn render_image_analysis_card(
    lines: &mut Vec<Line<'static>>,
    model: &str,
    description: &str,
    theme: Theme,
    width: u16,
) {
    let inner = usize::from(width.saturating_sub(2).max(1));
    let border = theme.tool_card_border;
    let title = format!(
        "Image analysis · {}",
        clean_terminal_text(&redact_secrets(model))
    );
    push_tool_card_top(lines, &title, theme.custom_message_label, border, inner);
    let body = clean_terminal_text(&redact_secrets(description));
    let mut rows = body
        .lines()
        .flat_map(|line| wrap_display_line(line, inner.saturating_sub(2).max(1)))
        .collect::<Vec<_>>();
    let omitted = rows.len().saturating_sub(IMAGE_ANALYSIS_LINE_LIMIT);
    if omitted > 0 {
        rows.truncate(IMAGE_ANALYSIS_LINE_LIMIT);
    }
    for row in &rows {
        push_tool_box_row(lines, row, theme.dim, border, inner);
    }
    if omitted > 0 {
        push_tool_box_row(
            lines,
            &format!("… {omitted} more lines"),
            theme.dim,
            border,
            inner,
        );
    }
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(inner)),
        Style::default().fg(border),
    )));
}

fn push_compaction_divider(lines: &mut Vec<Line<'static>>, theme: Theme, width: u16) {
    let inner = usize::from(width.max(1));
    let label = " compacted ";
    let label_width = grapheme_display_width(label).max(1);
    if inner <= label_width {
        lines.push(Line::from(Span::styled(
            fit_text("─", inner),
            Style::default().fg(theme.dim),
        )));
        return;
    }
    let remainder = inner - label_width;
    let left = remainder / 2;
    let right = remainder - left;
    let mut row = String::new();
    row.push_str(&"─".repeat(left));
    row.push_str(label);
    row.push_str(&"─".repeat(right));
    lines.push(Line::from(Span::styled(
        row,
        Style::default().fg(theme.dim),
    )));
}

fn render_transcript_entry_inner(
    lines: &mut Vec<Line<'static>>,
    entry: &TranscriptEntry,
    show_thinking: bool,
    expand_tools: bool,
    theme: Theme,
    width: u16,
    animation_frame: usize,
    mut image_context: Option<&mut TranscriptImageContext<'_>>,
) {
    if entry.kind == TranscriptKind::Tool {
        if let Some(tool) = &entry.tool_card {
            render_tool_card(lines, tool, expand_tools, theme, width);
        }
        return;
    }
    if !entry.content.iter().any(|block| match block {
        ContentBlock::Thinking { .. } => show_thinking && transcript_block_has_content(block),
        _ => transcript_block_has_content(block),
    }) {
        return;
    }
    let (label, label_color, background) = match entry.kind {
        TranscriptKind::User => (None, theme.accent, Some(theme.user_message_bg)),
        TranscriptKind::Assistant => (None, theme.success, None),
        TranscriptKind::System => {
            let compaction = entry.tool_name.as_deref() == Some("Compaction summary");
            (
                if compaction {
                    None
                } else {
                    Some(entry.tool_name.as_deref().unwrap_or(if entry.is_error {
                        "Error"
                    } else {
                        "System"
                    }))
                },
                if entry.is_error {
                    theme.error
                } else {
                    theme.custom_message_label
                },
                None,
            )
        }
        TranscriptKind::Custom => (
            Some(entry.tool_name.as_deref().unwrap_or("Custom")),
            theme.custom_message_label,
            None,
        ),
        TranscriptKind::Tool => {
            unreachable!("specialized transcript entries return before generic rendering")
        }
    };
    if entry.kind == TranscriptKind::System
        && entry.tool_name.as_deref() == Some("Compaction summary")
    {
        push_compaction_divider(lines, theme, width);
    }
    if let Some(label) = label {
        lines.push(Line::from(Span::styled(
            format!(
                "{} ·",
                fit_text(
                    &clean_terminal_text(label),
                    usize::from(width.max(1)).saturating_sub(2)
                )
            ),
            Style::default().fg(label_color),
        )));
    }
    let entry_content_start = lines.len();
    if entry.kind == TranscriptKind::User {
        lines.push(user_card_vertical_padding(width));
    }
    // Typed projection for USER entries (parity with the Web
    // `userMessageProjection`): computed once over the WHOLE message so the
    // wrapper-strip decision sees every image block — a transport wrapper
    // before OR after the images is dropped the same way.
    let user_projection =
        (entry.kind == TranscriptKind::User).then(|| UserMessageProjection::new(&entry.content));
    // Web user-bubble parity: a USER bubble renders its real images first
    // (relative order preserved), then the real caption text (text-relative
    // order preserved), then the analysis card — a caption that precedes its
    // image in the content blocks never renders above the preview.
    // Assistant paint: thinking first (relative order), then other blocks.
    let ordered_blocks: Vec<&ContentBlock> = match &user_projection {
        Some(projection) => projection
            .images
            .iter()
            .copied()
            .chain(projection.caption.iter().copied())
            .chain(projection.other.iter().copied())
            .collect(),
        None if entry.kind == TranscriptKind::Assistant => entry
            .content
            .iter()
            .filter(|block| matches!(block, ContentBlock::Thinking { .. }))
            .chain(
                entry
                    .content
                    .iter()
                    .filter(|block| !matches!(block, ContentBlock::Thinking { .. })),
            )
            .collect(),
        None => entry.content.iter().collect(),
    };
    let mut visible_blocks = 0_usize;
    let mut previous_was_thinking = false;
    for block in &ordered_blocks {
        match block {
            ContentBlock::Text { text, .. } => {
                if text.trim().is_empty() {
                    continue;
                }
                if previous_was_thinking {
                    lines.push(Line::default());
                }
                let base = match entry.kind {
                    TranscriptKind::User => theme.user_message_text,
                    TranscriptKind::System => {
                        if entry.is_error {
                            theme.error
                        } else {
                            theme.custom_message_text
                        }
                    }
                    TranscriptKind::Custom => theme.custom_message_text,
                    TranscriptKind::Assistant => theme.text,
                    TranscriptKind::Tool => {
                        unreachable!(
                            "specialized transcript entries return before generic text rendering"
                        )
                    }
                };
                let rendered = if entry.kind == TranscriptKind::User {
                    // Bounded projection for the user card: a large
                    // pasted/fenced block (up to the `MAX_PASTE_BYTES`
                    // ceiling) is cut to a grapheme-safe byte-bounded head
                    // FIRST — before any full-payload line scan, count,
                    // join, sanitize, or markdown work — then folded by the
                    // line budget over that bounded head. The final row cap
                    // reserves slots for the optional frame bottom and the
                    // fold marker so kept head + frame bottom + marker never
                    // exceed `USER_CARD_RENDER_ROW_LIMIT`, and the marker
                    // reports what the bounded work actually knows (byte-cut
                    // content as `… more content`, folded source lines as
                    // `… N more lines`, capped painted rows as `… N more
                    // rows`). Storage keeps the full text in the session
                    // record.
                    let (head, fold_omission) =
                        fold_user_text_head(text, USER_CARD_TEXT_LINE_BUDGET);
                    let sanitized = clean_terminal_text(&head);
                    let markdown_lines = render_markdown(&sanitized, theme, base, width);
                    let mut wrapped = render_user_card_lines(markdown_lines, width);
                    let painted_omitted = bound_user_card_rendered_rows(
                        &mut wrapped,
                        theme,
                        width,
                        fold_omission.any(),
                    );
                    if let Some(marker) = user_card_fold_marker(fold_omission, painted_omitted) {
                        wrapped.push(Line::from(Span::styled(
                            marker,
                            Style::default().fg(theme.dim),
                        )));
                    }
                    wrapped
                } else {
                    let sanitized = clean_terminal_text(text);
                    render_transcript_markdown(&sanitized, theme, base, width, entry.is_partial)
                };
                lines.extend(rendered);
                visible_blocks += 1;
                previous_was_thinking = false;
            }
            ContentBlock::Thinking {
                thinking, redacted, ..
            } => {
                if !show_thinking || *redacted || thinking.trim().is_empty() {
                    continue;
                }
                let mut rendered = render_transcript_markdown(
                    &clean_terminal_text(thinking),
                    theme,
                    theme.thinking_text,
                    width,
                    entry.is_partial,
                );
                // OMP forces every span inside a thinking block through
                // `thinkingText` (assistant-message.ts color transform): the
                // markdown chrome colors (headings/links/list bullets/code)
                // are suppressed so a numbered list or heading inside a
                // thinking trace never renders in accent blue. Structural
                // modifiers (bold/italic/underline) survive the transform.
                for line in &mut rendered {
                    line.style = line
                        .style
                        .fg(theme.thinking_text)
                        .add_modifier(Modifier::ITALIC);
                    for span in &mut line.spans {
                        span.style = span
                            .style
                            .fg(theme.thinking_text)
                            .add_modifier(Modifier::ITALIC);
                    }
                }
                lines.extend(rendered);
                visible_blocks += 1;
                previous_was_thinking = true;
            }
            ContentBlock::Image { data, mime_type } => {
                let layout = image_context.as_deref_mut().and_then(|context| {
                    context.renderer.layout(
                        data,
                        mime_type,
                        context.config,
                        context.viewport_columns,
                        context.viewport_rows,
                        context.cell_size,
                    )
                });
                if let (Some(layout), Some(context)) = (layout, image_context.as_deref_mut()) {
                    let line_index = lines.len();
                    lines.extend((0..layout.rows()).map(|_| Line::default()));
                    context.candidates.push(TranscriptImageCandidate {
                        line_index,
                        layout,
                        data: data.clone(),
                        mime_type: mime_type.clone(),
                    });
                } else {
                    // Bounded fallback: the MIME label is sanitized, redacted,
                    // and wrapped so a legacy/hostile MIME string can never
                    // overflow the width as a single row.
                    let label = format!(
                        "[image attachment: {}]",
                        clean_terminal_text(&redact_secrets(mime_type))
                    );
                    for row in
                        wrap_display_line(&label, usize::from(width.saturating_sub(1).max(1)))
                    {
                        lines.push(Line::from(Span::styled(
                            row,
                            Style::default().fg(theme.muted),
                        )));
                    }
                }
                visible_blocks += 1;
            }
            ContentBlock::ToolCall(call) => {
                lines.push(Line::from(vec![
                    Span::styled(
                        format!("{} ", clean_terminal_text(&redact_secrets(&call.name))),
                        Style::default()
                            .fg(theme.tool_title)
                            .add_modifier(Modifier::BOLD),
                    ),
                    Span::styled(
                        clean_terminal_text(&redact_secrets(&compact_arguments(&call.arguments))),
                        Style::default().fg(theme.tool_output),
                    ),
                ]));
                visible_blocks += 1;
            }
        }
    }
    // The typed auto-vision analysis renders as its own clearly-marked fold
    // card (never as the user's caption) after the user's real content.
    if let Some(projection) = &user_projection {
        if let Some((model, description)) = projection.analysis {
            render_image_analysis_card(lines, model, description, theme, width);
            visible_blocks += 1;
        }
    }
    if visible_blocks > 0 {
        if entry.kind == TranscriptKind::User {
            lines.push(user_card_vertical_padding(width));
        }
        if let Some(background) = background {
            for line in &mut lines[entry_content_start..] {
                line.style = line.style.bg(background);
                for span in &mut line.spans {
                    span.style = span.style.bg(background);
                }
            }
        }
    }
    // Assistant replies must not emit a trailing blank row: the adjacency
    // assembler inserts the single inter-entry separator between distinct
    // entries (or reuses a user card's bottom edge as that separator), so
    // the final reply ends flush on its last content line instead of
    // leaving an empty row below it.
}

fn user_card_vertical_padding(width: u16) -> Line<'static> {
    Line::from(Span::raw(" ".repeat(usize::from(width.max(1)))))
}

/// Omission facts learned by the bounded user-card fold. Line counts are
/// only ever computed over the byte-bounded head (at most
/// [`USER_CARD_TEXT_CHAR_BUDGET`] bytes); the payload tail is never scanned
/// to count what the byte cut hid, so that omission is reported as a boolean
/// instead of a fabricated line count.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct FoldOmission {
    /// True when the byte budget cut the head: the tail's size is known but
    /// its line structure is not without a full scan, so the fold marker
    /// says `… more content` rather than a count.
    bytes: bool,
    /// Source lines cut by the line budget over the bounded head. Exact when
    /// the head holds the whole text (no byte cut); merely informational
    /// when the byte budget cut first (the tail's lines are uncounted).
    lines: usize,
}

impl FoldOmission {
    const NONE: FoldOmission = FoldOmission {
        bytes: false,
        lines: 0,
    };

    fn any(self) -> bool {
        self.bytes || self.lines > 0
    }
}

/// Builds the truthful fold marker for a user card: `… more content` when
/// the byte budget cut the head (the omitted tail's line count is unknown
/// without scanning it), `… N more lines` when the line budget folded a
/// known number of source lines over the bounded head, and `… N more rows`
/// when the final row cap dropped exactly N painted rows (the count always
/// matches the dropped painted rows). Returns `None` when nothing was
/// omitted.
fn user_card_fold_marker(omission: FoldOmission, painted_omitted: usize) -> Option<String> {
    if omission.bytes {
        return Some("… more content".to_owned());
    }
    if omission.lines > 0 {
        return Some(format!("… {} more lines", omission.lines));
    }
    if painted_omitted > 0 {
        return Some(format!("… {painted_omitted} more rows"));
    }
    None
}

/// Folds a user text block to a bounded head for rendering. The text is
/// FIRST cut to at most [`USER_CARD_TEXT_CHAR_BUDGET`] bytes at a grapheme
/// boundary — before any full-payload line scan, count, or join — so a
/// megabyte newline-free paste is never walked in full; only then is the
/// line budget applied over that bounded head (at most `line_budget` source
/// lines, each counted without touching the tail). A fence left open at the
/// cut is closed synthetically so `render_markdown` always emits a real
/// frame bottom. Returns the head text and the omission facts learned from
/// the bounded work. Only the rendered card is bounded — the session record
/// keeps the full text.
fn fold_user_text_head(text: &str, line_budget: usize) -> (Cow<'_, str>, FoldOmission) {
    // Byte-bound first: a grapheme-safe prefix of at most
    // USER_CARD_TEXT_CHAR_BUDGET bytes. The grapheme scan is lazy and stops
    // at the budget, so the unbounded tail is never walked.
    let (prefix, cut) = truncate_head_graphemes(text, USER_CARD_TEXT_CHAR_BUDGET);
    // Line fold over the bounded prefix only: `lines.count()` walks at most
    // USER_CARD_TEXT_CHAR_BUDGET bytes, never the payload tail.
    let mut lines = prefix.lines();
    let head: Vec<&str> = lines.by_ref().take(line_budget).collect();
    let remaining = lines.count();
    if cut.is_none() && remaining == 0 {
        return (Cow::Borrowed(text), FoldOmission::NONE);
    }
    let mut fenced = false;
    for line in &head {
        if line.trim_start().starts_with("```") {
            fenced = !fenced;
        }
    }
    let mut out = head.join("\n");
    if fenced {
        // The fold cut inside a fence: close it so the frame renders a real
        // bottom instead of leaving body rows dangling.
        out.push_str("\n```");
    }
    (
        Cow::Owned(out),
        FoldOmission {
            bytes: cut.is_some(),
            lines: remaining,
        },
    )
}

/// Truncates `text` to at most `budget` bytes at a grapheme boundary, so a
/// multi-byte UTF-8 sequence or grapheme cluster is never split. The
/// grapheme scan is lazy and stops at the budget, so the unbounded tail of a
/// megabyte paste is never walked. Returns the bounded head and, when a cut
/// happened, the byte offset of the cut (the caller uses `is_some` to flag
/// byte-cut omission; it never counts the uncounted tail). Every grapheme is
/// at least one byte, so a byte fit is always a grapheme fit.
fn truncate_head_graphemes(text: &str, budget: usize) -> (Cow<'_, str>, Option<usize>) {
    if text.len() <= budget {
        return (Cow::Borrowed(text), None);
    }
    let mut cut = text.len();
    for (start, grapheme) in text.grapheme_indices(true) {
        if start + grapheme.len() > budget {
            cut = start;
            break;
        }
    }
    if cut == text.len() {
        return (Cow::Borrowed(text), None);
    }
    (Cow::Owned(text[..cut].to_owned()), Some(cut))
}

/// Bounds a user card's painted rows in place so the final card — kept
/// head, optional frame bottom, and fold marker — never exceeds
/// [`USER_CARD_RENDER_ROW_LIMIT`] rows. When `marker_reserved` (any bounded
/// fold omission exists) or the cap itself must drop rows, a fold marker
/// will be shown, so the cap keeps at most `LIMIT - 1` original rows and
/// reserves one more slot for a synthetic frame bottom when the cut lands
/// inside an open code fence (no side-bordered row may dangle). Returns the
/// exact number of ORIGINAL painted rows dropped — the count the fold
/// marker reports as `… N more rows`. The full payload stays in the session
/// record.
fn bound_user_card_rendered_rows(
    rendered: &mut Vec<Line<'static>>,
    theme: Theme,
    width: u16,
    marker_reserved: bool,
) -> usize {
    // Nothing to drop and no marker coming: leave the card untouched.
    if rendered.len() <= USER_CARD_RENDER_ROW_LIMIT && !marker_reserved {
        return 0;
    }
    // From here a fold marker will be shown (one already exists from the
    // bounded fold, or this cap is about to create one), so the cap leaves
    // one slot for it and one more for a frame bottom when the cut lands
    // inside an open fence.
    let keep_base = USER_CARD_RENDER_ROW_LIMIT - 1;
    let cut_inside_fence = rendered.len() > keep_base
        && (rendered
            .get(keep_base.saturating_sub(1))
            .is_some_and(is_fence_body_row)
            || rendered.get(keep_base).is_some_and(is_fence_body_row));
    let keep = keep_base - usize::from(cut_inside_fence);
    let omitted = rendered.len().saturating_sub(keep);
    rendered.truncate(keep);
    if cut_inside_fence {
        // The cut landed inside a fenced block: cap the frame with a real
        // bottom border (the same shape `render_markdown` emits for a closed
        // fence) so the head never dangles side-bordered rows.
        let frame_width = usize::from(width.max(1)).saturating_sub(1).max(1);
        rendered.push(Line::from(Span::styled(
            format!("╰{}╯", "─".repeat(frame_width.saturating_sub(2))),
            Style::default().fg(theme.tool_card_border),
        )));
    }
    omitted
}

/// A `render_markdown` code-frame body row: `│ … │`. These are the only rows
/// with a trailing side border (blockquote rows start with `│ ` but never
/// end with one), so this detects a fold cut that lands inside an open
/// fence. The user-card re-wrap appends one trailing padding cell to every
/// painted row, so the trailing border is matched after trimming that.
fn is_fence_body_row(line: &Line<'_>) -> bool {
    let mut text = String::new();
    for span in &line.spans {
        text.push_str(span.content.as_ref());
    }
    text.starts_with("│ ") && text.trim_end().ends_with(" │")
}

fn render_user_card_lines(rendered: Vec<Line<'static>>, width: u16) -> Vec<Line<'static>> {
    let width = usize::from(width.max(1));
    let trailing_padding = usize::from(width > 1);
    let content_width = width.saturating_sub(trailing_padding).max(1);
    let mut rows = Vec::new();

    for line in rendered {
        let line_style = line.style;
        // A row that already fits the content band by display width is passed
        // through untouched. Re-wrapping only wider rows keeps finished frame
        // rows (code fences, tables) intact instead of splitting a correct
        // frame row mid-frame.
        let line_width = line
            .spans
            .iter()
            .map(|span| UnicodeWidthStr::width(span.content.as_ref()))
            .sum::<usize>();
        if line_width <= content_width {
            push_user_card_row(&mut rows, line.spans, line_width, width, line_style);
            continue;
        }
        // Wide rows are re-wrapped grapheme by grapheme; a cluster is never
        // split, so multi-code-point graphemes (flags, ZWJ families) stay
        // intact and count their true terminal width.
        let mut row_spans = Vec::<Span<'static>>::new();
        let mut row_width = 0_usize;
        for span in line.spans {
            for grapheme in span.content.graphemes(true) {
                let grapheme_width = UnicodeWidthStr::width(grapheme);
                if row_width > 0 && row_width.saturating_add(grapheme_width) > content_width {
                    push_user_card_row(
                        &mut rows,
                        std::mem::take(&mut row_spans),
                        row_width,
                        width,
                        line_style,
                    );
                    row_width = 0;
                }
                if let Some(last) = row_spans.last_mut().filter(|last| last.style == span.style) {
                    last.content.to_mut().push_str(grapheme);
                } else {
                    row_spans.push(Span::styled(grapheme.to_owned(), span.style));
                }
                row_width = row_width.saturating_add(grapheme_width);
            }
        }
        push_user_card_row(&mut rows, row_spans, row_width, width, line_style);
    }

    rows
}

fn push_user_card_row(
    rows: &mut Vec<Line<'static>>,
    content: Vec<Span<'static>>,
    content_width: usize,
    width: usize,
    line_style: Style,
) {
    let mut spans = Vec::with_capacity(content.len().saturating_add(1));
    spans.extend(content);
    let trailing_band = width.saturating_sub(content_width);
    if trailing_band > 0 {
        spans.push(Span::raw(" ".repeat(trailing_band)));
    }
    rows.push(Line::from(spans).style(line_style));
}

const SESSION_SELECTOR_MAX_HEIGHT: u16 = 22;
const SESSION_SELECTOR_HEIGHT_OVERHEAD: usize = 6;

fn saved_session_preview_lines(
    row: &ResumeSelectorRow,
    marker: &str,
    show_path: bool,
    max_lines: usize,
) -> Vec<String> {
    if max_lines == 0 {
        return Vec::new();
    }
    let badge = clean_terminal_text(row.source_badge).replace('\n', " ");
    let preview = clean_terminal_text(session_display_name(row));
    let path = if show_path {
        format!(
            " · {}",
            clean_terminal_text(&row.path.display().to_string()).replace('\n', " ")
        )
    } else {
        String::new()
    };
    let count = row.message_count.map_or_else(
        || "? messages".to_owned(),
        |count| format!("{count} messages"),
    );
    let imported = matches!(
        &row.status,
        pi_coding::CatalogRowStatus::AlreadyImported { .. }
    )
    .then_some(" · imported")
    .unwrap_or_default();
    let mut logical_lines = preview.split('\n');
    let first = logical_lines.next().unwrap_or_default();
    let mut lines = Vec::with_capacity(max_lines.min(4));
    lines.push(format!(
        "{marker} [{badge}] {first} · {count}{imported}{path}"
    ));
    lines.extend(
        logical_lines
            .take(max_lines.saturating_sub(1))
            .map(|line| format!("  {line}")),
    );
    lines
}

fn sanitized_logical_line_count(text: &str, max_lines: usize) -> usize {
    if max_lines == 0 {
        return 0;
    }
    if max_lines == 1 {
        return 1;
    }
    let mut lines = 1;
    let mut characters = text.chars().peekable();
    while let Some(character) = characters.next() {
        if character == '\u{1b}' {
            match characters.next() {
                Some('[') => {
                    for value in characters.by_ref() {
                        if ('@'..='~').contains(&value) {
                            break;
                        }
                    }
                }
                Some(']') => {
                    while let Some(value) = characters.next() {
                        if value == '\u{7}' {
                            break;
                        }
                        if value == '\u{1b}' && characters.peek() == Some(&'\\') {
                            characters.next();
                            break;
                        }
                    }
                }
                Some(_) | None => {}
            }
        } else if character == '\n' {
            lines += 1;
            if lines == max_lines {
                break;
            }
        }
    }
    lines
}

fn saved_session_preview_line_count(row: &ResumeSelectorRow, max_lines: usize) -> usize {
    sanitized_logical_line_count(session_display_name(row), max_lines)
}

fn saved_session_viewport_start(selector: &SavedSessionSelector, row_line_budget: usize) -> usize {
    let mut start = selector.selected();
    let Some(selected) = selector.visible_row(start) else {
        return 0;
    };
    let selected_lines =
        saved_session_preview_line_count(selected, row_line_budget.saturating_add(1));
    if selected_lines > row_line_budget {
        return start;
    }
    let mut used = selected_lines;
    while start > 0 && used < row_line_budget {
        let remaining = row_line_budget - used;
        let Some(previous) = selector.visible_row(start - 1) else {
            break;
        };
        let previous_lines = saved_session_preview_line_count(previous, remaining + 1);
        if previous_lines > remaining {
            break;
        }
        start -= 1;
        used += previous_lines;
    }
    start
}

fn saved_session_preferred_preview_lines(selector: &SavedSessionSelector) -> usize {
    let max_preview_lines =
        usize::from(SESSION_SELECTOR_MAX_HEIGHT).saturating_sub(SESSION_SELECTOR_HEIGHT_OVERHEAD);
    let mut total = 0;
    for (_, row) in selector.visible_window(0, max_preview_lines) {
        let remaining = max_preview_lines - total;
        total += saved_session_preview_line_count(row, remaining);
        if total == max_preview_lines {
            break;
        }
    }
    total
}

fn saved_session_selector_lines(
    selector: &SavedSessionSelector,
    theme: Theme,
    content_line_budget: usize,
) -> Vec<Line<'static>> {
    let mut lines = Vec::with_capacity(content_line_budget);
    if content_line_budget > 0 {
        lines.push(Line::from(Span::styled(
            "Resume Session",
            Style::default().fg(theme.text).add_modifier(Modifier::BOLD),
        )));
    }
    if content_line_budget > 1 {
        lines.push(Line::from(Span::styled(
            session_selector_key_hints(selector),
            Style::default().fg(theme.dim),
        )));
    }
    if content_line_budget > 2 {
        match selector.mode() {
            SessionSelectorMode::Rename { value, .. } => lines.push(Line::from(vec![
                Span::styled("Rename: ", Style::default().fg(theme.warning)),
                Span::styled(
                    clean_terminal_text(value),
                    Style::default().fg(theme.text).bg(theme.selected_bg),
                ),
            ])),
            SessionSelectorMode::ConfirmDelete { .. } => lines.push(Line::from(Span::styled(
                "Archive session? d confirm · Esc cancel",
                Style::default().fg(theme.error),
            ))),
            SessionSelectorMode::List => lines.push(Line::from(vec![
                Span::styled("Filter: ", Style::default().fg(theme.dim)),
                Span::styled(
                    clean_terminal_text(selector.query()),
                    Style::default().fg(theme.text),
                ),
            ])),
        }
    }

    let row_line_budget = content_line_budget.saturating_sub(lines.len());
    if selector.visible_count() == 0 {
        if row_line_budget > 0 {
            lines.push(Line::from(Span::styled(
                "No matching sessions",
                Style::default().fg(theme.muted),
            )));
        }
        return lines;
    }

    let start = saved_session_viewport_start(selector, row_line_budget);
    let mut remaining = row_line_budget;
    for (index, row) in selector.visible_window(start, row_line_budget) {
        if remaining == 0 {
            break;
        }
        let marker = if selector.is_current(row) { "•" } else { " " };
        let style = if index == selector.selected() {
            Style::default().fg(theme.text).bg(theme.selected_bg)
        } else {
            Style::default().fg(if row.name.is_some() {
                theme.warning
            } else {
                theme.text
            })
        };
        let preview_lines =
            saved_session_preview_lines(row, marker, selector.show_path(), remaining);
        remaining = remaining.saturating_sub(preview_lines.len());
        lines.extend(
            preview_lines
                .into_iter()
                .map(|text| Line::from(Span::styled(text, style))),
        );
    }
    lines
}

fn render_saved_session_selector(
    frame: &mut ratatui::Frame<'_>,
    selector: &SavedSessionSelector,
    theme: Theme,
) {
    let preview_lines = saved_session_preferred_preview_lines(selector);
    let height = u16::try_from(preview_lines.saturating_add(SESSION_SELECTOR_HEIGHT_OVERHEAD))
        .unwrap_or(u16::MAX)
        .clamp(8, SESSION_SELECTOR_MAX_HEIGHT);
    let area = centered_rect(
        frame.area().width.saturating_sub(4).min(110).max(30),
        height,
        frame.area(),
    );
    frame.render_widget(Clear, area);
    let content_line_budget = usize::from(area.height.saturating_sub(2));
    let lines = saved_session_selector_lines(selector, theme, content_line_budget);
    frame.render_widget(
        Paragraph::new(lines)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(theme.border_accent)),
            )
            .wrap(Wrap { trim: false }),
        area,
    );
}

const AGENTS_PANEL_PADDING: u16 = 1;

fn inset_rect(area: Rect, padding: u16) -> Rect {
    let inset = padding.saturating_mul(2);
    Rect {
        x: area.x.saturating_add(padding),
        y: area.y.saturating_add(padding),
        width: area.width.saturating_sub(inset),
        height: area.height.saturating_sub(inset),
    }
}

fn agents_panel_lines(
    panel: &AgentsPanel,
    theme: Theme,
    width: u16,
    height: u16,
) -> Vec<Line<'static>> {
    let width = usize::from(width.max(1));
    let height = usize::from(height);
    if height == 0 {
        return Vec::new();
    }

    let dirty = if panel.dirty() { " · unsaved" } else { "" };
    let mut header = Vec::new();
    for text in [format!("{}{dirty}", panel.title()), panel.help().to_owned()] {
        let style = if header.is_empty() {
            Style::default().fg(theme.text).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(theme.dim)
        };
        header.extend(
            wrap_display_line(&clean_terminal_text(&text), width)
                .into_iter()
                .map(|line| Line::from(Span::styled(line, style))),
        );
    }
    header.push(Line::default());

    let mut body = Vec::new();
    let mut selected_range = None;
    let rows = panel.view_lines();
    for (index, row) in rows.iter().enumerate() {
        let start = body.len();
        let style = if row.selected {
            Style::default().fg(theme.text).bg(theme.selected_bg)
        } else {
            Style::default().fg(theme.text)
        };
        body.extend(
            wrap_display_line(&clean_terminal_text(&row.text), width)
                .into_iter()
                .map(|line| Line::from(Span::styled(line, style))),
        );
        if row.selected {
            selected_range = Some((start, body.len()));
        }
        if index + 1 < rows.len() {
            body.push(Line::default());
        }
    }

    let mut detail = panel.selected_row().map_or_else(Vec::new, |selected| {
        let mut lines = vec![Line::default()];
        lines.extend(
            wrap_display_line(&clean_terminal_text(&selected.description), width)
                .into_iter()
                .map(|line| Line::from(Span::styled(line, Style::default().fg(theme.dim)))),
        );
        lines
    });

    // Header is fixed. Reserve description detail only when it still leaves enough room for
    // every wrapped line of the selection; selected visibility takes precedence on short panes.
    header.truncate(height.saturating_sub(1));
    let selected_height = selected_range.map_or(1, |(start, end)| end.saturating_sub(start));
    let detail_budget = height
        .saturating_sub(header.len().saturating_add(selected_height))
        .min(detail.len());
    detail.truncate(detail_budget);
    let body_height = height.saturating_sub(header.len().saturating_add(detail.len()));

    let body_start = selected_range.map_or(0, |(selected_start, selected_end)| {
        if body.len() <= body_height || body_height == 0 {
            return 0;
        }
        if selected_end.saturating_sub(selected_start) >= body_height {
            return selected_start.min(body.len().saturating_sub(body_height));
        }
        let selected_middle = selected_start.saturating_add(selected_end) / 2;
        let centered = selected_middle.saturating_sub(body_height / 2);
        let latest_for_top = selected_start.min(body.len().saturating_sub(body_height));
        let earliest_for_bottom = selected_end.saturating_sub(body_height);
        centered
            .clamp(earliest_for_bottom, latest_for_top)
            .min(body.len().saturating_sub(body_height))
    });
    let mut lines = header;
    lines.extend(body.into_iter().skip(body_start).take(body_height));
    lines.extend(detail);
    lines.truncate(height);
    lines
}
fn render_agents_panel(frame: &mut ratatui::Frame<'_>, panel: &AgentsPanel, theme: Theme) {
    let width = frame.area().width.saturating_sub(4).min(110).max(1);
    let max_height = frame.area().height.saturating_sub(2).min(24).max(1);
    let max_area = centered_rect(width, max_height, frame.area());
    let max_content = inset_rect(
        Block::default().borders(Borders::ALL).inner(max_area),
        AGENTS_PANEL_PADDING,
    );
    let desired_lines = agents_panel_lines(panel, theme, max_content.width, max_content.height);
    let minimum_height = 8.min(max_height);
    let height = u16::try_from(desired_lines.len())
        .unwrap_or(u16::MAX)
        .saturating_add(2)
        .saturating_add(AGENTS_PANEL_PADDING.saturating_mul(2))
        .clamp(minimum_height, max_height);
    let area = centered_rect(width, height, frame.area());
    frame.render_widget(Clear, area);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(theme.border_accent));
    let content = inset_rect(block.inner(area), AGENTS_PANEL_PADDING);
    let lines = agents_panel_lines(panel, theme, content.width, content.height);
    frame.render_widget(block, area);
    frame.render_widget(Paragraph::new(lines), content);
}

/// Compact context-window label (`1m`, `200k`, `4096`); `None` when unknown.
fn format_context_window(window: i64) -> Option<String> {
    if window <= 0 {
        return None;
    }
    let value = if window >= 1_000_000 {
        let millions = window as f64 / 1_000_000.0;
        if (millions - millions.round()).abs() < 1e-9 {
            format!("{}m", millions as i64)
        } else {
            format!("{:.1}m", millions)
        }
    } else if window >= 1_000 {
        let thousands = window as f64 / 1_000.0;
        if (thousands - thousands.round()).abs() < 1e-9 {
            format!("{}k", thousands as i64)
        } else {
            format!("{:.1}k", thousands)
        }
    } else {
        window.to_string()
    };
    Some(format!("{value} ◫"))
}

/// Per-1M-token price label (`free`, `$1/$5`). Never invents pricing: a
/// `ModelCost::default()` (all zero) renders as `free`.
fn format_model_cost(cost: &pi_ai::ModelCost) -> String {
    let input = cost.input;
    let output = cost.output;
    if input <= 0.0 && output <= 0.0 {
        return "free".to_owned();
    }
    let price = |value: f64| {
        let rounded = (value * 100.0).round() / 100.0;
        if rounded == rounded.trunc() && rounded.abs() < 1e12 {
            format!("{}", rounded as i64)
        } else {
            format!("{rounded}")
        }
    };
    match (input > 0.0, output > 0.0) {
        (true, true) => format!("${}/${}", price(input), price(output)),
        (true, false) => format!("${}", price(input)),
        (false, true) => format!("${}", price(output)),
        (false, false) => "free".to_owned(),
    }
}

/// Right-pane meta columns: context window, price, reasoning flag. Values that
/// are unavailable are omitted entirely rather than rendered blank.
fn model_meta_text(model: &Model) -> String {
    let mut parts = Vec::with_capacity(3);
    if let Some(context) = format_context_window(model.context_window) {
        parts.push(context);
    }
    parts.push(format_model_cost(&model.cost));
    if model.reasoning {
        parts.push("reasoning".to_owned());
    }
    parts.join("  ")
}

/// Row label for the right pane: display name when the catalog has a distinct
/// one, otherwise the raw model id.
fn model_row_label(model: Option<&Model>, id: &str) -> String {
    match model {
        Some(model) if !model.name.is_empty() && model.name != model.id => model.name.clone(),
        _ => id.to_owned(),
    }
}

fn render_scoped_model_selector(
    frame: &mut ratatui::Frame<'_>,
    selector: &ScopedModelSelector,
    theme: Theme,
) {
    render_model_selector(frame, selector, false, "", theme);
}

fn render_active_model_selector(
    frame: &mut ratatui::Frame<'_>,
    selector: &ScopedModelSelector,
    current_model: &str,
    theme: Theme,
) {
    render_model_selector(frame, selector, true, current_model, theme);
}

/// Integration-test seam for [`tui_test_support`]: renders the picker with the
/// default theme. `#[doc(hidden)]`, not public API.
#[doc(hidden)]
pub fn render_active_model_selector_for_test(
    frame: &mut ratatui::Frame<'_>,
    selector: &ScopedModelSelector,
    current_model: &str,
) {
    render_model_selector(frame, selector, true, current_model, crate::theme::DARK);
}

fn selected_viewport_start(selected: usize, count: usize, visible_rows: usize) -> usize {
    if visible_rows == 0 || count <= visible_rows {
        return 0;
    }
    selected
        .saturating_sub(visible_rows / 2)
        .min(count.saturating_sub(visible_rows))
}

fn render_model_selector(
    frame: &mut ratatui::Frame<'_>,
    selector: &ScopedModelSelector,
    is_picker: bool,
    current_model: &str,
    theme: Theme,
) {
    let providers = selector.providers();
    let model_ids = selector
        .current_provider()
        .map_or_else(Vec::new, |provider| selector.models_for_provider(provider));
    let provider_count = providers.len();
    let model_count = model_ids.len();
    let selected_provider = selector.provider_selected();
    let selected_model = selector.model_selected();
    let in_providers = selector.column() == ModelColumn::Providers;
    let in_models = selector.column() == ModelColumn::Models;

    let body_rows = provider_count.max(model_count);
    let panel_width = frame.area().width.saturating_sub(4).min(104).max(30);
    let inner_width = panel_width.saturating_sub(2);
    let provider_chars = providers
        .iter()
        .map(|provider| display_width(provider))
        .max()
        .unwrap_or(0);
    let left_width = (provider_chars.saturating_add(2)).min(32);
    let right_width = inner_width.saturating_sub(left_width).saturating_sub(2);
    let two_column = right_width >= 18;
    // Content: title, hints, filter, footer, plus the column header (two-column
    // mode) or the merged provider+model rows (single-column fallback).
    let content_lines = if two_column {
        body_rows.saturating_add(5)
    } else {
        provider_count.saturating_add(model_count).saturating_add(4)
    };
    let height = u16::try_from(content_lines.saturating_add(2))
        .unwrap_or(u16::MAX)
        .clamp(8, 26);
    let area = centered_rect(panel_width, height, frame.area());
    frame.render_widget(Clear, area);
    let dirty = if !is_picker && selector.dirty() {
        " · unsaved"
    } else {
        ""
    };
    let title = if is_picker {
        "Select Model"
    } else {
        "Model Configuration"
    };
    let hints = if is_picker {
        "↑/↓ move · ←/→ or Tab switch column · Enter select · type filter · Esc cancel"
    } else {
        scoped_model_key_hints()
    };
    let mut lines = vec![
        Line::from(Span::styled(
            truncate_todo_line(&format!("{title}{dirty}"), usize::from(inner_width)),
            Style::default().fg(theme.text).add_modifier(Modifier::BOLD),
        )),
        Line::from(Span::styled(
            truncate_todo_line(hints, usize::from(inner_width)),
            Style::default().fg(theme.dim),
        )),
        Line::from(vec![
            Span::styled("Filter: ", Style::default().fg(theme.dim)),
            Span::styled(
                truncate_todo_line(
                    &clean_terminal_text(selector.query()),
                    usize::from(inner_width.saturating_sub(8)),
                ),
                Style::default().fg(theme.text),
            ),
        ]),
    ];

    let highlight = |focused: bool, is_selected: bool| {
        if focused && is_selected {
            Style::default().fg(theme.text).bg(theme.selected_bg)
        } else if is_selected {
            Style::default().fg(theme.accent)
        } else {
            Style::default().fg(theme.text)
        }
    };

    if two_column {
        // Two-column omp-style layout: providers left, models right.
        lines.push(Line::from(Span::styled(
            format!(
                "{:<width$}  Models",
                "Providers",
                width = usize::from(left_width)
            ),
            Style::default().fg(theme.dim).add_modifier(Modifier::BOLD),
        )));
        let visible_rows = usize::from(area.height.saturating_sub(7)).max(1);
        let rendered_rows = body_rows.min(visible_rows);
        let provider_start =
            selected_viewport_start(selected_provider, provider_count, rendered_rows);
        let model_start = selected_viewport_start(selected_model, model_count, rendered_rows);
        for row in 0..rendered_rows {
            let mut spans = Vec::with_capacity(2);
            let provider_row = provider_start.saturating_add(row);
            if provider_row < provider_count {
                let bullet = if provider_row == selected_provider {
                    "●"
                } else {
                    "○"
                };
                let mut cell = format!("{bullet} {}", providers[provider_row]);
                let cell_width = display_width(&cell);
                if cell_width < left_width {
                    cell.push_str(&" ".repeat(usize::from(left_width - cell_width)));
                } else {
                    cell = truncate_todo_line(&cell, usize::from(left_width));
                }
                spans.push(Span::styled(
                    cell,
                    highlight(in_providers, provider_row == selected_provider),
                ));
            } else {
                spans.push(Span::styled(
                    " ".repeat(usize::from(left_width)),
                    Style::default(),
                ));
            }
            spans.push(Span::styled("  ", Style::default()));
            let model_row = model_start.saturating_add(row);
            if model_row < model_count {
                let id = &model_ids[model_row];
                let model = selector.model_for_id(id);
                let marker = if is_picker {
                    if id == current_model { "●" } else { " " }
                } else if selector.is_enabled(id) {
                    "✓"
                } else {
                    "✗"
                };
                let meta = model.map_or_else(String::new, model_meta_text);
                let meta_width = display_width(&meta);
                let label_width =
                    usize::from(right_width.saturating_sub(meta_width).saturating_sub(3)).max(1);
                let label_text = truncate_todo_line(
                    &format!(
                        "{marker} {}",
                        clean_terminal_text(&model_row_label(model, id))
                    ),
                    label_width,
                );
                let cell = if meta.is_empty() {
                    label_text
                } else {
                    format!("{label_text}  {meta}")
                };
                spans.push(Span::styled(
                    cell,
                    highlight(in_models, model_row == selected_model),
                ));
            }
            lines.push(Line::from(spans));
        }
    } else {
        // Tiny-width fallback: providers and the selected provider's models in
        // one column, keeping both panes reachable.
        let visible_rows = usize::from(area.height.saturating_sub(6)).max(2);
        let reserved_model_rows = usize::from(model_count > 0);
        let provider_rows =
            provider_count.min(visible_rows.saturating_sub(reserved_model_rows).max(1));
        let model_rows = model_count.min(visible_rows.saturating_sub(provider_rows).max(1));
        let provider_start =
            selected_viewport_start(selected_provider, provider_count, provider_rows);
        let model_start = selected_viewport_start(selected_model, model_count, model_rows);
        for (row, provider) in providers
            .iter()
            .enumerate()
            .skip(provider_start)
            .take(provider_rows)
        {
            let bullet = if row == selected_provider {
                "●"
            } else {
                "○"
            };
            // Truncate to the inner width so one logical row stays one grid
            // row — a wrapped label would push later rows out of the overlay.
            let cell = truncate_todo_line(
                &format!("{bullet} {}", clean_terminal_text(provider)),
                usize::from(inner_width),
            );
            lines.push(Line::from(Span::styled(
                cell,
                highlight(in_providers, row == selected_provider),
            )));
        }
        for (row, id) in model_ids
            .iter()
            .enumerate()
            .skip(model_start)
            .take(model_rows)
        {
            let model = selector.model_for_id(id);
            let marker = if is_picker {
                if id == current_model { "●" } else { " " }
            } else if selector.is_enabled(id) {
                "✓"
            } else {
                "✗"
            };
            let meta = model.map_or_else(String::new, model_meta_text);
            let cell = if meta.is_empty() {
                format!(
                    "  {marker} {}",
                    clean_terminal_text(&model_row_label(model, id))
                )
            } else {
                format!(
                    "  {marker} {}  {meta}",
                    clean_terminal_text(&model_row_label(model, id))
                )
            };
            lines.push(Line::from(Span::styled(
                truncate_todo_line(&cell, usize::from(inner_width)),
                highlight(in_models, row == selected_model),
            )));
        }
    }

    let footer = if is_picker {
        selector.selected_id().map_or_else(
            || "No matching models".to_owned(),
            |id| format!("Selected: {id}"),
        )
    } else {
        format!(
            "{} enabled · {} unavailable",
            selector.enabled_count(),
            selector.unavailable_count()
        )
    };
    lines.push(Line::from(Span::styled(
        truncate_todo_line(&footer, usize::from(inner_width)),
        Style::default().fg(theme.dim),
    )));
    frame.render_widget(
        Paragraph::new(lines)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(theme.border_accent)),
            )
            .wrap(Wrap { trim: false }),
        area,
    );
}

fn render_transcript_markdown(
    text: &str,
    theme: Theme,
    base: Color,
    width: u16,
    streaming: bool,
) -> Vec<Line<'static>> {
    // Render-time redaction: the model's replies, thinking, and job context
    // may echo tokens/keys. The session record keeps raw text; only what is
    // drawn on screen is obfuscated.
    let text = redact_secrets(text);
    let styles = markdown_ratatui_styles(theme, base);
    if streaming {
        render_ratatui_markdown_streaming(&text, width, styles).lines
    } else {
        render_ratatui_markdown(&text, width, styles).lines
    }
}

pub(crate) fn markdown_ratatui_styles(theme: Theme, base: Color) -> MarkdownRatatuiStyles {
    let text = Style::default().fg(base);
    let heading = Style::default()
        .fg(theme.md_heading)
        .add_modifier(Modifier::BOLD);
    MarkdownRatatuiStyles {
        text,
        heading_1: heading,
        heading_2: heading,
        heading_3: heading,
        heading_4: heading,
        heading_5: heading,
        heading_6: heading,
        list_marker: Style::default().fg(theme.md_list_bullet),
        quote: Style::default().fg(theme.md_quote),
        code: Style::default().fg(theme.md_code_block),
        // Code-block frames use the same gray-white border as tool-card
        // frames: md_code_block_border (#2a3038) is too dim against the
        // #0f1216 background to read as a full card border.
        code_fence: Style::default().fg(theme.tool_card_border),
        inline_code: Style::default().fg(theme.md_code),
        syntax_comment: Style::default().fg(theme.syntax_comment),
        syntax_keyword: Style::default().fg(theme.syntax_keyword),
        syntax_function: Style::default().fg(theme.syntax_function),
        syntax_variable: Style::default().fg(theme.syntax_variable),
        syntax_string: Style::default().fg(theme.syntax_string),
        syntax_number: Style::default().fg(theme.syntax_number),
        syntax_type: Style::default().fg(theme.syntax_type),
        syntax_operator: Style::default().fg(theme.syntax_operator),
        syntax_punctuation: Style::default().fg(theme.syntax_punctuation),
        // Tables use the same frame role as code/tool-card frames:
        // md_code_block_border (#2a3038) is too dim against the #0f1216
        // background to read as a full card border.
        table_border: Style::default().fg(theme.tool_card_border),
        table_header: Style::default()
            .fg(theme.md_heading)
            .add_modifier(Modifier::BOLD),
        table_body: text,
        mermaid_border: Style::default().fg(theme.tool_card_border),
        mermaid_node: Style::default().fg(base),
        mermaid_edge: Style::default().fg(theme.md_list_bullet),
        diagnostic: Style::default()
            .fg(theme.warning)
            .add_modifier(Modifier::ITALIC),
        thematic_break: Style::default().fg(theme.tool_card_border),
    }
}

fn render_tool_text(text: &str, theme: Theme) -> Vec<Line<'static>> {
    let has_added = text
        .lines()
        .any(|line| line.starts_with('+') && !line.starts_with("+++"));
    let has_removed = text
        .lines()
        .any(|line| line.starts_with('-') && !line.starts_with("---"));
    let is_diff = text.lines().any(|line| line.starts_with("@@")) || (has_added && has_removed);
    if !is_diff {
        // No caller supplies a width today; use the shared renderer default
        // (callers wiring this up must thread the container width).
        return render_markdown(text, theme, theme.tool_output, 80);
    }
    text.lines()
        .map(|line| {
            let color = if line.starts_with('+') && !line.starts_with("+++") {
                theme.tool_diff_added
            } else if line.starts_with('-') && !line.starts_with("---") {
                theme.tool_diff_removed
            } else {
                theme.tool_diff_context
            };
            Line::from(Span::styled(line.to_owned(), Style::default().fg(color)))
        })
        .collect()
}

fn render_markdown(text: &str, theme: Theme, base: Color, width: u16) -> Vec<Line<'static>> {
    // Render-time redaction for user/tool prose drawn without the shared
    // ratatui markdown path; storage keeps the raw text.
    let text = redact_secrets(text);
    // The user bubble wraps content at `width - 1` (one trailing padding
    // cell), so the code frame is built at that inner width.
    let frame_width = usize::from(width.max(1)).saturating_sub(1).max(1);
    let content_width = frame_width.saturating_sub(4).max(1);
    let border_style = Style::default().fg(theme.tool_card_border);
    let mut lines = Vec::new();
    let mut fenced = false;
    let mut language = String::new();
    for raw in text.lines() {
        let line = raw.trim_end_matches('\r');
        if let Some(info) = line.trim_start().strip_prefix("```") {
            fenced = !fenced;
            if fenced {
                language = info.trim().to_owned();
                let title = if language.is_empty() {
                    "code".to_owned()
                } else {
                    format!("code · {language}")
                };
                push_code_frame_top(&mut lines, &title, border_style, frame_width);
            } else {
                lines.push(Line::from(Span::styled(
                    format!("╰{}╯", "─".repeat(frame_width.saturating_sub(2))),
                    border_style,
                )));
            }
            continue;
        }
        if fenced {
            // Sanitize before measuring/wrapping (tab → 4 spaces, control/CSI
            // stripped) so the width math matches what the terminal paints.
            // Wrapping reuses the shared grapheme-aware verbatim wrapper; a
            // single cluster wider than the content band survives intact there
            // (lossless overflow policy), so clamp those rows to content_width
            // with an ellipsis — every body row is exactly frame_width.
            let safe = clean_terminal_text(line);
            for wrapped in wrap_verbatim(&safe, content_width) {
                let fitted = if grapheme_display_width(&wrapped) > content_width {
                    fit_text(&wrapped, content_width)
                } else {
                    wrapped
                };
                let used = grapheme_display_width(&fitted);
                let pad = content_width.saturating_sub(used);
                let mut spans = vec![Span::styled("│ ", border_style)];
                spans.extend(syntax_spans(&fitted, theme));
                spans.push(Span::raw(" ".repeat(pad)));
                spans.push(Span::styled(" │", border_style));
                lines.push(Line::from(spans));
            }
            continue;
        }
        let trimmed = line.trim_start();
        if let Some(heading) = trimmed
            .strip_prefix("### ")
            .or_else(|| trimmed.strip_prefix("## "))
            .or_else(|| trimmed.strip_prefix("# "))
        {
            lines.push(Line::from(Span::styled(
                heading.to_owned(),
                Style::default()
                    .fg(theme.md_heading)
                    .add_modifier(Modifier::BOLD),
            )));
        } else if let Some(quote) = trimmed.strip_prefix("> ") {
            lines.push(Line::from(vec![
                Span::styled("│ ", Style::default().fg(theme.md_quote)),
                Span::styled(quote.to_owned(), Style::default().fg(theme.md_quote)),
            ]));
        } else if is_markdown_rule(trimmed) {
            // Span the actual bounded container width (frame_width = width-1,
            // the user bubble's inner band) — never the literal source length
            // — so the rule fills the row without overflowing into a wrapped
            // second row.
            lines.push(Line::from(Span::styled(
                "─".repeat(frame_width),
                Style::default().fg(theme.tool_card_border),
            )));
        } else if let Some(item) = trimmed
            .strip_prefix("- ")
            .or_else(|| trimmed.strip_prefix("* "))
        {
            let mut spans = vec![Span::styled(
                "• ",
                Style::default().fg(theme.md_list_bullet),
            )];
            spans.extend(inline_markdown_spans(item, theme, base));
            lines.push(Line::from(spans));
        } else {
            lines.push(Line::from(inline_markdown_spans(line, theme, base)));
        }
    }
    if fenced {
        // The fence never closed: cap the frame with a temporary bottom that
        // carries the unclosed marker, so the block never renders borderless
        // and never fakes a closed end while the fence is still open.
        push_code_frame_bottom(&mut lines, border_style, frame_width);
    }
    if text.is_empty() {
        lines.push(Line::default());
    }
    lines
}

/// Top border with the language label embedded, tool-card style
/// (`╭── code · lang ──╮`). Falls back to a plain top border plus a titled
/// row when the label cannot fit on the border line, mirroring tool cards.
fn push_code_frame_top(
    lines: &mut Vec<Line<'static>>,
    title: &str,
    border_style: Style,
    frame_width: usize,
) {
    let title_width = grapheme_display_width(title);
    if title_width <= frame_width.saturating_sub(8) {
        let fill = frame_width.saturating_sub(8) - title_width;
        lines.push(Line::from(Span::styled(
            format!("╭── {title} ──{}╮", "─".repeat(fill)),
            border_style,
        )));
        return;
    }
    lines.push(Line::from(Span::styled(
        format!("╭{}╮", "─".repeat(frame_width.saturating_sub(2))),
        border_style,
    )));
    let inner = frame_width.saturating_sub(4).max(1);
    let fitted = truncate_status_text(title, inner);
    let pad = inner.saturating_sub(grapheme_display_width(&fitted));
    lines.push(Line::from(vec![
        Span::styled("│ ", border_style),
        Span::styled(fitted, border_style),
        Span::raw(" ".repeat(pad)),
        Span::styled(" │", border_style),
    ]));
}

/// Text embedded in the temporary bottom border of a fence that is still
/// open when the text ends (streaming output whose closing fence line has
/// not arrived). Mirrors the shared renderer's marker so the frame reads as
/// incomplete instead of pretending the block ended.
const UNCLOSED_FENCE_MARKER: &str = "… (unclosed fence)";

/// Temporary bottom border for a fence still open at end of text, carrying
/// the unclosed marker (`╰── … (unclosed fence) ──╯`). Falls back to an
/// inner marker row above a plain bottom border when the marker cannot fit
/// the border line, mirroring the top border's overflow behavior.
fn push_code_frame_bottom(lines: &mut Vec<Line<'static>>, border_style: Style, frame_width: usize) {
    let marker_width = grapheme_display_width(UNCLOSED_FENCE_MARKER);
    if marker_width <= frame_width.saturating_sub(8) {
        let fill = frame_width.saturating_sub(8) - marker_width;
        lines.push(Line::from(Span::styled(
            format!("╰── {UNCLOSED_FENCE_MARKER} ──{}╯", "─".repeat(fill)),
            border_style,
        )));
        return;
    }
    let inner = frame_width.saturating_sub(4).max(1);
    let fitted = truncate_status_text(UNCLOSED_FENCE_MARKER, inner);
    let pad = inner.saturating_sub(grapheme_display_width(&fitted));
    lines.push(Line::from(vec![
        Span::styled("│ ", border_style),
        Span::styled(fitted, border_style),
        Span::raw(" ".repeat(pad)),
        Span::styled(" │", border_style),
    ]));
    lines.push(Line::from(Span::styled(
        format!("╰{}╯", "─".repeat(frame_width.saturating_sub(2))),
        border_style,
    )));
}

fn inline_markdown_spans(text: &str, theme: Theme, base: Color) -> Vec<Span<'static>> {
    let mut spans = Vec::new();
    let mut rest = text;
    while !rest.is_empty() {
        let next = ["`", "**", "[", "*"]
            .iter()
            .filter_map(|marker| rest.find(marker).map(|index| (index, *marker)))
            .min_by_key(|(index, _)| *index);
        let Some((index, marker)) = next else {
            spans.push(Span::styled(rest.to_owned(), Style::default().fg(base)));
            break;
        };
        if index > 0 {
            spans.push(Span::styled(
                rest[..index].to_owned(),
                Style::default().fg(base),
            ));
            rest = &rest[index..];
        }
        match marker {
            "`" => {
                if let Some(end) = rest[1..].find('`') {
                    spans.push(Span::styled(
                        rest[1..=end].to_owned(),
                        Style::default().fg(theme.md_code),
                    ));
                    rest = &rest[end + 2..];
                } else {
                    spans.push(Span::styled(rest.to_owned(), Style::default().fg(base)));
                    break;
                }
            }
            "**" => {
                if let Some(end) = rest[2..].find("**") {
                    spans.push(Span::styled(
                        rest[2..end + 2].to_owned(),
                        Style::default().fg(base).add_modifier(Modifier::BOLD),
                    ));
                    rest = &rest[end + 4..];
                } else {
                    spans.push(Span::styled(rest.to_owned(), Style::default().fg(base)));
                    break;
                }
            }
            "[" => {
                if let Some(close) = rest.find("](")
                    && let Some(end) = rest[close + 2..].find(')')
                {
                    spans.push(Span::styled(
                        rest[1..close].to_owned(),
                        Style::default()
                            .fg(theme.md_link)
                            .add_modifier(Modifier::UNDERLINED),
                    ));
                    spans.push(Span::styled(
                        format!(" ({})", &rest[close + 2..close + 2 + end]),
                        Style::default().fg(theme.md_link_url),
                    ));
                    rest = &rest[close + 3 + end..];
                } else {
                    spans.push(Span::styled("[".to_owned(), Style::default().fg(base)));
                    rest = &rest[1..];
                }
            }
            "*" => {
                if let Some(end) = rest[1..].find('*') {
                    spans.push(Span::styled(
                        rest[1..=end].to_owned(),
                        Style::default().fg(base).add_modifier(Modifier::ITALIC),
                    ));
                    rest = &rest[end + 2..];
                } else {
                    spans.push(Span::styled("*".to_owned(), Style::default().fg(base)));
                    rest = &rest[1..];
                }
            }
            _ => unreachable!(),
        }
    }
    spans
}

fn syntax_spans(line: &str, theme: Theme) -> Vec<Span<'static>> {
    let trimmed = line.trim_start();
    if trimmed.starts_with("//") || trimmed.starts_with('#') || trimmed.starts_with("--") {
        return vec![Span::styled(
            line.to_owned(),
            Style::default().fg(theme.syntax_comment),
        )];
    }
    let keywords = [
        "as", "async", "await", "break", "const", "continue", "def", "else", "enum", "fn", "for",
        "from", "if", "impl", "import", "in", "let", "loop", "match", "mod", "mut", "pub",
        "return", "self", "static", "struct", "trait", "type", "use", "where", "while",
    ];
    let chars = line.chars().collect::<Vec<_>>();
    let mut spans = Vec::new();
    let mut index = 0;
    while index < chars.len() {
        let start = index;
        let character = chars[index];
        let color = if character.is_whitespace() {
            while index < chars.len() && chars[index].is_whitespace() {
                index += 1;
            }
            theme.syntax_punctuation
        } else if character == '"' || character == '\'' {
            let quote = character;
            index += 1;
            while index < chars.len() {
                let current = chars[index];
                index += 1;
                if current == quote {
                    break;
                }
            }
            theme.syntax_string
        } else if character.is_ascii_digit() {
            while index < chars.len()
                && (chars[index].is_ascii_hexdigit() || chars[index] == '.' || chars[index] == '_')
            {
                index += 1;
            }
            theme.syntax_number
        } else if character.is_alphanumeric() || character == '_' {
            while index < chars.len() && (chars[index].is_alphanumeric() || chars[index] == '_') {
                index += 1;
            }
            let token = chars[start..index].iter().collect::<String>();
            if keywords.contains(&token.as_str()) {
                theme.syntax_keyword
            } else if token.chars().next().is_some_and(char::is_uppercase) {
                theme.syntax_type
            } else if chars[index..].iter().find(|value| !value.is_whitespace()) == Some(&&'(') {
                theme.syntax_function
            } else {
                theme.syntax_variable
            }
        } else {
            index += 1;
            if "+-*/%=!<>|&^~".contains(character) {
                theme.syntax_operator
            } else {
                theme.syntax_punctuation
            }
        };
        spans.push(Span::styled(
            chars[start..index].iter().collect::<String>(),
            Style::default().fg(color),
        ));
    }
    spans
}

fn apply_tool_line_styles(lines: &mut [Line<'static>], theme: Theme, background: Option<Color>) {
    for line in lines {
        let text = line
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        let foreground = if text.starts_with('+') && !text.starts_with("+++") {
            Some(theme.tool_diff_added)
        } else if text.starts_with('-') && !text.starts_with("---") {
            Some(theme.tool_diff_removed)
        } else if text.starts_with("@@") || text.starts_with(' ') {
            Some(theme.tool_diff_context)
        } else {
            None
        };
        if let Some(foreground) = foreground {
            for span in &mut line.spans {
                span.style = span.style.fg(foreground);
            }
        }
        if let Some(background) = background {
            line.style = line.style.bg(background);
        }
    }
}

fn extension_widget_lines(
    snapshot: &crate::extension_ui::ExtensionUiSnapshot,
    placement: UiWidgetPlacement,
    theme: Theme,
) -> Vec<Line<'static>> {
    let mut lines = Vec::new();
    for widget in snapshot
        .widgets
        .iter()
        .filter(|widget| widget.placement == placement)
    {
        for line in &widget.lines {
            lines.push(Line::from(Span::styled(
                clean_terminal_text(line),
                Style::default()
                    .fg(theme.custom_message_text)
                    .bg(theme.custom_message_bg),
            )));
        }
    }
    lines
}

fn render_tree_panel(frame: &mut ratatui::Frame<'_>, panel: &TreePanel, theme: Theme) {
    let width = frame.area().width.saturating_sub(4).min(110).max(30);
    let rows = if panel.mode == TreePanelMode::Fork {
        panel.visible().len().saturating_mul(3)
    } else {
        panel.visible().len()
    };
    let height = u16::try_from(rows.saturating_add(6))
        .unwrap_or(u16::MAX)
        .clamp(8, 24);
    let area = centered_rect(width, height, frame.area());
    let row_budget = usize::from(area.width.saturating_sub(4).max(1));
    let mut lines = vec![Line::from(Span::styled(
        clean_terminal_text(&panel.title),
        Style::default().fg(theme.text).add_modifier(Modifier::BOLD),
    ))];
    if panel.mode == TreePanelMode::Fork {
        lines.push(Line::from(Span::styled(
            "Select a user message to copy the active path up to that point into a new session",
            Style::default().fg(theme.dim),
        )));
    } else {
        lines.push(Line::from(vec![
            Span::styled("Type to search: ", Style::default().fg(theme.dim)),
            Span::styled(
                clean_terminal_text(&panel.query),
                Style::default().fg(theme.text),
            ),
        ]));
    }
    lines.push(Line::from(Span::styled(
        tree_panel_key_hints(panel),
        Style::default().fg(theme.dim),
    )));
    if panel.visible().is_empty() {
        lines.push(Line::from(Span::styled(
            if panel.mode == TreePanelMode::Fork {
                "No user messages found"
            } else {
                "No entries found"
            },
            Style::default().fg(theme.muted),
        )));
    } else {
        for (index, node) in panel.visible().iter().enumerate() {
            if panel.mode == TreePanelMode::Fork {
                let cursor = if node.selected { "› " } else { "  " };
                let body = node
                    .label_text
                    .strip_prefix("user: ")
                    .unwrap_or(&node.label_text);
                let style = if node.selected {
                    Style::default()
                        .fg(theme.text)
                        .bg(theme.selected_bg)
                        .add_modifier(Modifier::BOLD)
                } else {
                    Style::default().fg(theme.text)
                };
                let row = truncate_status_text(
                    &clean_terminal_text(&format!("{cursor}{body}")),
                    row_budget,
                );
                lines.push(Line::from(Span::styled(row, style)));
                lines.push(Line::from(Span::styled(
                    format!("  Message {} of {}", index + 1, panel.visible().len()),
                    Style::default().fg(theme.dim),
                )));
                lines.push(Line::from(""));
                continue;
            }
            let mut prefix = String::new();
            for gutter in &node.gutters {
                prefix.push_str(if *gutter { "│  " } else { "   " });
            }
            let connector = if node.depth == 0 {
                ""
            } else if node.is_last {
                "└"
            } else {
                "├"
            };
            let branch = if node.depth == 0 {
                ""
            } else if node.foldable {
                if node.folded { "⊞ " } else { "⊟ " }
            } else {
                "─ "
            };
            prefix.push_str(connector);
            prefix.push_str(branch);
            let cursor = if node.selected { "› " } else { "  " };
            let active = if node.active { "• " } else { "  " };
            let label = node.label.as_ref().map_or_else(String::new, |label| {
                if panel.show_label_timestamps {
                    format!(
                        "[{label} @ {}] ",
                        node.label_timestamp.as_deref().unwrap_or("?")
                    )
                } else {
                    format!("[{label}] ")
                }
            });
            let style = if node.selected {
                Style::default().fg(theme.text).bg(theme.selected_bg)
            } else if node.active {
                Style::default().fg(theme.accent)
            } else {
                Style::default().fg(theme.text)
            };
            let row = truncate_status_text(
                &clean_terminal_text(&format!(
                    "{cursor}{prefix}{active}{label}{}",
                    node.label_text
                )),
                row_budget,
            );
            lines.push(Line::from(Span::styled(row, style)));
        }
    }
    if panel.mode == TreePanelMode::Navigate {
        if let Some(label) = panel.label_input.as_ref() {
            lines.push(Line::from(vec![
                Span::styled(
                    "Label (empty to remove): ",
                    Style::default().fg(theme.warning),
                ),
                Span::styled(
                    clean_terminal_text(label),
                    Style::default().fg(theme.text).bg(theme.selected_bg),
                ),
            ]));
        }
        lines.push(Line::from(Span::styled(
            format!(
                "({}/{}) [{}]",
                panel.selected.saturating_add(1).min(panel.visible().len()),
                panel.visible().len(),
                panel.filter.label()
            ),
            Style::default().fg(theme.dim),
        )));
    }
    frame.render_widget(
        Paragraph::new(lines)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .border_style(Style::default().fg(theme.border_accent)),
            )
            .wrap(Wrap { trim: false }),
        area,
    );
}

fn format_hotkeys_text(bindings: &KeyBindingsManager) -> String {
    let sections = bindings.hotkey_sections();
    if sections.is_empty() {
        return "No keybindings loaded".to_owned();
    }
    let mut parts = Vec::with_capacity(sections.len());
    for section in sections {
        let mut block = format!("## {}", section.title);
        for row in section.rows {
            block.push('\n');
            block.push_str(&row);
        }
        parts.push(block);
    }
    parts.join("\n\n")
}

fn overlay_unknown_key_status(key: KeyEvent) -> String {
    let chord = crate::keybindings::normalize_key(&key)
        .map(|chord| crate::keybindings::format_chord_display(&chord))
        .unwrap_or_else(|| format!("{key:?}"));
    format!("Unknown key {chord} · see footer hints · Esc closes · /hotkeys for full map")
}

fn tree_panel_key_hints(panel: &TreePanel) -> String {
    if panel.label_input.is_some() {
        return "Enter save label · Esc cancel".to_owned();
    }
    match panel.mode {
        TreePanelMode::Fork => "↑/↓ move · Enter fork · Esc/q close".to_owned(),
        TreePanelMode::Navigate => {
            "↑/↓ move · ← fold · → unfold · Enter select · type search · Esc/q close".to_owned()
        }
    }
}

fn session_selector_key_hints(selector: &SavedSessionSelector) -> String {
    match selector.mode() {
        SessionSelectorMode::Rename { .. } => "Type name · Enter save · Esc cancel".to_owned(),
        SessionSelectorMode::ConfirmDelete { .. } => "d confirm · Esc cancel".to_owned(),
        SessionSelectorMode::List => {
            "↑/↓ · Enter resume · f fork · c clone · r rename · d archive · type filter · Esc/q close"
                .to_owned()
        }
    }
}

fn scoped_model_key_hints() -> &'static str {
    "↑/↓ move · → models · ← providers · Enter toggle · Ctrl+A/X/P/S · Alt+↑/↓ reorder · type filter · Esc/q close"
}

fn selector_panel_key_hints(panel: &SelectorPanel) -> String {
    if panel.help.trim().is_empty() {
        "↑/↓ move · Enter select · type filter · Esc cancel".to_owned()
    } else if panel.help.contains("Esc") {
        panel.help.clone()
    } else {
        format!("{} · Esc cancel", panel.help)
    }
}

fn render_selector_panel(frame: &mut ratatui::Frame<'_>, panel: &SelectorPanel, theme: Theme) {
    let visible = panel.visible_indices();
    let goal_panel = panel.title == "Goal";
    // Commit picker: fixed 12-row window, single-line clipped rows, selection-follow.
    let commit_picker = panel.kind == SelectorPanelKind::CommitList;
    let height = if commit_picker {
        16.min(frame.area().height)
    } else {
        u16::try_from(visible.len().saturating_add(4))
            .unwrap_or(u16::MAX)
            .clamp(5, 20)
    };
    let width = frame
        .area()
        .width
        .saturating_sub(4)
        .min(if goal_panel { 84 } else { 76 })
        .max(20);
    let area = centered_rect(width, height, frame.area());
    let inner_width = usize::from(area.width.saturating_sub(4).max(1));
    let mut lines = Vec::new();
    if !goal_panel {
        lines.push(Line::from(vec![
            Span::styled("Filter: ", Style::default().fg(theme.dim)),
            Span::styled(
                clean_terminal_text(&panel.query),
                Style::default().fg(theme.text),
            ),
        ]));
    }
    let row_budget = usize::from(area.height.saturating_sub(4)).max(1);
    let start = if commit_picker {
        selected_viewport_start(panel.selected, visible.len(), row_budget)
    } else {
        0
    };
    let window = if commit_picker { row_budget } else { usize::MAX };
    for (window_index, item_index) in visible.into_iter().skip(start).take(window).enumerate() {
        let item = &panel.items[item_index];
        let marker = if item.checked { "✓" } else { " " };
        let style = if window_index + start == panel.selected {
            Style::default().fg(theme.text).bg(theme.selected_bg)
        } else {
            Style::default().fg(theme.text)
        };
        let row = format!(
            " {marker} {}  {}",
            clean_terminal_text(&item.label),
            clean_terminal_text(&item.description)
        );
        if commit_picker {
            lines.push(Line::from(Span::styled(
                truncate_todo_line(&row, inner_width),
                style,
            )));
        } else {
            for wrapped in wrap_display_line(&row, inner_width) {
                lines.push(Line::from(Span::styled(wrapped, style)));
            }
        }
    }
    lines.push(Line::from(Span::styled(
        clean_terminal_text(&selector_panel_key_hints(panel)),
        Style::default().fg(theme.dim),
    )));
    frame.render_widget(Clear, area);
    frame.render_widget(
        Paragraph::new(lines)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .padding(ratatui::widgets::Padding::horizontal(1))
                    .border_style(Style::default().fg(theme.border_accent))
                    .title(format!(" {} ", clean_terminal_text(&panel.title))),
            )
            .wrap(Wrap { trim: false }),
        area,
    );
}

fn centered_rect(width: u16, height: u16, area: Rect) -> Rect {
    Rect {
        x: area.x.saturating_add(area.width.saturating_sub(width) / 2),
        y: area
            .y
            .saturating_add(area.height.saturating_sub(height) / 2),
        width: width.min(area.width),
        height: height.min(area.height),
    }
}
fn is_markdown_rule(text: &str) -> bool {
    text.len() >= 3
        && text
            .chars()
            .all(|character| character == '-' || character == '*' || character == '_')
}

/// Strip terminal control sequences from untrusted text, expanding tabs to
/// four spaces, so the result is safe to display as plain text (titles, args,
/// editor content, exports). This is the plain-text projection of the shared
/// one-pass ANSI parser ([`crate::ansi::parse_ansi_runs`] /
/// [`ansi_plain_text`]), so the plain and styled display paths are
/// byte-identical by construction.
pub(crate) fn clean_terminal_text(text: &str) -> String {
    ansi_plain_text(text)
}

fn normalize_newlines(text: &str) -> Cow<'_, str> {
    if !text.contains('\r') {
        return Cow::Borrowed(text);
    }
    let mut normalized = String::with_capacity(text.len());
    let mut characters = text.chars().peekable();
    while let Some(character) = characters.next() {
        if character == '\r' {
            if characters.peek() == Some(&'\n') {
                characters.next();
            }
            normalized.push('\n');
        } else {
            normalized.push(character);
        }
    }
    Cow::Owned(normalized)
}
fn wrapped_line_count(lines: &[Line<'_>], width: u16) -> usize {
    let width = usize::from(width.max(1));
    lines
        .iter()
        .map(|line| {
            let columns = line
                .spans
                .iter()
                .flat_map(|span| span.content.chars())
                .map(|character| character.width().unwrap_or(0))
                .sum::<usize>();
            columns.max(1).div_ceil(width)
        })
        .sum()
}

/// Physical rows required by an already-rendered scrollback projection.
/// `None` is semantically different from one blank row: it means every entry
/// was renderer-invisible and `insert_before` must not run.
fn projected_scrollback_height(lines: &[Line<'_>], width: u16) -> Option<u16> {
    let rows = wrapped_line_count(lines, width);
    (rows > 0).then(|| u16::try_from(rows).unwrap_or(u16::MAX))
}

/// Compute the transcript Paragraph scroll offset for this frame and update
/// the scroll bookkeeping for the next frame.
///
/// The window is anchored to a transcript **entry** (plus a row offset inside
/// it) rather than to the bottom. Entries are stable across frames, so when
/// content below the window changes height — streaming growth, a mermaid
/// fence closing (source ↔ diagram settle flip, which can move tens of rows),
/// or a resize reflow — the re-anchored window keeps showing the same
/// content instead of drifting by the height delta. A bottom-anchored row
/// offset (`bottom - transcript_scroll`) drifts by exactly that delta, which
/// is the remaining scroll-up history loss after the F9 `.wrap()` fix: the
/// `[scroll, scroll + height)` window lands at the wrong rows and content
/// appears to vanish.
///
/// `entry_row_starts` maps absolute transcript entry index → rendered start
/// row (length `transcript.len() + 1`; the trailing slot is the streaming
/// tail). The returned `scroll` is what the Paragraph should be scrolled by;
/// it is always clamped to `[0, bottom]`, so the tail is never skipped.
fn transcript_scroll_offset(
    state: &TuiState,
    entry_row_starts: &[usize],
    total_rows: usize,
    transcript_height: usize,
) -> usize {
    let bottom = total_rows.saturating_sub(transcript_height);
    let pending_up = state.pending_scroll_up_rows.get();
    let scroll = match state.transcript_top_row.get() {
        None => bottom,
        Some(_) if pending_up > 0 => {
            // PageUp prepended retained entries, invalidating the old raw row
            // coordinate. Re-map the previous top through its absolute entry
            // anchor, then move upward by the requested page rows.
            let (entry, offset) = state.scroll_anchor.get();
            let entry = entry.min(entry_row_starts.len().saturating_sub(1));
            entry_row_starts[entry]
                .saturating_add(offset)
                .saturating_sub(pending_up)
                .min(bottom)
        }
        Some(_) if state.scroll_moved.get() => {
            // The user just paged within the current projection: use the moved
            // row verbatim this frame; re-anchoring starts next frame.
            state.transcript_top_row.get().unwrap_or(bottom).min(bottom)
        }
        Some(_) => {
            // Layout may have changed since the top row was recorded
            // (streaming growth, settle flips, resize): re-map the anchor.
            let (entry, offset) = state.scroll_anchor.get();
            let entry = entry.min(entry_row_starts.len().saturating_sub(1));
            entry_row_starts[entry].saturating_add(offset).min(bottom)
        }
    };
    // Re-derive the anchor for the next frame from the actual window top.
    let top_entry = entry_row_starts
        .iter()
        .rposition(|&start| start <= scroll)
        .unwrap_or(0);
    state.scroll_anchor.set((
        top_entry,
        scroll.saturating_sub(entry_row_starts[top_entry]),
    ));
    state.pending_scroll_up_rows.set(0);
    state.scroll_moved.set(false);
    let manually_expanded = state.transcript_render_start.get() < state.committed_entries;
    state
        .transcript_top_row
        .set((scroll < bottom || manually_expanded).then_some(scroll));
    if !manually_expanded && scroll == bottom {
        state.transcript_render_start.set(state.committed_entries);
    }
    state.transcript_scroll_bottom.set(bottom);
    scroll
}

fn display_width(text: &str) -> u16 {
    let width = text
        .graphemes(true)
        .map(UnicodeWidthStr::width)
        .sum::<usize>();
    u16::try_from(width).unwrap_or(u16::MAX)
}

fn floor_char_boundary(text: &str, requested: usize) -> usize {
    if requested >= text.len() {
        return text.len();
    }
    text.char_indices()
        .map(|(index, _)| index)
        .take_while(|index| *index <= requested)
        .last()
        .unwrap_or(0)
}

/// Clipboard image waiting in the composer. Bytes live only inside
/// `ContentBlock::Image`; width/height are display metadata from the guarded
/// pipeline and never appear in the model payload.
#[derive(Clone, Debug, PartialEq)]
struct PendingAttachment {
    block: ContentBlock,
    width: u32,
    height: u32,
}

impl PendingAttachment {
    fn from_clipboard_image(image: crate::clipboard::ClipboardImage) -> Self {
        let width = image.width;
        let height = image.height;
        Self {
            block: image.into_content_block(),
            width,
            height,
        }
    }

    /// OMP-compatible composer placeholder: `[Image #N, WIDTHxHEIGHT]`.
    fn label(&self, index: usize) -> String {
        format!("[Image #{}, {}x{}]", index + 1, self.width, self.height)
    }
}

/// Human-visible labels for pending image attachments. Never includes base64
/// payload bytes or absolute paths — only ordinal and decoded dimensions.
fn pending_attachment_labels(attachments: &[PendingAttachment]) -> Vec<String> {
    attachments
        .iter()
        .enumerate()
        .map(|(index, attachment)| attachment.label(index))
        .collect()
}

/// Merge clipboard pending attachments with expanded file images for one submit.
/// Pure helper so adapter tests can assert exact-once assembly without a desktop clipboard.
fn assemble_submit_attachments(
    pending: &[PendingAttachment],
    file_images: Vec<ContentBlock>,
) -> Vec<ContentBlock> {
    let mut attachments = pending
        .iter()
        .map(|attachment| attachment.block.clone())
        .collect::<Vec<_>>();
    attachments.extend(file_images);
    attachments
}

/// After a failed prompt, keep only the pre-submit pending attachments.
/// File images must not be folded into pending while the draft still contains
/// `@file` markers — expand will re-emit them on the next submit.
fn restore_pending_after_failed_submit(
    pending: &mut Vec<PendingAttachment>,
    pre_submit_pending: Vec<PendingAttachment>,
) {
    *pending = pre_submit_pending;
}

fn content_text(content: &[ContentBlock]) -> String {
    content
        .iter()
        .filter_map(|block| match block {
            ContentBlock::Text { text, .. } => Some(text.clone()),
            ContentBlock::Image { mime_type, .. } => {
                Some(format!("[image attachment: {mime_type}]"))
            }
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn parse_bash_input(text: &str) -> Option<(String, bool)> {
    let (command, exclude_from_context) = if let Some(command) = text.strip_prefix("!!") {
        (command, true)
    } else {
        (text.strip_prefix('!')?, false)
    };
    let command = command.trim();
    (!command.is_empty()).then(|| (command.to_owned(), exclude_from_context))
}

fn message_text(message: Message) -> Option<String> {
    match message {
        Message::User(message) => Some(content_text(&message.content)),
        _ => None,
    }
    .filter(|text| !text.trim().is_empty())
}

fn fuzzy_match(candidate: &str, query: &str) -> bool {
    slash_match_rank(candidate, query).is_some()
}

fn slash_match_rank(candidate: &str, query: &str) -> Option<u8> {
    if query.is_empty() {
        return Some(0);
    }
    let candidate_lower = candidate.to_ascii_lowercase();
    let query_lower = query.to_ascii_lowercase();
    if candidate_lower == query_lower {
        Some(0)
    } else if candidate_lower.starts_with(&query_lower) {
        Some(1)
    } else if hyphen_boundary_match(&candidate_lower, &query_lower) {
        Some(2)
    } else if subsequence_match(&candidate_lower, &query_lower) {
        Some(3)
    } else {
        None
    }
}

fn hyphen_boundary_match(candidate: &str, query: &str) -> bool {
    candidate
        .split('-')
        .skip(1)
        .any(|part| part.starts_with(query))
}

pub(crate) fn subsequence_match(candidate: &str, query: &str) -> bool {
    let mut candidate = candidate.chars();
    query
        .chars()
        .all(|expected| candidate.by_ref().any(|actual| actual == expected))
}

fn slash_item_order(
    left: &CompletionItem,
    right: &CompletionItem,
    prefix: &str,
) -> std::cmp::Ordering {
    let left_name = left.value.trim_start_matches('/');
    let right_name = right.value.trim_start_matches('/');
    slash_match_rank(left_name, prefix)
        .cmp(&slash_match_rank(right_name, prefix))
        .then_with(|| left.value.cmp(&right.value))
}

fn first_prefix_completion_index(items: &[CompletionItem], prefix: &str) -> Option<usize> {
    if prefix.is_empty() {
        return None;
    }
    items.iter().position(|item| {
        item.value
            .trim_start_matches('/')
            .to_ascii_lowercase()
            .starts_with(&prefix.to_ascii_lowercase())
    })
}

fn selected_slash_is_prefix_hit(state: &TuiState) -> bool {
    let Some(item) = state.completions.selected() else {
        return false;
    };
    let text = state.editor.text();
    let Some(prefix) = text.strip_prefix('/') else {
        return false;
    };
    if prefix.is_empty() || prefix.contains(char::is_whitespace) {
        return false;
    }
    item.value
        .trim_start_matches('/')
        .to_ascii_lowercase()
        .starts_with(&prefix.to_ascii_lowercase())
}

fn compact_arguments(arguments: &serde_json::Value) -> String {
    let value = ["command", "path", "pattern"]
        .into_iter()
        .find_map(|key| arguments.get(key).and_then(serde_json::Value::as_str))
        .unwrap_or_default();
    let mut characters = value.chars();
    let prefix = characters.by_ref().take(57).collect::<String>();
    if characters.next().is_some() {
        format!("{prefix}...")
    } else {
        prefix
    }
}

/// Discovers theme directories and keybinding files in global-first,
/// project-last order so project config overrides global config. Reuses the
/// shared `.pi` config dir name; the home lookup mirrors pi-coding's. When a
/// shared `ResourcePaths`/`ResourceSnapshot` API lands in pi-coding, swap this
/// out to consume it — the managers themselves only take these paths.
fn config_paths(cwd: &Path) -> (Vec<PathBuf>, Vec<PathBuf>) {
    let global = home_dir()
        .map(|home| Path::new(&home).join(CONFIG_DIR_NAME))
        .unwrap_or_else(|| PathBuf::from(CONFIG_DIR_NAME));
    let project = cwd.join(CONFIG_DIR_NAME);
    let theme_dirs = vec![global.join("themes"), project.join("themes")];
    let keybinding_files = vec![
        global.join("keybindings.json"),
        project.join("keybindings.json"),
    ];
    (theme_dirs, keybinding_files)
}

/// Best-effort home directory (`HOME` on Unix, `USERPROFILE` on Windows).
fn home_dir() -> Option<String> {
    std::env::var_os("HOME")
        .or_else(|| std::env::var_os("USERPROFILE"))
        .and_then(|value| value.into_string().ok())
        .filter(|value| !value.is_empty())
}

