    impl std::ops::Deref for TestApplicationFixture {
        type Target = Application;

        fn deref(&self) -> &Self::Target {
            &self.application
        }
    }

    /// Cross-directory `/move` cutover needs the same runtime factory the
    /// production TUI attaches at startup. Without it `switch_session` fails
    /// closed and `run_session_move` parks the failure on `composer_error`,
    /// leaving the user-visible status row empty.
    struct MoveSlashRuntimeFactory {
        owners: Arc<std::sync::Mutex<Vec<tempfile::TempDir>>>,
    }

    impl pi_coding::ApplicationRuntimeFactory for MoveSlashRuntimeFactory {
        fn build_runtime_candidate(
            &self,
            cwd: PathBuf,
            options: pi_coding::SessionOptions,
            resume: Option<pi_coding::PreparedSessionResume>,
        ) -> pi_coding::ApplicationRuntimeFuture {
            let owners = self.owners.clone();
            Box::pin(async move {
                let session = Session::new_with_additional_tools_filtered_and_discovery(
                    options,
                    Vec::new(),
                    pi_coding::ToolSelection::default(),
                    pi_coding::ResourceDiscovery::Disabled,
                )?;
                session.set_session_dir(pi_coding::default_session_dir(&cwd));
                let agent_dir = tempfile::tempdir()?;
                std::fs::write(
                    agent_dir.path().join("settings.json"),
                    r#"{"sandbox":{"mode":"danger-full-access"}}"#,
                )?;
                let mut resource_options = pi_coding::ResourceManagerOptions::new(&cwd);
                resource_options.agent_dir = agent_dir.path().to_path_buf();
                resource_options.project_trust_override = Some(true);
                resource_options.disable_extensions = true;
                resource_options.disable_skills = true;
                resource_options.disable_prompt_templates = true;
                resource_options.disable_themes = true;
                resource_options.disable_context_files = true;
                let resources = pi_coding::ResourceManager::new(resource_options)?;
                session.attach_resources(resources).await?;
                if let Some(resume) = resume {
                    let context = resume.build_context();
                    let recorder = resume.into_recorder()?;
                    session.resume_recording(recorder, context.messages).await?;
                }
                owners
                    .lock()
                    .expect("move slash factory owners")
                    .push(agent_dir);
                Ok(pi_coding::ApplicationRuntimeCandidate::new(session))
            })
        }
    }

    fn attach_move_slash_runtime_factory(application: &Application) {
        application
            .attach_runtime_factory(Arc::new(MoveSlashRuntimeFactory {
                owners: Arc::new(std::sync::Mutex::new(Vec::new())),
            }))
            .expect("attach move slash runtime factory");
    }

