    #[test]
    fn startup_replay_inserts_every_printable_exactly_once() {
        let mut state = todo_test_state(Vec::new());
        let events = [
            Event::Key(KeyEvent::new(KeyCode::Char('a'), KeyModifiers::NONE)),
            Event::Key(KeyEvent::new(KeyCode::Char('b'), KeyModifiers::NONE)),
            Event::Key(KeyEvent::new(KeyCode::Char('c'), KeyModifiers::NONE)),
            Event::Resize(80, 24),
            Event::Key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE)),
            Event::Key(KeyEvent::new(KeyCode::Char('e'), KeyModifiers::NONE)),
            Event::Key(KeyEvent::new(KeyCode::Char('f'), KeyModifiers::NONE)),
        ];
        for event in events {
            match event {
                Event::Key(key) if key.kind == KeyEventKind::Press => {
                    if let KeyCode::Char(character) = key.code {
                        state.editor.insert_char(character);
                        state.refresh_completions();
                    }
                }
                Event::Resize(_, _) => {}
                _ => {}
            }
        }
        assert_eq!(state.editor.text(), "abcdef");
    }

