    #[test]
    fn one_mib_multiline_burst_applies_deterministically_without_blocking() {
        // Freeze regression for unmarked pastes. The production drain is
        // `input.next().now_or_never()` — it can never wait — so the
        // deterministic contract is structural, not wall-clock: classification
        // and application of a ~1 MiB multi-line burst are pure synchronous
        // functions over already-drained input, and every line up to the cap
        // lands in the composer in one grouped undo.
        let lines = 20_000;
        let payload: String = (0..lines)
            .map(|index| format!("line {index} with some content\n"))
            .collect();
        assert!(
            payload.len() < MAX_PASTE_BYTES,
            "fixture must stay under the cap"
        );
        assert_eq!(
            classify_raw_input_burst(&payload),
            RawInputDisposition::Paste,
            "multi-line burst must be delivered as one paste"
        );
        let mut state = todo_test_state(Vec::new());
        apply_classified_burst(&mut state, &payload);
        assert!(
            state.editor.text().contains("line 0 with some content"),
            "head of the paste must land in the composer"
        );
        assert!(
            state.editor.text().contains("line 19999 with some content"),
            "tail must not be truncated before the cap"
        );
    }

    #[test]
    fn burst_at_the_byte_cap_stops_exactly_at_max_paste_bytes() {
        // A burst crossing MAX_PASTE_BYTES is cut at the cap by the drain
        // loop; classification itself must accept up to the full cap without
        // misreading the boundary as a key replay.
        let unit = "x".repeat(1024);
        let mut payload = String::new();
        while payload.len() + unit.len() <= MAX_PASTE_BYTES {
            payload.push_str("line\n");
            payload.push_str(&unit);
        }
        assert!(payload.len() <= MAX_PASTE_BYTES && payload.len() > MAX_PASTE_BYTES - 2048);
        assert_eq!(
            classify_raw_input_burst(&payload),
            RawInputDisposition::Paste
        );
    }

