    #[test]
    fn assistant_markdown_matches_shared_neutral_output_for_rich_blocks() {
        let source = "# Heading\n\n1. ordered\n   - [x] nested\n\n| Name | Stat |\n| --- | ---: |\n| Tokyo | ✅ |\n\n[docs](https://example.test)\n\n```rust\nlet place = \"Tokyo\";\n```\n\n```mermaid\nflowchart LR\nA --> B\n```\n\n```mermaid\ngantt\ntitle A Gantt Diagram\n```";
        let width = 40;
        let expected = pi_coding::markdown::render_markdown(
            source,
            &pi_coding::markdown::MarkdownRenderOptions {
                width: usize::from(width),
                ..pi_coding::markdown::MarkdownRenderOptions::default()
            },
        )
        .plain_lines();
        let entry = TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text(source)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &entry, true, true, crate::theme::DARK, width);
        let rendered = lines
            .iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        assert_eq!(rendered, expected);
        assert!(
            rendered
                .iter()
                .any(|line| line.starts_with("┌─ mermaid · flowchart"))
        );
        assert!(rendered.iter().any(|line| line.contains("source fallback")));
        assert!(rendered.iter().all(|line| display_width(line) <= width));
        assert!(
            lines[0].spans[0]
                .style
                .add_modifier
                .contains(Modifier::BOLD)
        );
        assert!(lines.iter().all(|line| {
            line.spans
                .iter()
                .all(|span| span.content.as_ref() != "Assistant")
        }));
    }

