    #[test]
    fn screenshot_markdown_keeps_prose_default_and_cyan_sparse() {
        let source = "# Release notes\n\nOrdinary prose explains the change with **bold** and *italic* detail.\n\n- first item\n- second item\n\n[project path](https://example.test/src/lib.rs) and `cargo check`.\n\n```rust\nlet count: usize = parse(42);\n```";
        let lines = render_transcript_markdown(
            source,
            crate::theme::DARK,
            crate::theme::DARK.text,
            80,
            false,
        );
        let cyan = Some(crate::theme::DARK.md_heading);
        let plain = lines
            .iter()
            .flat_map(|line| line.spans.iter())
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(plain.contains("Ordinary prose explains the change"));
        let prose_spans = lines
            .iter()
            .flat_map(|line| line.spans.iter())
            .filter(|span| {
                matches!(
                    span.content.as_ref(),
                    "Ordinary" | "prose" | "explains" | "change"
                )
            });
        assert!(prose_spans.into_iter().all(|span| span.style.fg != cyan));
        let visible_spans = lines
            .iter()
            .flat_map(|line| &line.spans)
            .filter(|span| !span.content.trim().is_empty())
            .count();
        let cyan_spans = lines
            .iter()
            .flat_map(|line| &line.spans)
            .filter(|span| !span.content.trim().is_empty() && span.style.fg == cyan)
            .count();
        assert!(
            cyan_spans.saturating_mul(3) < visible_spans,
            "cyan must remain a sparse high-salience accent"
        );
    }

    #[test]
    fn markdown_chrome_uses_visible_borders_at_render_width() {
        let theme = crate::theme::DARK;
        let styles = markdown_ratatui_styles(theme, theme.text);
        assert_eq!(styles.code_fence.fg, Some(theme.tool_card_border));
        assert_eq!(styles.table_border.fg, Some(theme.tool_card_border));
        assert_eq!(styles.mermaid_border.fg, Some(theme.tool_card_border));
        assert_eq!(styles.thematic_break.fg, Some(theme.tool_card_border));

        let lines = render_markdown("> quoted\n---", theme, theme.text, 40);
        let quote = lines.first().expect("quote row");
        assert_eq!(
            quote.spans.first().and_then(|span| span.style.fg),
            Some(theme.md_quote)
        );
        let rule = lines.get(1).expect("rule row");
        // frame_width = width-1 = 39: the user bubble's bounded content band.
        assert_eq!(rule.width(), 39);
        assert_eq!(
            rule.spans.first().and_then(|span| span.style.fg),
            Some(theme.tool_card_border)
        );

        // The rule must stay a single bounded row through the card pass — the
        // 39-dash frame padded to the 40-wide row, never wrapped into a stray
        // second dash row beyond the bound.
        let card = render_user_card_lines(lines, 40);
        let dash_rows: Vec<_> = card
            .iter()
            .filter(|l| {
                let text: String = l.spans.iter().map(|s| s.content.as_ref()).collect();
                text.starts_with('─')
            })
            .collect();
        assert_eq!(
            dash_rows.len(),
            1,
            "thematic break must stay one bounded row: {card:?}"
        );
        let dash_count: usize = dash_rows[0]
            .spans
            .iter()
            .map(|s| s.content.chars().filter(|&c| c == '─').count())
            .sum();
        assert_eq!(
            dash_count, 39,
            "rule must span the bounded 39-cell band: {card:?}"
        );
    }

