    #[test]
    fn streaming_updates_replace_the_live_entry_without_repeating_frozen_blocks() {
        let width = 32;
        let mut state = todo_test_state(Vec::new());
        state.apply(ApplicationEvent::Agent(AgentEvent::AgentStart));
        for delta in ["# Stable\n\nmutable", " tail"] {
            let mut partial = pi_ai::AssistantMessage::pending(&Model::default());
            partial.content = vec![ContentBlock::text(format!(
                "{}{}",
                state.streaming_text, delta
            ))];
            state.apply(ApplicationEvent::Agent(AgentEvent::MessageUpdate {
                message: Message::Assistant(partial.clone()),
                assistant_message_event: AssistantMessageEvent::TextDelta {
                    content_index: 0,
                    delta: delta.to_owned(),
                    partial,
                },
            }));
            let rendered = render_transcript_markdown(
                &state.streaming_text,
                crate::theme::DARK,
                crate::theme::DARK.text,
                width,
                true,
            );
            let stable = rendered
                .iter()
                .filter(|line| {
                    line.spans
                        .iter()
                        .map(|span| span.content.as_ref())
                        .collect::<String>()
                        == "Stable"
                })
                .count();
            assert_eq!(stable, 1);
        }
        assert_eq!(state.streaming_text, "# Stable\n\nmutable tail");
        assert!(state.transcript.is_empty());
    }

    #[test]
    fn table_frames_use_card_border_color_and_stay_bounded_in_transcript() {
        // User-reported: markdown tables rendered with a weaker border than the
        // surrounding code/tool-card frames. Tables must frame with the same
        // box-drawing chrome AND the same theme role as the cards
        // (theme.tool_card_border) — never the dim md_code_block_border that
        // disappears against the #0f1216 background.
        let theme = crate::theme::DARK;
        let width = 52u16;
        let source = "| Field | Value |\n\
                      | --- | --- |\n\
                      | Architecture decision record | Explains why committed conversation stays separate from transient composer frames |\n\
                      | Contributor guide | Shows maintainers how to extend rendering without losing semantic styles |";
        let lines = render_transcript_markdown(source, theme, theme.text, width, false);
        let texts = lines.iter().map(rendered_line_text).collect::<Vec<_>>();

        // Complete card-consistent frame: top border, header separator, bottom
        // border, and every body row carries side borders.
        assert!(
            texts.first().is_some_and(|line| line.starts_with('┌')),
            "{texts:?}"
        );
        assert!(
            texts.last().is_some_and(|line| line.starts_with('└')),
            "{texts:?}"
        );
        assert!(
            texts
                .iter()
                .any(|line| line.starts_with('├') && line.contains('┼')),
            "header separator must render: {texts:?}"
        );
        assert!(
            texts
                .iter()
                .filter(|line| line.starts_with('│') && line.ends_with('│'))
                .count()
                >= 4,
            "side borders on every row: {texts:?}"
        );

        // All rows share one width and stay within the render budget.
        assert!(!texts.is_empty(), "table must render at width {width}");
        let frame_width = display_width(&texts[0]);
        assert!(
            frame_width <= width,
            "frame must stay width-bounded: {frame_width} > {width}: {texts:?}"
        );
        assert!(
            texts.iter().all(|line| display_width(line) == frame_width),
            "every table row must share the frame width: {texts:?}"
        );

        // Every border glyph uses the card frame color — never the dim
        // md_code_block_border, never Reset. The per-glyph equality assertion
        // also proves the frame is a single color.
        let glyphs = "┌┬┐├┼┤│└┴┘─";
        let mut border_glyph_spans = 0usize;
        for line in &lines {
            for span in &line.spans {
                if span.content.chars().any(|c| glyphs.contains(c)) {
                    border_glyph_spans += 1;
                    assert_eq!(
                        span.style.fg,
                        Some(theme.tool_card_border),
                        "border glyph must use the card frame color: {span:?}"
                    );
                }
            }
        }
        assert!(
            border_glyph_spans > 0,
            "table must render border glyphs: {texts:?}"
        );

        // Long cells wrap inside the frame instead of overflowing or vanishing.
        // Wrapping can split a phrase across rows, so assert per-row tokens.
        assert!(
            texts.iter().any(|line| line.contains("Architecture"))
                && texts.iter().any(|line| line.contains("decision record")),
            "{texts:?}"
        );
        assert!(
            texts.iter().any(|line| line.contains("Contributor guide")),
            "{texts:?}"
        );
    }

    #[test]
    fn user_card_has_one_internal_padding_row_per_edge_without_extra_separator() {
        let prompt = "Can you put it in the background?";
        let entry = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(prompt)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };

        for width in [80, 10] {
            let mut lines = Vec::new();
            render_transcript_entry(&mut lines, &entry, true, true, crate::theme::DARK, width);

            let content = &lines[1..lines.len() - 1];
            assert!(
                lines.first().is_some_and(|line| line
                    .spans
                    .iter()
                    .all(|span| span.content.trim().is_empty()))
            );
            assert!(
                lines.last().is_some_and(|line| line
                    .spans
                    .iter()
                    .all(|span| span.content.trim().is_empty()))
            );
            let first_row = &content[0];
            let first_visible = first_row
                .spans
                .iter()
                .flat_map(|span| span.content.chars())
                .find(|character| !character.is_whitespace());
            assert_eq!(
                first_visible,
                Some('C'),
                "first user glyph at width {width}"
            );
            assert!(
                first_row
                    .spans
                    .first()
                    .is_some_and(|span| span.content.starts_with('C')),
                "user content must begin at transcript column zero at width {width}: {first_row:?}"
            );
            assert!(lines.iter().all(|line| {
                line.spans
                    .iter()
                    .map(|span| display_width(span.content.as_ref()))
                    .sum::<u16>()
                    == width
            }));
            assert!(
                lines
                    .iter()
                    .flat_map(|line| &line.spans)
                    .all(|span| { span.style.bg == Some(crate::theme::DARK.user_message_bg) })
            );
        }

        let unicode = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text("🙂🙂🙂🙂🙂abc")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &unicode, true, true, crate::theme::DARK, 10);
        let plain = lines[1..lines.len() - 1]
            .iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        assert_eq!(plain[0].trim_end(), "🙂🙂🙂🙂");
        assert_eq!(plain[1].trim_end(), "🙂abc");
    }

    #[test]
    fn user_card_bounds_megabyte_fenced_block_with_fold_marker() {
        // A 1 MiB fenced/wrapped user block (the `MAX_PASTE_BYTES` paste
        // ceiling) must not materialize one row per payload line through the
        // real projection helper: the card keeps a bounded head with a
        // byte-truncation `… more content` fold marker and never renders the
        // payload tail. Storage keeps the full text; only the rendered card
        // is bounded.
        let line = format!("let value = 0x0f; // {}", "x".repeat(80));
        let body = std::iter::repeat_n(line.as_str(), 10_500)
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            body.len() >= MAX_PASTE_BYTES,
            "fixture must reach the paste ceiling"
        );
        let tail_sentinel = "PAYLOAD_TAIL_SENTINEL_9f3c";
        let payload = format!("```rust\n{body}\n{tail_sentinel}\n```");
        assert!(payload.len() >= MAX_PASTE_BYTES);
        let entry = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(payload)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &entry, true, true, crate::theme::DARK, 80);

        // Bounded: a fixed-size card, not one row per payload line. The card
        // is exactly two vertical padding rows around at most
        // `USER_CARD_RENDER_ROW_LIMIT` content rows (kept head + frame
        // bottom + fold marker) — the cap reserves both slots.
        assert!(
            lines.len() <= USER_CARD_RENDER_ROW_LIMIT + 2,
            "user card must stay bounded: {} rows for a 1 MiB block (limit {} + 2 padding)",
            lines.len(),
            USER_CARD_RENDER_ROW_LIMIT
        );
        assert!(
            lines.len().saturating_sub(2) <= USER_CARD_RENDER_ROW_LIMIT,
            "card content rows must respect the row limit"
        );
        // No full-payload output: the payload tail never reaches the card.
        let plain = lines.iter().map(rendered_line_text).collect::<String>();
        assert!(
            !plain.contains(tail_sentinel),
            "fold must drop the payload tail: {plain}"
        );
        // The byte budget cut the head inside the fence, so the marker is
        // the truthful byte-truncation shape: the tail's line count is
        // unknown without scanning it, and no fake line/row count may be
        // claimed.
        let marker = lines
            .iter()
            .map(rendered_line_text)
            .position(|row| row.contains("… more content"))
            .expect("fold marker must render");
        assert!(
            !plain.contains("more lines") && !plain.contains("more rows"),
            "byte-cut marker must not fake a count: {plain}"
        );
        // The cut landed inside the fence, so the head frame is capped with
        // a real bottom border directly above the marker — no dangling
        // side-bordered rows.
        assert!(
            rendered_line_text(&lines[marker - 1]).starts_with('╰'),
            "frame bottom must close the folded head: {:?}",
            lines[marker - 1]
        );
        // The card structure stays intact: symmetric padding edges and the
        // styled card background on every row.
        assert!(
            lines
                .first()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .last()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .iter()
                .flat_map(|line| &line.spans)
                .all(|span| { span.style.bg == Some(crate::theme::DARK.user_message_bg) })
        );
    }

    #[test]
    fn user_card_bounds_megabyte_single_line_block_with_fold_marker() {
        // A 1 MiB SINGLE-LINE (unfenced) user block bypasses the source-line
        // fold: the payload has no newlines, so the line budget keeps all of
        // it. The byte budget must cut the head FIRST (before any full
        // line scan, join, or markdown walk of the megabyte), and the final
        // row cap must bound the painted rows while keeping the fold marker
        // visible and the payload tail out of the card.
        let line = format!("let value = 0x0f; // {}", "x".repeat(80));
        let mut body = String::with_capacity(MAX_PASTE_BYTES + line.len());
        while body.len() < MAX_PASTE_BYTES {
            body.push_str(&line);
        }
        let tail_sentinel = "PAYLOAD_TAIL_SENTINEL_9f3c";
        let payload = format!("{body}{tail_sentinel}");
        assert!(
            payload.len() >= MAX_PASTE_BYTES,
            "fixture must reach the paste ceiling"
        );
        assert!(
            !payload.contains('\n'),
            "fixture must be a single unfenced line"
        );
        let entry = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(payload)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &entry, true, true, crate::theme::DARK, 80);

        // Strictly bounded: the card is exactly two vertical padding rows
        // around at most `USER_CARD_RENDER_ROW_LIMIT` content rows — not one
        // row per wrapped payload chunk.
        assert!(
            lines.len() <= USER_CARD_RENDER_ROW_LIMIT + 2,
            "user card must stay bounded: {} rows for a 1 MiB single-line block (limit {} + 2 padding)",
            lines.len(),
            USER_CARD_RENDER_ROW_LIMIT
        );
        assert!(
            lines.len().saturating_sub(2) <= USER_CARD_RENDER_ROW_LIMIT,
            "card content rows must respect the row limit"
        );
        // No full-payload output: the payload tail never reaches the card.
        let plain = lines.iter().map(rendered_line_text).collect::<String>();
        assert!(
            !plain.contains(tail_sentinel),
            "fold must drop the payload tail: {plain}"
        );
        // The byte budget cut the newline-free head, so the marker is the
        // truthful byte-truncation shape: the omitted tail is one line of
        // unknown length, and no fake line/row count may be claimed (the old
        // code reported a count from scanning the whole megabyte).
        let marker = lines
            .iter()
            .map(rendered_line_text)
            .position(|row| row.contains("… more content"))
            .expect("fold marker must render");
        assert!(
            !plain.contains("more lines") && !plain.contains("more rows"),
            "byte-cut marker must not fake a count: {plain}"
        );
        // The card structure stays intact: symmetric padding edges and the
        // styled card background on every row.
        assert!(
            lines
                .first()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .last()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .iter()
                .flat_map(|line| &line.spans)
                .all(|span| { span.style.bg == Some(crate::theme::DARK.user_message_bg) })
        );
    }

    #[test]
    fn user_card_bounds_megabyte_multibyte_single_line_block_with_fold_marker() {
        // A 1 MiB SINGLE-LINE block of multi-byte/combined graphemes (a ZWJ
        // family) must be cut by the byte budget at a grapheme boundary: the
        // rendered card stays bounded, the payload tail never reaches it,
        // and no cluster is split — the head is a clean prefix ending on a
        // whole grapheme even when the budget lands mid-cluster.
        let grapheme = "👨\u{200d}👩\u{200d}👧\u{200d}👦"; // one 11-byte ZWJ family
        let prefix = "xyz"; // odd-byte prefix so the budget lands mid-grapheme
        let mut payload = String::with_capacity(MAX_PASTE_BYTES + grapheme.len());
        payload.push_str(prefix);
        while payload.len() < MAX_PASTE_BYTES {
            payload.push_str(grapheme);
        }
        let tail_sentinel = "PAYLOAD_TAIL_SENTINEL_9f3c";
        payload.push_str(tail_sentinel);
        assert!(
            payload.len() >= MAX_PASTE_BYTES,
            "fixture must reach the paste ceiling"
        );
        assert!(
            !payload.contains('\n'),
            "fixture must be a single unfenced line"
        );

        // The bounded fold cuts at a whole grapheme: the head is a clean
        // prefix of the payload, never splits a cluster, and reports the
        // byte-truncation omission without counting the tail.
        let (head, omission) = fold_user_text_head(&payload, USER_CARD_TEXT_LINE_BUDGET);
        assert!(omission.bytes, "1 MiB single line must be byte-cut");
        assert_eq!(omission.lines, 0, "no source lines were folded");
        assert!(
            payload.starts_with(head.as_ref()),
            "head must be a clean prefix of the payload"
        );
        let cut = head.len();
        assert!(cut <= USER_CARD_TEXT_CHAR_BUDGET);
        assert!(
            payload.is_char_boundary(cut),
            "cut must not split a multi-byte char"
        );
        assert_eq!(
            cut,
            prefix.len()
                + ((USER_CARD_TEXT_CHAR_BUDGET - prefix.len()) / grapheme.len()) * grapheme.len(),
            "cut must land exactly on a whole-grapheme boundary"
        );
        let rest = &payload[cut..];
        let next_grapheme = rest.graphemes(true).next().expect("tail must not be empty");
        assert!(
            rest.starts_with(next_grapheme),
            "the cluster at the cut must be complete"
        );

        let entry = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(payload)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &entry, true, true, crate::theme::DARK, 80);

        // Strictly bounded: exactly two padding rows around at most the row
        // limit of content rows.
        assert!(
            lines.len() <= USER_CARD_RENDER_ROW_LIMIT + 2,
            "user card must stay bounded: {} rows for a 1 MiB multi-byte single-line block (limit {} + 2 padding)",
            lines.len(),
            USER_CARD_RENDER_ROW_LIMIT
        );
        assert!(lines.len().saturating_sub(2) <= USER_CARD_RENDER_ROW_LIMIT);
        // No full-payload output and a truthful byte-truncation marker.
        let plain = lines.iter().map(rendered_line_text).collect::<String>();
        assert!(
            !plain.contains(tail_sentinel),
            "fold must drop the payload tail: {plain}"
        );
        assert!(
            plain.contains("… more content"),
            "byte-cut marker must render: {plain}"
        );
        assert!(
            !plain.contains("more lines") && !plain.contains("more rows"),
            "byte-cut marker must not fake a count: {plain}"
        );
        // The card structure stays intact: symmetric padding edges and the
        // styled card background on every row.
        assert!(
            lines
                .first()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .last()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .iter()
                .flat_map(|line| &line.spans)
                .all(|span| { span.style.bg == Some(crate::theme::DARK.user_message_bg) })
        );
    }

    #[test]
    fn user_card_folds_long_multiline_block_with_exact_line_count() {
        // A multi-line message under the byte budget is folded by the line
        // budget only: the omitted count is exact because it is counted over
        // the whole (at most 16 KiB) text — the marker reports the true
        // omitted source lines, and the final cap reserves the marker slot
        // so kept head + marker never exceed the row limit.
        let line = "short line content";
        let body = std::iter::repeat_n(line, 300)
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            body.len() < USER_CARD_TEXT_CHAR_BUDGET,
            "fixture must stay under the byte budget"
        );
        let entry = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(body)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &entry, true, true, crate::theme::DARK, 80);

        // 300 short lines → 120-line head painting 120 rows; the cap keeps
        // 119 (reserving the marker slot) and the marker reports the exact
        // 180 folded source lines: 2 padding + 119 kept + 1 marker = 122.
        assert_eq!(
            lines.len(),
            USER_CARD_RENDER_ROW_LIMIT + 2,
            "2 padding + reserved-head + marker must be exactly limit + padding: {}",
            lines.len()
        );
        let plain = lines.iter().map(rendered_line_text).collect::<String>();
        assert!(
            plain.contains("… 180 more lines"),
            "fold marker must report the exact omitted source lines: {plain}"
        );
        assert!(
            !plain.contains("more rows") && !plain.contains("more content"),
            "line fold must not borrow the row/byte wording: {plain}"
        );
        assert!(
            lines
                .first()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
        assert!(
            lines
                .last()
                .is_some_and(|line| line.spans.iter().all(|span| span.content.trim().is_empty()))
        );
    }

    #[test]
    fn user_card_megabyte_block_keeps_full_projection_window_bounded() {
        // Whole-transcript projection (the real frame path): after the fold
        // the assembled transcript stays tiny, follow-mode scroll lands
        // exactly at the bottom window, and the payload tail never enters
        // the projection.
        let line = format!("let value = 0x0f; // {}", "x".repeat(80));
        let body = std::iter::repeat_n(line.as_str(), 10_500)
            .collect::<Vec<_>>()
            .join("\n");
        let tail_sentinel = "PAYLOAD_TAIL_SENTINEL_9f3c";
        let payload = format!("```rust\n{body}\n{tail_sentinel}\n```");
        let mut state = todo_test_state(Vec::new());
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(payload)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        let mut renderer = TerminalImageRenderer::default();
        let mut candidates = Vec::new();
        let mut image_context = TranscriptImageContext {
            renderer: &mut renderer,
            candidates: &mut candidates,
            config: ImageDisplayConfig {
                show_images: false,
                width_cells: 50,
            },
            viewport_columns: 80,
            viewport_rows: 24,
            cell_size: TerminalCellSize::default(),
        };
        let (lines, starts) =
            render_transcript_lines(&state, crate::theme::DARK, 80, &mut image_context);
        let total_rows = wrapped_line_count(&lines, 80);
        assert!(
            total_rows <= USER_CARD_RENDER_ROW_LIMIT + 16,
            "projection must stay bounded: {total_rows} rows"
        );
        let scroll = transcript_scroll_offset(&state, &starts, total_rows, 24);
        assert_eq!(
            scroll,
            total_rows.saturating_sub(24),
            "follow mode sits at the bottom window"
        );
        let plain = lines.iter().map(rendered_line_text).collect::<String>();
        assert!(
            !plain.contains(tail_sentinel),
            "payload tail must not reach the projection"
        );
        assert!(
            plain.contains("… more content"),
            "fold marker must render: {plain}"
        );
    }

    #[test]
    fn compact_roles_hide_repeated_labels_and_empty_entries() {
        let assistant = TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text("answer")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let user = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text("prompt")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let empty = TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text("  "), ContentBlock::thinking("hidden")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let reasoning = TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![
                ContentBlock::thinking("useful analysis"),
                ContentBlock::text("answer"),
            ],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };

        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, &user, true, true, crate::theme::DARK, 80);
        render_transcript_entry(&mut lines, &assistant, true, true, crate::theme::DARK, 80);
        let text = lines
            .iter()
            .flat_map(|line| &line.spans)
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(!text.contains("You"));
        assert!(!text.contains("Assistant"));
        let user_content = lines
            .iter()
            .find(|line| {
                line.spans
                    .iter()
                    .any(|span| span.content.starts_with("prompt"))
            })
            .expect("user content row");
        assert!(user_content.spans[0].content.starts_with("prompt"));
        assert_eq!(
            user_content.spans[0].style.bg,
            Some(crate::theme::DARK.user_message_bg)
        );

        let before = lines.len();
        render_transcript_entry(&mut lines, &empty, false, true, crate::theme::DARK, 80);
        assert_eq!(lines.len(), before);

        let mut reasoning_lines = Vec::new();
        render_transcript_entry(
            &mut reasoning_lines,
            &reasoning,
            true,
            true,
            crate::theme::DARK,
            80,
        );
        assert!(
            reasoning_lines
                .iter()
                .flat_map(|line| &line.spans)
                .all(|span| span.content.as_ref() != "thinking ·"),
            "thinking block must render without a 'thinking ·' label: {reasoning_lines:?}"
        );
        assert!(
            reasoning_lines
                .iter()
                .flat_map(|line| &line.spans)
                .all(|span| {
                    span.content.as_ref() != "Reasoning"
                        && !span.content.contains("Reasoning hidden")
                })
        );
        let plain = reasoning_lines
            .iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        let thinking_row = plain
            .iter()
            .position(|line| line == "useful analysis")
            .unwrap();
        let answer_row = plain.iter().position(|line| line == "answer").unwrap();
        assert_eq!(answer_row, thinking_row + 2);
        assert_eq!(plain[thinking_row + 1], "");
    }

    // ---- typed user message projection: caption / images / vision analysis ----
    // Reported regression: the user bubble dumped the raw `<attachment>`
    // transport wrapper and the auto-vision `[Image analyzed by …]`
    // description as if they were the user's own text. The TUI now projects
    // the three surfaces like the Web's `userMessageProjection`: the user's
    // REAL caption, real image previews (in order), and a typed fold card
    // labeled "Image analysis".

    fn image_block(data: &str, mime_type: &str) -> ContentBlock {
        ContentBlock::Image {
            data: data.to_owned(),
            mime_type: mime_type.to_owned(),
        }
    }

    fn rendered_text(entry: &TranscriptEntry, width: u16) -> Vec<String> {
        let mut lines = Vec::new();
        render_transcript_entry(&mut lines, entry, true, true, crate::theme::DARK, width);
        lines.iter().map(rendered_line_text).collect()
    }

    #[test]
    fn user_projection_splits_caption_images_and_vision_analysis() {
        // Contract: the user bubble shows the user's REAL caption, the image
        // preview, and a typed `Image analysis` card — never the
        // `<attachment>` transport wrapper, never the backend's
        // `[Image analyzed by …]` marker as the user's own text.
        let entry = TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![
                ContentBlock::text("<attachment type=\"image/png\">ref-1</attachment>"),
                image_block(
                    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==",
                    "image/png",
                ),
                ContentBlock::text("[Image analyzed by vm: a diagram]"),
                ContentBlock::text("这个图是什么"),
            ],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        };
        let rows = rendered_text(&entry, 60);
        let text = rows.join("\n");
        assert!(
            text.contains("这个图是什么"),
            "real caption must render: {text}"
        );
        assert!(
            text.contains("[image attachment: image/png]"),
            "image preview must render: {text}"
        );
        assert!(
            text.contains("Image analysis · vm"),
            "typed analysis card must render: {text}"
        );
        assert!(
            text.contains("a diagram"),
            "analysis description must render: {text}"
        );
        assert!(
            !text.contains("<attachment"),
            "transport wrapper must be dropped: {text}"
        );
        assert!(
            !text.contains("ref-1"),
            "wrapper inner reference must be dropped: {text}"
        );
        assert!(
            !text.contains("[Image analyzed by"),
            "marker must never render as user text: {text}"
        );
    }

