    #[test]
    fn bash_card_multiline_command_renders_lines_intact_with_single_dollar() {
        // Strips the `│ ` / ` │` card frame and fill padding from one
        // rendered row, leaving its text content.
        fn row_text(row: &str) -> &str {
            row.strip_prefix("│ ")
                .unwrap_or(row)
                .strip_suffix(" │")
                .unwrap_or(row)
                .trim()
        }
        use pi_agent::AgentToolResult;
        let mut state = todo_test_state(Vec::new());
        state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionStart {
            tool_call_id: "bash".to_owned(),
            tool_name: "bash".to_owned(),
            arguments: serde_json::json!({"command": "CA=/tmp/oh-my-pi\n# session-context\nbuildrg -n \"export fu\""}),
        }));
        state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionEnd {
            tool_call_id: "bash".to_owned(),
            tool_name: "bash".to_owned(),
            result: AgentToolResult::text("match-1"),
            is_error: false,
        }));
        let mut lines = Vec::new();
        render_transcript_entry(
            &mut lines,
            state.transcript.last().unwrap(),
            true,
            false,
            crate::theme::DARK,
            80,
        );
        let rendered = lines
            .iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        // User-reported flattening: a raw line feed must never survive inside
        // a rendered row (it painted as a garbled control character).
        assert!(
            !rendered.iter().any(|line| line.contains('\n')),
            "no raw LF may reach a rendered row: {rendered:?}"
        );
        let top = rendered
            .iter()
            .position(|line| line.starts_with('╭'))
            .expect("top border");
        let output = rendered
            .iter()
            .position(|line| line.contains("Output"))
            .expect("output separator");
        let command_rows = &rendered[top + 1..output];
        assert_eq!(
            command_rows.len(),
            3,
            "one row per command line: {rendered:?}"
        );
        assert!(
            row_text(&command_rows[0]).starts_with("$ CA=/tmp/oh-my-pi"),
            "env assignment on the first row: {command_rows:?}"
        );
        assert!(
            row_text(&command_rows[1]).starts_with("# session-context"),
            "comment line kept: {command_rows:?}"
        );
        assert!(
            row_text(&command_rows[2]).starts_with("buildrg -n \"export fu\""),
            "third line kept: {command_rows:?}"
        );
        // The `$ ` prefix appears on the first command row only.
        assert!(
            !command_rows[1].contains('$'),
            "no $ prefix on continuation rows: {command_rows:?}"
        );
        assert!(
            !command_rows[2].contains('$'),
            "no $ prefix on continuation rows: {command_rows:?}"
        );
        let command_text = command_rows.concat();
        assert!(
            command_text.contains("CA=/tmp/oh-my-pi"),
            "full command text renders: {command_text:?}"
        );
        assert!(
            command_text.contains("# session-context"),
            "comment renders: {command_text:?}"
        );
    }

    #[test]
    fn bash_card_leading_comments_render_on_frame_and_dollar_starts_command() {
        // Strips the `│ ` / ` │` card frame and fill padding from one
        // rendered row, leaving its text content.
        fn row_text(row: &str) -> &str {
            row.strip_prefix("│ ")
                .unwrap_or(row)
                .strip_suffix(" │")
                .unwrap_or(row)
                .trim()
        }
        use pi_agent::AgentToolResult;
        let mut state = todo_test_state(Vec::new());
        state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionStart {
            tool_call_id: "bash".to_owned(),
            tool_name: "bash".to_owned(),
            arguments: serde_json::json!({"command": "# Key layering of sibling crates\n# cargo workspace first\n# third dropped\necho a\n# i1\necho b\necho c\necho d\necho e"}),
        }));
        state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionEnd {
            tool_call_id: "bash".to_owned(),
            tool_name: "bash".to_owned(),
            result: AgentToolResult::text("ok"),
            is_error: false,
        }));
        let mut lines = Vec::new();
        render_transcript_entry(
            &mut lines,
            state.transcript.last().unwrap(),
            true,
            false,
            crate::theme::DARK,
            80,
        );
        let rendered = lines
            .iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        // The first leading comment titles the top border; the second renders
        // as a frame row above the command; deeper ones are dropped (bounded).
        let top = rendered
            .iter()
            .position(|line| line.starts_with('╭'))
            .expect("top border");
        assert!(
            rendered[top].contains("# Key layering of sibling crates"),
            "first comment on the top border: {:?}",
            rendered[top]
        );
        assert!(
            !rendered[top].contains('$'),
            "no $ on the border: {:?}",
            rendered[top]
        );
        let output = rendered
            .iter()
            .position(|line| line.contains("Output"))
            .expect("output separator");
        let rows = &rendered[top + 1..output];
        assert_eq!(
            rows.len(),
            5,
            "one comment frame row + 4 bounded command rows: {rendered:?}"
        );
        assert!(
            row_text(&rows[0]).starts_with("# cargo workspace first"),
            "second comment as a frame row: {rows:?}"
        );
        assert!(
            !rows[0].contains('$'),
            "comment frame row has no $ prefix: {rows:?}"
        );
        assert!(
            row_text(&rows[1]).starts_with("$ echo a"),
            "$ starts the first real command: {rows:?}"
        );
        assert!(
            row_text(&rows[2]).starts_with("# i1"),
            "interior comment stays in the body: {rows:?}"
        );
        assert!(
            !rows[2].contains('$'),
            "interior comment has no $ prefix: {rows:?}"
        );
        assert!(
            row_text(&rows[3]).starts_with("echo b"),
            "body line kept: {rows:?}"
        );
        assert_eq!(
            row_text(&rows[4]),
            "…",
            "fold marker closes the body: {rows:?}"
        );
        let joined = rows.concat();
        assert!(
            !joined.contains("$ #"),
            "a comment must never ride the $ row: {rows:?}"
        );
        assert!(
            !joined.contains("third dropped"),
            "comments past the second are dropped (bounded): {rows:?}"
        );
        assert!(
            !joined.contains("echo c"),
            "dropped body tail must not render: {rows:?}"
        );
    }

