    #[test]
    fn status_changed_survives_leftover_transient_ttl() {
        use crate::extension_ui::ExtensionStatusItem;
        use pi_coding::ExtensionInstanceId;

        let adapter = ExtensionUiAdapter::new();
        let mut state = dialog_test_state(adapter.clone());
        let demo = ExtensionInstanceId {
            extension_id: "demo".to_owned(),
            generation: 1,
        };

        state.set_transient_status("Resumed 3 messages".to_owned());
        assert!(state.status_expires_at.is_some());

        state.apply_extension_ui(ExtensionUiEvent::StatusChanged {
            item: ExtensionStatusItem {
                instance: demo,
                key: "progress".to_owned(),
                text: "loading".to_owned(),
            },
        });
        assert_eq!(state.status, "loading");
        assert!(state.extension_status_key.is_some());
        assert!(
            state.status_expires_at.is_none(),
            "StatusChanged must drop leftover transient TTL"
        );

        let past =
            std::time::Instant::now() + TRANSIENT_STATUS_TTL + std::time::Duration::from_millis(1);
        state.expire_transient_status(past);
        assert_eq!(
            state.status, "loading",
            "extension status must remain after leftover transient TTL elapses"
        );
    }

