    #[test]
    fn scroll_up_window_survives_mermaid_growth_and_resize() {
        // Regression for the scroll-up history loss: the transcript window
        // must stay anchored to the content the user is reading. A mermaid
        // block at the bottom that GROWS between frames (fence closing:
        // streaming code block → tall source-fallback diagram, or a resize
        // reflow) must not drag the scrolled-up window down with it.
        // Bottom-anchored row math (`scroll = bottom - transcript_scroll`)
        // drifted by exactly the height delta, so the rows under/above the
        // mermaid appeared to vanish when scrolling up. The window is now
        // anchored to (entry, row-offset) and re-mapped each frame.
        let mermaid_partial = "```mermaid\nflowchart TB\n    subgraph L0[\"pi-cli";
        let mermaid_full = "```mermaid\nflowchart TB\n    subgraph L0[\"pi-cli — crates/pi-cli\"]\n        TUI[\"TUI 面板 / REPL<br/>tui.rs · repl.rs\"]\n        RPC[\"JSON-RPC / ACP 模式<br/>rpc.rs · acp.rs\"]\n        CMD[\"子命令 · 会话编排<br/>interactive_commands.rs · session_run.rs\"]\n    end\n    subgraph L1[\"pi-coding — crates/pi-coding（本图主体）\"]\n        APP[\"Application 状态机<br/>application.rs\"]\n        SESS[\"Session 回合执行<br/>session.rs\"]\n        SUB[\"工具 · 编排 · 工作流<br/>扩展 · 配置 · 持久化\"]\n    end\n    subgraph L2[\"pi-agent — crates/pi-agent\"]\n        AGENT[\"Agent 循环<br/>agent.rs · loop_runtime.rs\"]\n    end\n    subgraph L3[\"pi-ai — crates/pi-ai\"]\n        PROV[\"providers/<br/>anthropic · openai · responses · codex · gemini...\"]\n        CAT[\"模型目录 · 流式 · 重试 · 超时<br/>catalog.rs · stream.rs\"]\n    end\n    TUI --> APP\n    RPC --> APP\n    CMD --> APP\n    APP --> SESS\n    SESS --> AGENT\n    AGENT --> PROV\n    PROV --> CAT\n```";
        let mut state = todo_test_state(Vec::new());
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text("explain the architecture")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text("short reply above the diagram")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        // Taller history so the scrolled-up window lands mid-transcript
        // (not pinned to the top), like a real session with prior turns.
        for turn in 0..5 {
            state.push_entry(TranscriptEntry {
                kind: TranscriptKind::User,
                content: vec![ContentBlock::text(format!(
                    "follow-up question {turn} with enough words to wrap across the width"
                ))],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            });
            state.push_entry(TranscriptEntry { kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text(format!(
                "answer {turn} describing the layered design and the data flow through the components"
            ))],
            tool_name: None, tool_card: None, is_error: false, is_partial: false, });
        }
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text(mermaid_partial)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        let mermaid_index = state.transcript.len() - 1;
        let height = 15usize;
        let render = |state: &mut TuiState, width: u16| -> (Vec<String>, usize, usize) {
            let mut renderer = TerminalImageRenderer::default();
            let mut candidates = Vec::new();
            let mut image_context = TranscriptImageContext {
                renderer: &mut renderer,
                candidates: &mut candidates,
                config: ImageDisplayConfig {
                    show_images: false,
                    width_cells: 50,
                },
                viewport_columns: width,
                viewport_rows: u16::try_from(height).unwrap(),
                cell_size: TerminalCellSize::default(),
            };
            let (lines, starts) =
                render_transcript_lines(state, crate::theme::DARK, width, &mut image_context);
            let total_rows = wrapped_line_count(&lines, width);
            let scroll = transcript_scroll_offset(state, &starts, total_rows, height);
            let plain: Vec<String> = lines
                .iter()
                .map(|line| {
                    line.spans
                        .iter()
                        .map(|span| span.content.as_ref())
                        .collect::<String>()
                })
                .collect();
            (plain, scroll, total_rows)
        };

        // Following: window sits at the bottom (tail visible).
        let (_, scroll_follow, total_rows) = render(&mut state, 80);
        assert_eq!(
            scroll_follow,
            total_rows.saturating_sub(height),
            "follow shows the tail"
        );

        // Scroll up two pages.
        state.page_transcript(-1);
        state.page_transcript(-1);
        let (plain_before, scroll_before, _) = render(&mut state, 80);
        assert!(scroll_before < scroll_follow, "PageUp moved the window up");
        let top_line_before = plain_before[scroll_before].clone();
        let anchor_before = state.scroll_anchor.get();
        let top_row_before = state.transcript_top_row.get();

        // The mermaid entry settles/grows BELOW the window (fence closes:
        // short code block → tall source-fallback diagram). The window must
        // not drift: the old bottom-anchored math moved by exactly the delta.
        state.transcript[mermaid_index].content = vec![ContentBlock::text(mermaid_full.to_owned())];
        let (plain_after, scroll_after, total_after) = render(&mut state, 80);
        assert!(
            total_after > total_rows,
            "the grown mermaid must make the transcript taller"
        );
        assert_eq!(
            scroll_after, scroll_before,
            "window top must stay put when content below the window grows"
        );
        assert_eq!(
            plain_after[scroll_after], top_line_before,
            "the window must keep showing the same content row"
        );
        assert_eq!(state.scroll_anchor.get(), anchor_before);
        assert_eq!(state.transcript_top_row.get(), top_row_before);

        // Resize: re-anchor keeps the window in the same transcript entry.
        let (_, scroll_w100, _) = render(&mut state, 100);
        assert_eq!(
            state.scroll_anchor.get().0,
            anchor_before.0,
            "resize keeps the entry"
        );
        let _ = scroll_w100;
        let (_, scroll_w40, _) = render(&mut state, 40);
        assert_eq!(
            state.scroll_anchor.get().0,
            anchor_before.0,
            "narrow resize keeps the entry"
        );
        let _ = scroll_w40;

        // Every row of the grown transcript must be reachable at every width:
        // sweep all window positions and union their coverage.
        for width in [40u16, 80, 100, 140] {
            let (plain, _, total) = render(&mut state, width);
            let bottom = total.saturating_sub(height);
            let mut covered = vec![false; total];
            for top in 0..=bottom {
                state.transcript_top_row.set(Some(top));
                state.scroll_moved.set(true);
                let (_, scroll, _) = render(&mut state, width);
                assert_eq!(scroll, top.min(bottom), "raw top honored for the sweep");
                for row in scroll..(scroll + height).min(total) {
                    covered[row] = true;
                }
            }
            let missing: Vec<usize> = covered
                .iter()
                .enumerate()
                .filter_map(|(index, covered)| (!covered).then_some(index))
                .collect();
            assert!(
                missing.is_empty(),
                "width {width}: rows {missing:?} are unreachable by any scroll window"
            );
            let mermaid_start = plain.iter().position(|line| line.contains("┌─ mermaid"));
            let mermaid_end = plain.iter().rposition(|line| line.contains("└─"));
            assert!(
                mermaid_start.is_some() && mermaid_end.is_some(),
                "width {width}: mermaid frame must render (source fallback)"
            );
            assert!(
                covered[mermaid_start.unwrap()] && covered[mermaid_end.unwrap()],
                "width {width}: mermaid frame rows must be reachable"
            );
        }

        // Scrolling back down resumes following with the tail visible.
        loop {
            state.page_transcript(1);
            render(&mut state, 80);
            if state.transcript_top_row.get().is_none() {
                break;
            }
        }
        let (plain, scroll_tail, total_tail) = render(&mut state, 80);
        assert_eq!(scroll_tail, total_tail.saturating_sub(height));
        assert!(plain[scroll_tail..].iter().any(|line| line.contains("└─")));
    }

    #[test]
    fn mermaid_stays_reachable_scrolling_up_through_real_render() {
        // Acceptance: build a transcript with a mermaid entry, scroll up
        // through it at multiple widths + a resize, driving the REAL render()
        // path (full Terminal draw). No rows vanish: the mermaid frame and
        // the rows around it stay reachable at every width.
        use ratatui::backend::TestBackend;
        let mermaid = "```mermaid\nflowchart TD\nA[Start] --> B[Load data]\nB --> C{Ready?}\nC -->|yes| D[Go]\nC -->|no| E[Wait]\nD --> F[Done]\n```";
        let mut state = todo_test_state(Vec::new());
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text("draw the flow")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text(mermaid)],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text("done")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        let mut images = TerminalImageRenderer::default();
        let mut draw = |terminal: &mut Terminal<TestBackend>, state: &TuiState| -> Vec<String> {
            terminal
                .draw(|frame| {
                    let _ = render(frame, state, &mut images);
                })
                .unwrap();
            let cells = terminal.backend().buffer();
            let width = usize::from(terminal.backend().buffer().area.width);
            cells
                .content
                .chunks(width)
                .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
                .collect()
        };
        for width in [80u16, 60, 100] {
            let mut terminal = Terminal::new(TestBackend::new(width, 24)).unwrap();
            let mut saw_header = false;
            let mut saw_closer = false;
            let mut saw_tail = false;
            // Follow: the mermaid is visible at the bottom.
            let rows = draw(&mut terminal, &state);
            saw_header |= rows.iter().any(|row| row.contains("┌─ mermaid"));
            saw_closer |= rows.iter().any(|row| row.trim() == "└─");
            saw_tail |= rows.iter().any(|row| row.contains("done"));
            // PageUp all the way to the top; the mermaid frame must be
            // visible at some point and the surrounding text stay reachable.
            for _ in 0..12 {
                state.page_transcript(-1);
                let rows = draw(&mut terminal, &state);
                saw_header |= rows.iter().any(|row| row.contains("┌─ mermaid"));
                saw_closer |= rows.iter().any(|row| row.trim() == "└─");
                saw_tail |= rows.iter().any(|row| row.contains("done"));
            }
            assert!(
                saw_header,
                "width {width}: mermaid header must be reachable on scroll-up"
            );
            assert!(
                saw_closer,
                "width {width}: mermaid closer must be reachable on scroll-up"
            );
            assert!(saw_tail, "width {width}: trailing text must stay reachable");
            // Scroll back down to follow.
            for _ in 0..12 {
                state.page_transcript(1);
                draw(&mut terminal, &state);
                if state.transcript_top_row.get().is_none() {
                    break;
                }
            }
            let rows = draw(&mut terminal, &state);
            assert!(
                rows.iter().any(|row| row.trim() == "└─"),
                "width {width}: tail visible when following"
            );
        }
    }

    /// Regression for the strict-Psy long-session blank-frame / lost-bottom
    /// contract: driving the REAL `render()` path, PageUp to the top and
    /// PageDown back to the bottom must be deterministic at every terminal
    /// size (170x45, 120x36, 80x24, 60x20), every intermediate frame's
    /// transcript region must be non-empty (no blank frames), the composer
    /// must stay visible, and a mid-scroll resize must keep the scroll offset
    /// clamped to `[0, bottom]` with a stable anchor entry. This is the
    /// unit-level mirror of the tmux PSY-03/05 four-size sweep.
    #[test]
    fn page_scroll_to_top_and_back_keeps_every_frame_nonempty_and_recovers_bottom() {
        use ratatui::backend::TestBackend;
        // A long transcript that overflows the viewport at every tested size
        // (tall mermaid + many wrapped assistant turns + user cards), modeled
        // on the Psy long-session shape that produced blank frames.
        let mermaid = "```mermaid\nflowchart TD\n    subgraph L0[\"pi-cli — crates/pi-cli\"]\n        TUI[\"TUI 面板 / REPL<br/>tui.rs · repl.rs\"]\n        RPC[\"JSON-RPC / ACP 模式<br/>rpc.rs · acp.rs\"]\n    end\n    subgraph L1[\"pi-coding — crates/pi-coding\"]\n        APP[\"Application 状态机<br/>application.rs\"]\n        SESS[\"Session 回合执行<br/>session.rs\"]\n    end\n    TUI --> APP\n    RPC --> APP\n    APP --> SESS\n```";
        let mut state = todo_test_state(Vec::new());
        for turn in 0..18u32 {
            state.push_entry(TranscriptEntry {
                kind: TranscriptKind::User,
                content: vec![ContentBlock::text(format!(
                    "user turn {turn}: please summarize the next module and draw the diagram"
                ))],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            });
            let mut prose = String::new();
            for line in 0..6 {
                prose.push_str(&format!(
                    "Turn {turn} line {line}: the rendering pipeline keeps a bounded live tail \
                     and drains the hydrated prefix to native scrollback across frames.\n"
                ));
            }
            if turn == 4 || turn == 12 {
                prose.push_str(mermaid);
                prose.push('\n');
            }
            state.push_entry(TranscriptEntry {
                kind: TranscriptKind::Assistant,
                content: vec![ContentBlock::text(prose)],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            });
        }

        let mut images = TerminalImageRenderer::default();
        let transcript_rect = |state: &TuiState, area: ratatui::layout::Rect| {
            let content = live_content_rect(area);
            let height = transcript_region_height(state, area.width, area.height);
            ratatui::layout::Rect {
                x: content.x,
                y: content.y,
                width: content.width,
                height,
            }
        };
        let mut render_buffer =
            |terminal: &mut Terminal<TestBackend>, state: &TuiState| -> Vec<String> {
                terminal
                    .draw(|frame| {
                        let _ = render(frame, state, &mut images);
                    })
                    .unwrap();
                let buf = terminal.backend().buffer();
                let w = usize::from(buf.area.width);
                buf.content
                    .chunks(w)
                    .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
                    .collect()
            };
        let region_nonempty = |rows: &[String], rect: ratatui::layout::Rect| {
            let y0 = usize::from(rect.y);
            let y1 = (y0 + usize::from(rect.height)).min(rows.len());
            let x0 = usize::from(rect.x);
            let x1 = x0 + usize::from(rect.width);
            rows[y0..y1].iter().any(|row| {
                row.chars()
                    .skip(x0)
                    .take(x1.saturating_sub(x0))
                    .any(|c| !c.is_whitespace())
            })
        };
        let composer_visible = |rows: &[String]| rows.iter().any(|row| row.contains('╭'));
        let scroll_now = |state: &TuiState| {
            state
                .transcript_top_row
                .get()
                .unwrap_or_else(|| state.transcript_scroll_bottom.get())
        };

        let sizes = [(170u16, 45u16), (120, 36), (80, 24), (60, 20)];
        for &(w, h) in &sizes {
            let mut terminal = Terminal::new(TestBackend::new(w, h)).unwrap();
            // Each size starts from follow, mirroring a fresh launch at that
            // terminal size (the scroll state must not leak from a prior size).
            state.follow_transcript();
            // Follow: bottom window, non-empty region, composer visible.
            let rows = render_buffer(&mut terminal, &state);
            let rect = transcript_rect(&state, terminal.backend().buffer().area);
            assert!(
                region_nonempty(&rows, rect),
                "size {w}x{h}: follow transcript region empty"
            );
            assert!(
                composer_visible(&rows),
                "size {w}x{h}: follow composer missing"
            );
            let bottom = state.transcript_scroll_bottom.get();
            assert_eq!(
                scroll_now(&state),
                bottom,
                "size {w}x{h}: follow must sit at bottom"
            );
            let follow_hash: u64 = {
                let mut hasher = DefaultHasher::new();
                rows.join("\n").hash(&mut hasher);
                hasher.finish()
            };

            // PageUp to the top: every frame non-empty + composer visible,
            // scroll strictly non-increasing and lands at 0.
            let mut prev_scroll = bottom;
            let mut reached_top = false;
            for _ in 0..64 {
                state.page_transcript(-1);
                let rows = render_buffer(&mut terminal, &state);
                let rect = transcript_rect(&state, terminal.backend().buffer().area);
                assert!(
                    region_nonempty(&rows, rect),
                    "size {w}x{h}: PageUp produced a blank transcript region at scroll {}",
                    scroll_now(&state)
                );
                assert!(
                    composer_visible(&rows),
                    "size {w}x{h}: PageUp lost composer"
                );
                let s = scroll_now(&state);
                assert!(
                    s <= prev_scroll,
                    "size {w}x{h}: PageUp must not move down: {s} > {prev_scroll}"
                );
                prev_scroll = s;
                if s == 0 {
                    reached_top = true;
                    break;
                }
            }
            assert!(
                reached_top,
                "size {w}x{h}: PageUp never reached the top (scroll={prev_scroll})"
            );

            // PageDown back to the bottom: every frame non-empty + composer
            // visible, scroll strictly non-decreasing, and the final follow
            // frame hashes byte-identically to the original follow frame
            // (deterministic bottom recovery, no content loss).
            let mut prev_scroll = 0usize;
            let mut reached_bottom = false;
            for _ in 0..64 {
                state.page_transcript(1);
                let rows = render_buffer(&mut terminal, &state);
                let rect = transcript_rect(&state, terminal.backend().buffer().area);
                assert!(
                    region_nonempty(&rows, rect),
                    "size {w}x{h}: PageDown produced a blank transcript region at scroll {}",
                    scroll_now(&state)
                );
                assert!(
                    composer_visible(&rows),
                    "size {w}x{h}: PageDown lost composer"
                );
                let s = scroll_now(&state);
                assert!(
                    s >= prev_scroll,
                    "size {w}x{h}: PageDown must not move up: {s} < {prev_scroll}"
                );
                prev_scroll = s;
                if state.transcript_top_row.get().is_none() {
                    reached_bottom = true;
                    break;
                }
            }
            assert!(
                reached_bottom,
                "size {w}x{h}: PageDown never returned to follow (scroll={prev_scroll})"
            );
            let rows = render_buffer(&mut terminal, &state);
            let rect = transcript_rect(&state, terminal.backend().buffer().area);
            assert!(
                region_nonempty(&rows, rect),
                "size {w}x{h}: recovered bottom transcript region empty"
            );
            assert!(
                composer_visible(&rows),
                "size {w}x{h}: recovered bottom composer missing"
            );
            let mut hasher = DefaultHasher::new();
            rows.join("\n").hash(&mut hasher);
            assert_eq!(
                hasher.finish(),
                follow_hash,
                "size {w}x{h}: bottom frame must be byte-identical after up-then-down (bottom hash not recovered)"
            );

            // Mid-scroll resize: page up partway, then resize across all four
            // widths. The scroll offset must stay clamped to `[0, bottom]`,
            // the anchor entry must stay stable, and every resized frame's
            // transcript region must stay non-empty.
            state.page_transcript(-1);
            state.page_transcript(-1);
            let _ = render_buffer(&mut terminal, &state);
            let anchor_entry_before = state.scroll_anchor.get().0;
            for &(rw, rh) in &sizes {
                let mut t2 = Terminal::new(TestBackend::new(rw, rh)).unwrap();
                let rows = render_buffer(&mut t2, &state);
                let rect = transcript_rect(&state, t2.backend().buffer().area);
                assert!(
                    region_nonempty(&rows, rect),
                    "resize {w}x{h}->{rw}x{rh}: transcript region empty"
                );
                assert!(
                    composer_visible(&rows),
                    "resize {w}x{h}->{rw}x{rh}: composer missing"
                );
                let bottom = state.transcript_scroll_bottom.get();
                let s = scroll_now(&state);
                assert!(
                    s <= bottom,
                    "resize {w}x{h}->{rw}x{rh}: scroll {s} exceeds bottom {bottom} (offset clamp broken)"
                );
                assert!(
                    state.scroll_anchor.get().0 == anchor_entry_before || s == bottom,
                    "resize {w}x{h}->{rw}x{rh}: anchor entry drifted from {anchor_entry_before} to {}",
                    state.scroll_anchor.get().0
                );
            }
        }
    }

    #[test]
    fn transcript_commit_boundary_preserves_visible_adjacency() {
        let entries = vec![
            TranscriptEntry {
                kind: TranscriptKind::User,
                content: vec![ContentBlock::text("committed user")],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            },
            TranscriptEntry {
                kind: TranscriptKind::Assistant,
                content: vec![ContentBlock::text("live assistant")],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            },
        ];
        let expected = assemble_transcript_entries(&entries, true, true, crate::theme::DARK, 40);
        let mut split = assemble_committed_transcript_entries(
            &entries[..1],
            true,
            true,
            crate::theme::DARK,
            40,
            true,
        );
        split.extend(assemble_transcript_entries(
            &entries[1..],
            true,
            true,
            crate::theme::DARK,
            40,
        ));
        assert_eq!(split, expected);

        let mut state = todo_test_state(Vec::new());
        state.transcript = vec![
            entries[0].clone(),
            TranscriptEntry {
                kind: TranscriptKind::Assistant,
                content: vec![ContentBlock::thinking("hidden")],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            },
        ];
        state.show_thinking = false;
        assert!(!state.has_visible_entry_after(1));
        state.streaming_text = "partial answer".to_owned();
        assert!(state.has_visible_entry_after(1));
        state.streaming_text.clear();
        state.streaming_thinking = "hidden partial thinking".to_owned();
        assert!(!state.has_visible_entry_after(1));
        state.show_thinking = true;
        assert!(state.has_visible_entry_after(1));
    }
