    #[test]
    fn goal_panel_items_follow_pause_reason() {
        let state = |lifecycle: &str, pause_reason: serde_json::Value| -> GoalState {
            serde_json::from_value(serde_json::json!({
                "current": {
                    "id": "goal-1",
                    "objective": "ship the release",
                    "lifecycle": lifecycle,
                    "pauseReason": pause_reason,
                    "createdAt": "2026-01-01T00:00:00Z",
                    "updatedAt": "2026-01-01T00:00:00Z",
                    "usage": { "tokensUsed": 0, "activeTimeSeconds": 0 }
                },
                "revision": 1
            }))
            .expect("goal state json")
        };
        fn labels(items: &[PanelItem]) -> Vec<&str> {
            items.iter().map(|item| item.label.as_str()).collect()
        }
        fn resume(items: &[PanelItem]) -> Option<&PanelItem> {
            items
                .iter()
                .find(|item| matches!(item.value, PanelValue::GoalResume))
        }

        // No goal: create flow, no lifecycle actions.
        let items = goal_panel_items(&GoalState::default());
        assert_eq!(labels(&items), vec!["Create goal", "Show details"]);
        assert!(resume(&items).is_none());

        // Active goal: pause, no resume.
        let items = goal_panel_items(&state("active", serde_json::Value::Null));
        assert!(labels(&items).contains(&"Pause"), "{:?}", labels(&items));
        assert!(resume(&items).is_none());

        // Manual pause stays recoverable with the plain resume action.
        let items = goal_panel_items(&state("paused", serde_json::json!("manual")));
        let resume_item = resume(&items).expect("manual pause offers Resume");
        assert_eq!(
            resume_item.description,
            "Continue work toward this objective"
        );
        assert!(!labels(&items).contains(&"Pause"), "{:?}", labels(&items));

        // Resume-safety pause is recoverable too; the description says why.
        let items = goal_panel_items(&state("paused", serde_json::json!("resume_safety")));
        let resume_item = resume(&items).expect("resume-safety pause offers Resume");
        assert_eq!(
            resume_item.description,
            "Session resumed; continue work toward this objective"
        );

        // Budget-exhausted pause cannot be resumed: no Resume action at all.
        let items = goal_panel_items(&state("paused", serde_json::json!("budget_exhausted")));
        assert!(!labels(&items).contains(&"Resume"), "{:?}", labels(&items));
        assert!(
            labels(&items).contains(&"Complete") && labels(&items).contains(&"Drop"),
            "terminal actions remain available: {:?}",
            labels(&items)
        );

        // Terminal lifecycles offer no pause/resume actions.
        for lifecycle in ["completed", "dropped"] {
            let items = goal_panel_items(&state(lifecycle, serde_json::Value::Null));
            assert_eq!(
                labels(&items),
                vec!["Show details"],
                "{lifecycle}: {:?}",
                labels(&items)
            );
        }

        // The Show details row explains the pause reason in the one-liner.
        let items = goal_panel_items(&state("paused", serde_json::json!("resume_safety")));
        let show = items
            .iter()
            .find(|item| item.label == "Show details")
            .expect("Show details row");
        assert!(
            show.description
                .contains("session resumed; run /goal resume"),
            "{}",
            show.description
        );
    }

    #[tokio::test]
    async fn goal_dispatch_starts_work_and_preserves_editor_on_usage_error() {
        let cwd = tempfile::tempdir().expect("cwd");
        let stream_fn: pi_agent::StreamFn =
            std::sync::Arc::new(move |model, _context, _options| {
                Box::pin(async move {
                    let stream = pi_ai::new_assistant_message_event_stream();
                    let producer = stream.clone();
                    tokio::spawn(async move {
                        let mut message = pi_ai::AssistantMessage::pending(&model);
                        message.content.push(ContentBlock::text("done"));
                        message.stop_reason = pi_ai::StopReason::Stop;
                        producer.end(Some(message)).await;
                    });
                    stream
                })
            });
        let application =
            test_application_with(cwd.path(), Some(stream_fn), None, Vec::new()).await;
        let session = application.session();
        let mut state = todo_test_state(Vec::new());
        state
            .editor
            .set_text("/goal create --tokens nope keep this");
        assert!(
            !dispatch_goal_command(
                &application,
                &mut state,
                Some("create --tokens nope keep this"),
            )
            .await
        );
        assert_eq!(state.editor.text(), "/goal create --tokens nope keep this");
        assert!(
            state
                .composer_error
                .as_deref()
                .is_some_and(|error| error.contains("positive integer")),
            "goal usage errors must remain in the composer toast"
        );
        assert!(
            state.transcript.is_empty(),
            "goal usage errors must never enter the transcript"
        );
        assert!(session.history().is_empty());

        assert!(
            dispatch_goal_command(
                &application,
                &mut state,
                Some("create --tokens 20 ship cleanly"),
            )
            .await
        );
        assert!(
            state.composer_error.is_none(),
            "accepted goal work clears the toast"
        );
        assert!(
            state
                .status
                .starts_with("Goal work started · active · 0/20 tokens · ship cleanly"),
            "{}",
            state.status
        );
        assert_eq!(state.goal_state, application.goal_state());
        let details = state
            .transcript
            .iter()
            .rev()
            .find(|entry| {
                !entry.is_error && content_text(&entry.content).contains("Objective: ship cleanly")
            })
            .map(|entry| content_text(&entry.content))
            .expect("create must push OMP-style goal details");
        assert!(details.contains("Status: active"), "{details}");
        assert!(details.contains("Tokens: 0 / 20"), "{details}");
        assert!(details.contains("Time spent:"), "{details}");

        assert!(
            dispatch_goal_command(&application, &mut state, Some("inspect")).await,
            "inspect must be read-only Show, not create"
        );
        assert_eq!(state.goal_state, application.goal_state());
        assert!(
            application.goal_state().current.is_some(),
            "inspect must not drop the active goal"
        );
        let inspect = state
            .transcript
            .last()
            .map(|entry| content_text(&entry.content))
            .expect("inspect details");
        assert!(inspect.contains("Objective: ship cleanly"), "{inspect}");

        assert!(
            dispatch_goal_command(
                &application,
                &mut state,
                Some("pin keep the release checklist in scope"),
            )
            .await
        );
        let before_pins = state.transcript.len();
        assert!(dispatch_goal_command(&application, &mut state, Some("pins")).await);
        let pins = state
            .transcript
            .get(before_pins..)
            .expect("pins rows")
            .iter()
            .map(|entry| content_text(&entry.content))
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            pins.contains("1. keep the release checklist in scope"),
            "pins listing must enter the transcript, not only status: {pins}"
        );
        assert_eq!(
            state.status,
            crate::goal_commands::format_goal_pins(&application.goal_state())
        );

        application.wait_for_idle().await;
        assert!(
            session
                .history()
                .iter()
                .any(|message| matches!(message, Message::Assistant(_))),
            "goal create must start the agent"
        );
        application.cleanup().await;
    }

    #[tokio::test]
    async fn goal_dispatch_reports_queued_work_while_busy() {
        let cwd = tempfile::tempdir().expect("cwd");
        let started = std::sync::Arc::new(tokio::sync::Notify::new());
        let release = CancellationToken::new();
        let stream_started = started.clone();
        let stream_release = release.clone();
        let stream_fn: pi_agent::StreamFn =
            std::sync::Arc::new(move |model, _context, _options| {
                let started = stream_started.clone();
                let release = stream_release.clone();
                Box::pin(async move {
                    let stream = pi_ai::new_assistant_message_event_stream();
                    let producer = stream.clone();
                    tokio::spawn(async move {
                        started.notify_waiters();
                        release.cancelled().await;
                        let mut message = pi_ai::AssistantMessage::pending(&model);
                        message.content.push(ContentBlock::text("done"));
                        message.stop_reason = pi_ai::StopReason::Stop;
                        producer.end(Some(message)).await;
                    });
                    stream
                })
            });
        let application =
            test_application_with(cwd.path(), Some(stream_fn), None, Vec::new()).await;
        application
            .prompt("busy".to_owned(), Vec::new(), None)
            .await
            .expect("busy prompt");
        tokio::time::timeout(std::time::Duration::from_secs(2), started.notified())
            .await
            .expect("busy turn started");

        let mut state = todo_test_state(Vec::new());
        assert!(dispatch_goal_command(&application, &mut state, Some("create queued goal")).await);
        assert!(
            state
                .status
                .starts_with("Goal work queued · active · 0 tokens used · queued goal"),
            "{}",
            state.status
        );

        application.goal_pause().expect("cancel queued work");
        release.cancel();
        application.wait_for_idle().await;
        application.cleanup().await;
    }

