    fn recursive_jsonl_entries(root: &Path) -> BTreeSet<PathBuf> {
        fn visit(root: &Path, directory: &Path, entries: &mut BTreeSet<PathBuf>) {
            let Ok(children) = std::fs::read_dir(directory) else {
                return;
            };
            for child in children {
                let child = child.expect("session directory entry").path();
                if child.is_dir() {
                    visit(root, &child, entries);
                } else if child
                    .extension()
                    .is_some_and(|extension| extension == "jsonl")
                {
                    entries.insert(
                        child
                            .strip_prefix(root)
                            .expect("JSONL entry below root")
                            .to_path_buf(),
                    );
                }
            }
        }

        let mut entries = BTreeSet::new();
        visit(root, root, &mut entries);
        entries
    }

    /// Regression: `/import` drives the real slash-command dispatch against a
    /// missing custom session root. The directory-only import API must create
    /// that root, emit exactly one JSONL child there, resume it, and leave both
    /// cwd-derived default roots byte-for-byte untouched at the entry level.
    #[tokio::test]
    async fn import_slash_command_creates_missing_root_and_writes_nested_jsonl() {
        let process_cwd = tempfile::tempdir().expect("process cwd");
        let recorded_cwd = tempfile::tempdir().expect("recorded cwd");
        let custom_root = tempfile::tempdir().expect("custom root parent");
        let nested = custom_root.path().join("nested-session-dir");
        assert!(!nested.exists(), "nested session root must start absent");

        let default_from_recorded = pi_coding::default_session_dir(recorded_cwd.path());
        let default_from_process = pi_coding::default_session_dir(process_cwd.path());
        for (root, name) in [
            (&default_from_recorded, "recorded-cwd-rogue.jsonl"),
            (&default_from_process, "process-cwd-rogue.jsonl"),
        ] {
            let planted = root.join("preexisting").join(name);
            std::fs::create_dir_all(planted.parent().expect("rogue parent"))
                .expect("create default-root fixture");
            std::fs::write(&planted, b"preexisting fixture\n").expect("plant rogue JSONL");
        }
        let recorded_before = recursive_jsonl_entries(&default_from_recorded);
        let process_before = recursive_jsonl_entries(&default_from_process);

        let fixture_dir = tempfile::tempdir().expect("fixture source dir");
        let fixture_path = fixture_dir.path().join("import-containment.jsonl");
        let recorded_cwd_str = recorded_cwd
            .path()
            .display()
            .to_string()
            .replace('\\', "\\\\");
        std::fs::write(
            &fixture_path,
            format!(
                "{{\"type\":\"session\",\"version\":3,\"id\":\"import-containment\",\"timestamp\":\"2026-01-01T00:00:00.000Z\",\"cwd\":\"{recorded_cwd_str}\"}}\n\
                 {{\"type\":\"message\",\"id\":\"user\",\"parentId\":null,\"timestamp\":\"2026-01-01T00:00:01.000Z\",\"message\":{{\"role\":\"user\",\"content\":\"fixture prompt\"}}}}\n"
            ),
        )
        .expect("session fixture");

        let fixture = test_application(recorded_cwd.path()).await;
        fixture
            .application
            .session()
            .start_new_recording()
            .expect("record import test session");
        fixture
            .application
            .session()
            .set_session_dir(nested.clone());
        let model_before = fixture.application.session().model().expect("model before import");
        let mut state = todo_test_state(Vec::new());
        dispatch_import_command(&fixture.application, &mut state, fixture_path.to_str())
            .await
            .expect("import dispatch");
        let model_after = fixture.application.session().model().expect("model after import");
        assert_eq!(model_after.provider, model_before.provider);
        assert_eq!(model_after.id, model_before.id);

        assert!(
            nested.is_dir(),
            "nested root must be a directory after import"
        );
        let emitted = recursive_jsonl_entries(&nested);
        assert_eq!(emitted.len(), 1, "exactly one imported JSONL: {emitted:?}");
        let emitted_path = nested.join(emitted.first().expect("imported JSONL"));
        assert_eq!(
            emitted_path.parent(),
            Some(nested.as_path()),
            "emitted JSONL must live directly under the active session_dir",
        );
        assert!(
            state.status.starts_with("Imported and resumed"),
            "dispatch status reflects a successful import: {}",
            state.status,
        );
        let user_entry = state
            .transcript
            .iter()
            .find(|entry| entry.kind == TranscriptKind::User)
            .expect("imported user message hydrated into transcript");
        assert!(
            content_text(&user_entry.content).contains("fixture prompt"),
            "transcript must carry the imported fixture prompt: {:?}",
            user_entry.content,
        );
        assert_eq!(
            recursive_jsonl_entries(&default_from_recorded),
            recorded_before,
            "recorded-cwd default root changed during scoped import",
        );
        assert_eq!(
            recursive_jsonl_entries(&default_from_process),
            process_before,
            "process-cwd default root changed during scoped import",
        );
        assert!(
            !emitted_path.starts_with(&default_from_recorded)
                && !emitted_path.starts_with(&default_from_process),
            "the weaker emitted-path assertion also holds despite planted rogue artifacts",
        );
        fixture.application.cleanup().await;
    }

