    #[test]
    fn move_target_parser_accepts_absolute_directory_with_spaces() {
        let cwd = tempfile::tempdir().expect("cwd");
        let target = cwd.path().join("target dir with spaces");
        std::fs::create_dir(&target).expect("target directory");
        assert_eq!(
            parse_session_move_target(Some(target.to_str().expect("utf8 target"))),
            Ok(target),
            "the whole rest-of-line is the target: unquoted spaces survive"
        );
    }

    #[test]
    fn move_target_parser_rejects_empty_relative_and_missing_targets() {
        let cwd = tempfile::tempdir().expect("cwd");

        for empty in [None, Some(""), Some("   ")] {
            let error = parse_session_move_target(empty).expect_err("empty target");
            assert_eq!(error, "Usage: /move <absolute-existing-directory>");
        }

        let error = parse_session_move_target(Some("relative/checkout"))
            .expect_err("relative target");
        assert!(
            error.contains("absolute"),
            "relative input must be rejected without resolution: {error}"
        );

        let missing = cwd.path().join("missing-dir");
        let error =
            parse_session_move_target(Some(missing.to_str().expect("utf8 missing")))
                .expect_err("missing target");
        assert!(
            error.contains("existing directory"),
            "nonexistent input must be rejected: {error}"
        );

        let file = cwd.path().join("file.txt");
        std::fs::write(&file, "x").expect("file");
        let error =
            parse_session_move_target(Some(file.to_str().expect("utf8 file")))
                .expect_err("file target");
        assert!(
            error.contains("existing directory"),
            "a plain file is not a directory target: {error}"
        );
    }

    /// `/move` against a valid existing directory but a sabotaged destination
    /// (different-byte collision with the same session file name) must leave
    /// the old runtime fully active: same recorder path, same cwd, source
    /// file still present, and a bounded path-free failure status.
    #[tokio::test]
    async fn move_slash_command_failure_leaves_old_runtime_active() {
        let cwd = tempfile::tempdir().expect("cwd");
        let target = tempfile::tempdir().expect("target");
        let fixture = test_application(cwd.path()).await;
        fixture
            .application
            .session()
            .start_new_recording()
            .expect("record move failure test session");
        let (session_id, recorder_path) = fixture
            .application
            .session()
            .recorder_info()
            .expect("recorded session");
        let dest_dir = pi_coding::default_session_dir(target.path());
        std::fs::create_dir_all(&dest_dir).expect("destination session dir");
        let collision = dest_dir.join(
            recorder_path
                .file_name()
                .expect("recorder file name"),
        );
        std::fs::write(&collision, b"colliding different bytes\n").expect("collision fixture");

        let mut state = todo_test_state(Vec::new());
        state.cwd_path = cwd.path().to_path_buf();
        dispatch_session_move_command(
            &fixture.application,
            &mut state,
            Some(target.path().to_str().expect("utf8 target")),
        )
        .await;

        assert_eq!(
            state.composer_error.as_deref(),
            Some("Session move failed; the active session is unchanged"),
            "failure status is bounded: {:?}",
            state.composer_error,
        );
        assert!(
            !state.status.contains(target.path().to_str().expect("utf8 target")),
            "failure status must not echo local paths: {}",
            state.status,
        );
        assert_eq!(
            fixture.application.session().recorder_info().expect("recorder"),
            (session_id, recorder_path.clone()),
            "old runtime stays active after a failed move"
        );
        assert_eq!(
            fixture.application.session().cwd(),
            cwd.path(),
            "cwd unchanged after a failed move"
        );
        assert!(
            recorder_path.is_file(),
            "source session file survives the failed move"
        );
        assert!(state.pending_session_move.is_none());
        fixture.application.cleanup().await;
    }

    /// Idle success contract: `/move` relocates the saved session, switches
    /// the application through the cross-directory resume path, names the
    /// moved session in the status without echoing any local path, and leaves
    /// no queued cutover behind.
    #[tokio::test]
    async fn move_slash_command_relocates_and_switches_when_idle() {
        let cwd = tempfile::tempdir().expect("cwd");
        let target = tempfile::tempdir().expect("target");
        let fixture = test_application(cwd.path()).await;
        attach_move_slash_runtime_factory(&fixture.application);
        fixture
            .application
            .session()
            .start_new_recording()
            .expect("record move success test session");
        let (session_id, recorder_path) = fixture
            .application
            .session()
            .recorder_info()
            .expect("recorded session");

        let mut state = todo_test_state(Vec::new());
        state.cwd_path = cwd.path().to_path_buf();
        dispatch_session_move_command(
            &fixture.application,
            &mut state,
            Some(target.path().to_str().expect("utf8 target")),
        )
        .await;

        assert_eq!(
            state.status,
            format!("Moved session {session_id}"),
            "success status names the moved session: {}",
            state.status,
        );
        assert!(
            !state.status.contains(cwd.path().to_str().expect("utf8 cwd"))
                && !state.status.contains(target.path().to_str().expect("utf8 target")),
            "success status must not echo absolute paths: {}",
            state.status,
        );
        assert!(state.pending_session_move.is_none());
        assert!(
            !recorder_path.exists(),
            "the old authority is removed on success"
        );
        let dest_dir = pi_coding::default_session_dir(target.path());
        let moved = std::fs::read_dir(&dest_dir)
            .expect("destination session dir")
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .find(|path| path.extension().is_some_and(|extension| extension == "jsonl"))
            .expect("moved session jsonl under the target checkout");
        assert_eq!(
            moved.file_name(),
            recorder_path.file_name(),
            "the file name is preserved exactly"
        );
        assert_eq!(
            fixture.application.session().cwd(),
            target.path(),
            "the application cut over to the new checkout"
        );
        fixture.application.cleanup().await;
    }

    /// Streaming contract: `/move` during an active turn queues the cutover,
    /// touches nothing, and runs exactly once when the agent settles — the
    /// same settle point the event loop uses after `AgentSettled`.
    #[tokio::test]
    async fn move_slash_command_waits_for_idle_then_cuts_over() {
        let cwd = tempfile::tempdir().expect("cwd");
        let target = tempfile::tempdir().expect("target");
        let fixture = test_application(cwd.path()).await;
        attach_move_slash_runtime_factory(&fixture.application);
        fixture
            .application
            .session()
            .start_new_recording()
            .expect("record deferred move test session");
        let (_, recorder_path) = fixture
            .application
            .session()
            .recorder_info()
            .expect("recorded session");

        let mut state = todo_test_state(Vec::new());
        state.cwd_path = cwd.path().to_path_buf();
        state.is_streaming = true;
        dispatch_session_move_command(
            &fixture.application,
            &mut state,
            Some(target.path().to_str().expect("utf8 target")),
        )
        .await;

        assert_eq!(
            state.pending_session_move,
            Some(target.path().to_path_buf()),
            "the cutover is queued while streaming"
        );
        assert_eq!(
            state.status,
            "Session move queued; it runs when the current turn settles",
        );
        assert_eq!(
            fixture.application.session().recorder_info().expect("recorder").1,
            recorder_path,
            "streaming dispatch must not touch the session"
        );
        assert!(recorder_path.is_file(), "source file survives the queue");

        state.apply(ApplicationEvent::AgentSettled);
        assert!(!state.is_streaming, "settled turn is idle");
        maybe_run_pending_session_move(&fixture.application, &mut state).await;

        assert!(state.pending_session_move.is_none(), "queue is consumed");
        assert!(
            state.status.starts_with("Moved session "),
            "settled cutover reports the move: {}",
            state.status,
        );
        assert_eq!(
            fixture.application.session().cwd(),
            target.path(),
            "the queued move cut over to the new checkout"
        );
        fixture.application.cleanup().await;
    }
