    #[test]
    fn session_selector_hints_name_exact_direct_keys() {
        let mut selector = SavedSessionSelector::new(saved_session_rows(1), None);
        assert_eq!(
            session_selector_key_hints(&selector),
            "↑/↓ · Enter resume · f fork · c clone · r rename · d archive · type filter · Esc/q close"
        );
        let lines = saved_session_selector_lines(&selector, crate::theme::DARK, 8);
        let rendered = lines.iter().map(rendered_line_text).collect::<Vec<_>>();
        assert!(
            rendered.iter().any(|line| line.contains("f fork")
                && line.contains("c clone")
                && line.contains("r rename")
                && line.contains("d archive")),
            "{rendered:?}"
        );
        assert_eq!(
            selector.handle_char('d'),
            crate::saved_session_selector::SessionSelectorInput::Status(
                crate::saved_session_selector::SessionManagementResult::Started
            )
        );
        assert_eq!(
            session_selector_key_hints(&selector),
            "d confirm · Esc cancel"
        );
        let confirm_lines = saved_session_selector_lines(&selector, crate::theme::DARK, 8);
        let confirm_rendered = confirm_lines
            .iter()
            .map(rendered_line_text)
            .collect::<Vec<_>>();
        assert!(
            confirm_rendered
                .iter()
                .any(|line| line.contains("Archive session? d confirm · Esc cancel")),
            "{confirm_rendered:?}"
        );
        assert!(
            !confirm_rendered
                .iter()
                .any(|line| line.to_ascii_lowercase().contains("deleted")),
            "{confirm_rendered:?}"
        );
        assert_eq!(selector.confirm(), SessionSelectorRequest::None);
        assert!(matches!(
            selector.mode(),
            SessionSelectorMode::ConfirmDelete { .. }
        ));
        selector.cancel_mode();
        assert_eq!(selector.mode(), &SessionSelectorMode::List);
    }

