    /// Test fixture: a live workflow projection whose child runtime has
    /// spawned the given workers (name + optional current task summary).
    fn workflow_panel_with_workers(
        name: &str,
        status: pi_coding::WorkflowStatus,
        workers: &[(&str, Option<&str>)],
    ) -> WorkflowPanelSnapshot {
        let mut panel = WorkflowPanelSnapshot::from(&workflow_snapshot(1, status));
        panel.id = name.to_owned();
        panel.name = name.to_owned();
        panel.subagents = workers
            .iter()
            .map(
                |(name, task)| crate::workflow_panel::WorkflowActorSnapshot {
                    name: (*name).to_owned(),
                    role: "task".to_owned(),
                    status: "running".to_owned(),
                    task: task.map(|task| task.to_owned()),
                    task_id: None,
                    activity: Vec::new(),
                },
            )
            .collect();
        panel
    }

    #[tokio::test]
    async fn workflow_panel_command_handoff_preserves_filter_and_routes_commands() {
        // The reported case: `/workflow remove <id>` typed while the panel
        // owns the page must reach the ordinary composer/command path, never
        // disappear. A partial `workflow` prefix stays an intentional filter;
        // once the first token is an executable command the Space/Enter
        // boundary hands the whole draft over.
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;
        let mut state = todo_test_state(Vec::new());
        state.commands = vec![InteractiveCommand {
            name: "workflow".to_owned(),
            description: "Manage workflows".to_owned(),
            source: CommandSource::Builtin,
        }];
        state.workflow_panel = Some(WorkflowPanel::new(Vec::new()));
        let type_filter = |state: &mut TuiState, text: &str| {
            let panel = state.workflow_panel.as_mut().expect("workflow panel");
            panel.handle_key(KeyEvent::new(KeyCode::Char('/'), KeyModifiers::NONE));
            for character in text.chars() {
                panel.handle_key(KeyEvent::new(
                    KeyCode::Char(character),
                    KeyModifiers::NONE,
                ));
            }
        };

        // `work` is a filter prefix, not an executable command name.
        type_filter(&mut state, "work");
        assert!(!handoff_workflow_panel_command(
            &mut state,
            KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE)
        ));
        assert_eq!(
            state.workflow_panel.as_ref().expect("workflow panel").filter(),
            "work"
        );
        assert!(state.editor.is_empty());

        // The reported command: first token `workflow` plus an argument is
        // command intent. Space hands the exact draft to the composer.
        type_filter(&mut state, "flow remove wf-1");
        assert_eq!(
            handle_workflow_panel_key(
                &application,
                &mut state,
                KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE),
            )
            .await
            .expect("workflow command handoff"),
            Some(false)
        );
        assert!(state.workflow_panel.is_none());
        assert_eq!(state.editor.text(), "/workflow remove wf-1");
        assert!(
            state.status.contains("Moved /workflow to the composer"),
            "{}",
            state.status
        );

        // Enter hands the same draft without appending the argument space.
        state.workflow_panel = Some(WorkflowPanel::new(Vec::new()));
        state.editor.clear();
        type_filter(&mut state, "workflow remove wf-2");
        assert_eq!(
            handle_workflow_panel_key(
                &application,
                &mut state,
                KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            )
            .await
            .expect("workflow command handoff"),
            Some(false)
        );
        assert!(state.workflow_panel.is_none());
        assert_eq!(state.editor.text(), "/workflow remove wf-2");

        // A nonempty composer draft is never clobbered: the handoff keeps the
        // panel open and parks a bounded warning instead.
        state.workflow_panel = Some(WorkflowPanel::new(Vec::new()));
        type_filter(&mut state, "workflow remove wf-3");
        state.editor.set_text("user draft");
        assert!(
            handle_workflow_panel_key(
                &application,
                &mut state,
                KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE),
            )
            .await
            .expect("workflow command rejection")
            .is_some()
        );
        assert!(state.workflow_panel.is_some());
        assert_eq!(state.editor.text(), "user draft");
        assert!(
            state
                .composer_error
                .as_deref()
                .is_some_and(|text| text.contains("Composer draft kept")),
            "{:?}",
            state.composer_error
        );

        application.cleanup().await;
    }

    #[tokio::test]
    async fn stale_workflow_events_do_not_regress_tui_projection() {
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;
        let mut state = todo_test_state(Vec::new());
        state
            .workflow_snapshots
            .push(WorkflowPanelSnapshot::from(&workflow_snapshot(
                2,
                pi_coding::WorkflowStatus::Running,
            )));

        state.apply_workflow_event(
            &application,
            pi_coding::WorkflowEvent::StatusChanged {
                workflow_id: pi_coding::WorkflowId::new("workflow-generation"),
                generation: 1,
                status: pi_coding::WorkflowStatus::Failed,
            },
        );
        assert_eq!(
            state.workflow_snapshots[0].status,
            pi_coding::WorkflowStatus::Running
        );

        state.apply_workflow_event(
            &application,
            pi_coding::WorkflowEvent::Removed {
                workflow_id: pi_coding::WorkflowId::new("workflow-generation"),
                generation: 1,
            },
        );
        assert_eq!(state.workflow_snapshots.len(), 1);

        state.apply_workflow_event(
            &application,
            pi_coding::WorkflowEvent::StatusChanged {
                workflow_id: pi_coding::WorkflowId::new("workflow-generation"),
                generation: 2,
                status: pi_coding::WorkflowStatus::Paused,
            },
        );
        assert_eq!(
            state.workflow_snapshots[0].status,
            pi_coding::WorkflowStatus::Paused
        );
        application.cleanup().await;
    }

    #[tokio::test]
    async fn closing_workflow_panel_is_silent_never_errors_the_running_status() {
        // User-reported: closing the workflow panel surfaced an
        // "Error: Workflow <name> · running" toast. A live status change while
        // the panel owns the page is parked in the dedicated deferred slot
        // (`set_deferred_workflow_status`); Esc/q close discards ONLY that
        // deferred line instead of leaving it to render as an error above the
        // composer. Unrelated deferred notices survive the close (covered by
        // `closing_workflow_panel_keeps_non_workflow_deferred_notices`).
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;

        let mut state = todo_test_state(Vec::new());
        let mut running =
            WorkflowPanelSnapshot::from(&workflow_snapshot(1, pi_coding::WorkflowStatus::Running));
        running.id = "wf-zig".to_owned();
        running.name = "zig-agent".to_owned();
        state.workflow_snapshots.push(running.clone());
        state.workflow_panel = Some(WorkflowPanel::new(vec![running.clone()]));

        for close_key in [KeyCode::Esc, KeyCode::Char('q')] {
            state.apply_workflow_event(
                &application,
                pi_coding::WorkflowEvent::StatusChanged {
                    workflow_id: pi_coding::WorkflowId::new("wf-zig"),
                    generation: 1,
                    status: pi_coding::WorkflowStatus::Running,
                },
            );
            assert_eq!(
                state.deferred_workflow_status.as_deref(),
                Some("Workflow zig-agent · running"),
                "the running workflow's status must be deferred while the panel owns the page"
            );
            assert!(
                state.composer_error.is_none(),
                "the workflow line must not occupy the composer-error slot"
            );
            assert!(
                !composer_error_toast_lines(&state, 120, crate::theme::DARK).is_empty(),
                "the deferred workflow line must still render as a toast while the panel is open"
            );

            let closed = handle_workflow_panel_key(
                &application,
                &mut state,
                KeyEvent::new(close_key, KeyModifiers::NONE),
            )
            .await
            .expect("workflow panel close");
            assert_eq!(closed, Some(false));
            assert!(state.workflow_panel.is_none(), "close must drop the panel");
            assert_eq!(state.status, "Ready", "close resets to the neutral status");
            assert!(
                state.deferred_workflow_status.is_none(),
                "closing must discard ONLY the deferred workflow line"
            );
            assert!(
                state.composer_error.is_none(),
                "no unrelated composer notice may appear on close"
            );
            assert!(
                composer_error_toast_lines(&state, 120, crate::theme::DARK).is_empty(),
                "no error toast may render after closing"
            );

            state.workflow_panel = Some(WorkflowPanel::new(vec![running.clone()]));
        }
        application.cleanup().await;
    }

    #[tokio::test]
    async fn closing_workflow_panel_keeps_non_workflow_deferred_notices() {
        // A non-workflow deferred notice parked while the workflow panel owns
        // the page must SURVIVE the close: closing discards only the deferred
        // workflow status line, never unrelated composer notices (failed /run
        // results, paste-consume notices, WorkflowCommandFinished errors,
        // push_warning warnings).
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;

        let mut state = todo_test_state(Vec::new());
        let mut running =
            WorkflowPanelSnapshot::from(&workflow_snapshot(1, pi_coding::WorkflowStatus::Running));
        running.id = "wf-zig".to_owned();
        running.name = "zig-agent".to_owned();
        state.workflow_snapshots.push(running.clone());
        state.workflow_panel = Some(WorkflowPanel::new(vec![running.clone()]));

        state.push_status("/run smoke-test failed: boom".to_owned(), true);
        assert_eq!(
            state.composer_error.as_deref(),
            Some("/run smoke-test failed: boom"),
            "the failed /run result must be a deferred composer notice"
        );
        state.apply_workflow_event(
            &application,
            pi_coding::WorkflowEvent::StatusChanged {
                workflow_id: pi_coding::WorkflowId::new("wf-zig"),
                generation: 1,
                status: pi_coding::WorkflowStatus::Running,
            },
        );
        assert_eq!(
            state.deferred_workflow_status.as_deref(),
            Some("Workflow zig-agent · running")
        );

        let toast = composer_error_toast_lines(&state, 120, crate::theme::DARK)
            .into_iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            toast.contains("/run smoke-test failed: boom"),
            "the /run failure must be the visible toast: {toast}"
        );

        let closed = handle_workflow_panel_key(
            &application,
            &mut state,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
        )
        .await
        .expect("workflow panel close");
        assert_eq!(closed, Some(false));
        assert!(state.workflow_panel.is_none());
        assert!(state.deferred_workflow_status.is_none());
        assert_eq!(
            state.composer_error.as_deref(),
            Some("/run smoke-test failed: boom"),
            "the non-workflow deferred notice must survive the close"
        );
        let after = composer_error_toast_lines(&state, 120, crate::theme::DARK)
            .into_iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            after.contains("/run smoke-test failed: boom"),
            "the surviving notice must still render after close: {after}"
        );
        assert!(
            !after.contains("Workflow zig-agent"),
            "the deferred workflow line must not render after close: {after}"
        );

        application.cleanup().await;
    }

    #[tokio::test]
    async fn workflow_create_dispatch_returns_before_delayed_backend_completes() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicUsize, Ordering};
        use std::time::Duration;

        let (background_tx, mut background_rx) = mpsc::unbounded_channel();
        let mut state = todo_test_state(Vec::new());
        state.background_tx = background_tx;
        let command =
            crate::workflow_commands::parse_interactive_workflow_command(Some("create ship it"))
                .expect("parse /workflow create");
        assert!(matches!(
            command,
            crate::workflow_commands::InteractiveWorkflowCommand::Create { .. }
        ));

        let create_gate = Arc::new(tokio::sync::Notify::new());
        let create_entered = Arc::new(tokio::sync::Notify::new());
        let created = Arc::new(AtomicUsize::new(0));
        let future_gate = create_gate.clone();
        let future_entered = create_entered.clone();
        let future_created = created.clone();

        let routed = state.dispatch_non_page_workflow_command(command, move |command| async move {
            assert!(matches!(
                command,
                crate::workflow_commands::InteractiveWorkflowCommand::Create { .. }
            ));
            future_entered.notify_one();
            future_gate.notified().await;
            future_created.fetch_add(1, Ordering::SeqCst);
            Ok(crate::workflow_commands::WorkflowCommandEffect::Message(
                "created ship it".to_owned(),
            ))
        });

        assert!(routed, "parsed create command must use non-page routing");
        assert!(
            state.status.contains("Creating workflow"),
            "admission status must be visible: {}",
            state.status,
        );
        assert!(state.composer_error.is_none());

        tokio::time::timeout(Duration::from_secs(30), create_entered.notified())
            .await
            .expect("workflow executor entered");
        assert_eq!(
            created.load(Ordering::SeqCst),
            0,
            "routing must return before the gated backend completes",
        );
        assert!(
            background_rx.try_recv().is_err(),
            "no completion event before the gate releases",
        );

        create_gate.notify_one();
        let finished = tokio::time::timeout(Duration::from_secs(30), background_rx.recv())
            .await
            .expect("workflow command finished event")
            .expect("background channel open");
        let BackgroundEvent::WorkflowCommandFinished { label, result } = finished else {
            panic!("expected WorkflowCommandFinished");
        };
        assert_eq!(label, "Creating workflow");
        assert_eq!(
            created.load(Ordering::SeqCst),
            1,
            "workflow future completed exactly once",
        );
        tokio::task::yield_now().await;
        assert!(
            background_rx.try_recv().is_err(),
            "routing must emit exactly one WorkflowCommandFinished event",
        );
        let message = match result {
            Ok(crate::workflow_commands::WorkflowCommandEffect::Message(message)) => message,
            other => panic!("expected message effect, got {other:?}"),
        };
        assert!(
            message.contains("ship it"),
            "final status names the workflow: {message}"
        );

        state.status = String::new();
        let mut first =
            WorkflowPanelSnapshot::from(&workflow_snapshot(1, pi_coding::WorkflowStatus::Queued));
        first.id = "wf-alpha".to_owned();
        first.name = "alpha-flow".to_owned();
        let mut second =
            WorkflowPanelSnapshot::from(&workflow_snapshot(1, pi_coding::WorkflowStatus::Queued));
        second.id = "wf-beta".to_owned();
        second.name = "beta-flow".to_owned();
        state.workflow_snapshots = vec![first, second];
        state.apply_background(BackgroundEvent::WorkflowCommandFinished {
            label,
            result: Ok(crate::workflow_commands::WorkflowCommandEffect::Message(
                message,
            )),
        });
        assert!(
            state.status.contains("ship it"),
            "apply_background must set the final status: {}",
            state.status,
        );
        let compact = state
            .transcript
            .iter()
            .map(|entry| content_text(&entry.content))
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            compact.contains("Workflows · 2 active · 2 total"),
            "create completion must paint the compact conversation header: {compact}"
        );

        state.status = "Creating workflow…".to_owned();
        state.apply_background(BackgroundEvent::WorkflowCommandFinished {
            label: "Creating workflow",
            result: Err("backend rejected request".to_owned()),
        });
        assert_eq!(state.status, "Ready");
        assert_eq!(
            state.composer_error.as_deref(),
            Some("Workflow command failed: backend rejected request"),
        );
    }

    #[tokio::test]
    async fn compact_dispatch_runs_in_background_and_reports_token_counts() {
        let cwd = tempfile::tempdir().expect("cwd");
        let stream_fn: pi_agent::StreamFn = std::sync::Arc::new(|_model, _context, _options| {
            Box::pin(async move {
                let stream = pi_ai::new_assistant_message_event_stream();
                let producer = stream.clone();
                tokio::spawn(async move {
                    let mut message = pi_ai::AssistantMessage::pending(&Model::default());
                    message
                        .content
                        .push(ContentBlock::text("checkpoint summary"));
                    message.stop_reason = pi_ai::StopReason::Stop;
                    producer.end(Some(message)).await;
                });
                stream
            })
        });
        let compaction = Some(pi_coding::CompactionSettings {
            enabled: true,
            reserve_tokens: 10,
            keep_recent_tokens: 4,
            snap_keep_turns: 10,
        });
        let (session, faux) =
            test_session_with(cwd.path(), Some(stream_fn), compaction, Vec::new());
        session
            .load_history(vec![
                Message::user_text("older context ".repeat(60), 1),
                Message::user_text("middle context ".repeat(60), 2),
                Message::user_text("recent context ".repeat(60), 3),
            ])
            .await
            .expect("load history");
        let application = application_for_session(session, faux).await;

        let (background_tx, mut background_rx) = mpsc::unbounded_channel();
        let mut state = todo_test_state(Vec::new());
        state.background_tx = background_tx;

        // Dispatch admits the compaction on a background task and returns
        // synchronously (mirrors the `/workflow` admission): awaiting the
        // provider summarization call inline froze the TUI event loop.
        admit_compact_background(&application, &mut state, None);
        assert_eq!(
            state.status, "Compacting context",
            "admission status must be visible immediately",
        );

        // The background completion arrives with the full result.
        let finished =
            tokio::time::timeout(std::time::Duration::from_secs(5), background_rx.recv())
                .await
                .expect("CompactionFinished must arrive promptly")
                .expect("background channel open");
        let BackgroundEvent::CompactionFinished { result } = finished else {
            panic!("expected CompactionFinished");
        };
        let result = result.expect("compaction succeeded");
        assert!(
            result.summary.contains("checkpoint summary"),
            "summary came from the provider stream: {}",
            result.summary,
        );
        assert!(result.tokens_before > 0, "context was measurable");
        assert!(
            result
                .estimated_tokens_after
                .is_some_and(|after| after < result.tokens_before),
            "compaction must shrink the context",
        );

        // The status must pair the pre-compaction count with the
        // post-compaction estimate (A → B), not echo the same value twice.
        let expected_status = format!(
            "Compacted {} → {} estimated tokens",
            result.tokens_before,
            result.estimated_tokens_after.unwrap_or_default()
        );
        state.apply_background(BackgroundEvent::CompactionFinished { result: Ok(result) });
        assert_eq!(
            state.status, expected_status,
            "final status shows the right token pair: {}",
            state.status,
        );
        assert!(!state.is_compacting, "compaction indicator cleared");

        application.cleanup().await;
    }

    #[tokio::test]
    async fn handoff_dispatch_renders_envelope_only_and_hints_prose_for_tui() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let cwd = tempfile::tempdir().expect("cwd");
        let calls = std::sync::Arc::new(AtomicUsize::new(0));
        let counting = calls.clone();
        let stream_fn: pi_agent::StreamFn =
            std::sync::Arc::new(move |_model, _context, _options| {
                counting.fetch_add(1, Ordering::SeqCst);
                Box::pin(async move {
                    let stream = pi_ai::new_assistant_message_event_stream();
                    let producer = stream.clone();
                    tokio::spawn(async move {
                        let mut message = pi_ai::AssistantMessage::pending(&Model::default());
                        message
                            .content
                            .push(ContentBlock::text("tui handoff prose"));
                        message.stop_reason = pi_ai::StopReason::Stop;
                        producer.end(Some(message)).await;
                    });
                    stream
                })
            });
        let application =
            test_application_with(cwd.path(), Some(stream_fn), None, Vec::new()).await;
        let mut state = todo_test_state(Vec::new());
        let transcript_text = |state: &TuiState| {
            state
                .transcript
                .iter()
                .map(|entry| content_text(&entry.content))
                .collect::<Vec<_>>()
                .join("\n")
        };

        // Bare `/handoff`: the envelope renders, no prose hint, and the
        // summarizer is never invoked (the TUI must not block on a provider).
        dispatch_handoff_command(&application, &mut state, None).await;
        let block = transcript_text(&state);
        assert!(
            block.contains("# Handoff"),
            "bare /handoff must render the envelope:\n{block}"
        );
        assert!(
            !block.contains("--prose"),
            "bare /handoff must not surface the prose hint:\n{block}"
        );
        assert!(
            !state.status.contains("--prose"),
            "bare /handoff must not surface the prose hint in status:\n{}",
            state.status
        );
        assert_eq!(
            calls.load(Ordering::SeqCst),
            0,
            "TUI /handoff must never invoke the summarizer"
        );

        // `/handoff --prose`: still envelope-only (never a provider call on
        // the event loop), but the REPL/CLI prose surface is hinted.
        state.transcript.clear();
        state.status = String::new();
        dispatch_handoff_command(&application, &mut state, Some("--prose")).await;
        let block = transcript_text(&state);
        assert!(
            block.contains("# Handoff"),
            "--prose in the TUI must still render the envelope:\n{block}"
        );
        assert!(
            !block.contains("--prose"),
            "the TUI must keep the prose hint out of the transcript (status-only):\n{block}"
        );
        assert!(
            state.status.contains("--prose") && state.status.contains("--mode text"),
            "the TUI must hint via status that prose runs in the REPL/CLI:\n{}",
            state.status
        );
        assert_eq!(
            calls.load(Ordering::SeqCst),
            0,
            "TUI /handoff --prose must stay envelope-only"
        );

        // Unknown flag: a typed error, nothing rendered, no provider call.
        state.transcript.clear();
        state.composer_error = None;
        dispatch_handoff_command(&application, &mut state, Some("--bogus")).await;
        assert!(
            state
                .composer_error
                .as_deref()
                .is_some_and(|error| error.contains("/handoff [--prose]")),
            "unknown /handoff flag must surface usage, got: {:?}",
            state.composer_error
        );
        assert!(
            !transcript_text(&state).contains("# Handoff"),
            "a rejected flag must not render a handoff block"
        );
        assert_eq!(
            calls.load(Ordering::SeqCst),
            0,
            "a rejected /handoff flag must never reach the provider"
        );

        application.cleanup().await;
    }

    #[tokio::test]
    async fn escape_aborts_background_compaction_instead_of_freezing() {
        let cwd = tempfile::tempdir().expect("cwd");
        // The provider stalls until the compaction's abort token fires, then
        // ends with StopReason::Aborted — the same shape as the live stalled
        // SSE repro, but bounded so the test does not wait out the 300s
        // summarization deadline.
        let stream_fn: pi_agent::StreamFn = std::sync::Arc::new(|_model, _context, options| {
            Box::pin(async move {
                let stream = pi_ai::new_assistant_message_event_stream();
                let producer = stream.clone();
                let token = options.stream.abort_signal.clone();
                tokio::spawn(async move {
                    if let Some(token) = token {
                        token.cancelled().await;
                    }
                    let mut message = pi_ai::AssistantMessage::pending(&Model::default());
                    message.stop_reason = pi_ai::StopReason::Aborted;
                    producer.end(Some(message)).await;
                });
                stream
            })
        });
        let compaction = Some(pi_coding::CompactionSettings {
            enabled: true,
            reserve_tokens: 10,
            keep_recent_tokens: 4,
            snap_keep_turns: 10,
        });
        let (session, faux) =
            test_session_with(cwd.path(), Some(stream_fn), compaction, Vec::new());
        session
            .load_history(vec![
                Message::user_text("older context ".repeat(60), 1),
                Message::user_text("middle context ".repeat(60), 2),
                Message::user_text("recent context ".repeat(60), 3),
            ])
            .await
            .expect("load history");
        let application = application_for_session(session.clone(), faux).await;

        let (background_tx, mut background_rx) = mpsc::unbounded_channel();
        let mut state = todo_test_state(Vec::new());
        state.background_tx = background_tx;
        let mut app_events = application.subscribe();

        admit_compact_background(&application, &mut state, None);

        // Wait until the compaction is actually in flight (CompactionStart
        // broadcast), then drive the Escape path: `dispatch_action` routes
        // `Action::Abort` to `application.abort()` while `is_compacting` is set.
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        loop {
            match tokio::time::timeout(std::time::Duration::from_millis(100), app_events.recv())
                .await
            {
                Ok(Ok(pi_coding::ApplicationEvent::Session(
                    pi_coding::SessionEvent::CompactionStart { .. },
                ))) => break,
                Ok(Ok(_)) | Err(_) => {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "CompactionStart never arrived",
                    );
                }
                Ok(Err(_)) => panic!("application event channel closed"),
            }
        }
        state.is_compacting = true;
        application.abort().await;
        state.status = "Aborting compaction".to_owned();

        // The stalled provider observes the abort and the compaction reports
        // cancellation promptly instead of hanging the session.
        let finished =
            tokio::time::timeout(std::time::Duration::from_secs(5), background_rx.recv())
                .await
                .expect("aborted compaction must report back promptly")
                .expect("background channel open");
        let BackgroundEvent::CompactionFinished { result } = finished else {
            panic!("expected CompactionFinished");
        };
        assert_eq!(
            result,
            Err("Compaction cancelled".to_owned()),
            "abort must cancel the compaction",
        );
        assert!(
            !session.is_compacting(),
            "compaction activity must be cleared"
        );

        state.apply_background(BackgroundEvent::CompactionFinished { result });
        assert_eq!(
            state.status, "Compaction aborted",
            "Escape during compaction must surface the abort status",
        );

        application.cleanup().await;
    }

