    fn gated_todo_runtime(
        artifact_dir: &Path,
        max_concurrency: usize,
        parent_model: Model,
    ) -> (
        pi_coding::OrchestrationRuntime,
        Arc<std::sync::Mutex<std::collections::HashMap<String, CancellationToken>>>,
    ) {
        let releases = Arc::new(std::sync::Mutex::new(std::collections::HashMap::<
            String,
            CancellationToken,
        >::new()));
        let factory_releases = releases.clone();
        let factory: pi_coding::ChildSessionFactory = Arc::new(move |request| {
            let releases = factory_releases.clone();
            Box::pin(async move {
                let child_id = request.child_id.clone();
                let release = {
                    let mut releases = releases.lock().expect("todo child gates");
                    releases
                        .entry(child_id.clone())
                        .or_insert_with(CancellationToken::new)
                        .clone()
                };
                let stream_fn: pi_agent::StreamFn = Arc::new(move |model, _context, options| {
                    let release = release.clone();
                    Box::pin(async move {
                        let stream = pi_ai::new_assistant_message_event_stream();
                        let producer = stream.clone();
                        tokio::spawn(async move {
                            let abort = options
                                .stream
                                .abort_signal
                                .expect("child stream abort signal");
                            let aborted = tokio::select! {
                                () = release.cancelled() => false,
                                () = abort.cancelled() => true,
                            };
                            let mut message = pi_ai::AssistantMessage::pending(&model);
                            if aborted {
                                message.stop_reason = pi_ai::StopReason::Aborted;
                                message.error_message = Some("cancelled by test".to_owned());
                            } else {
                                message
                                    .content
                                    .push(ContentBlock::text("completed owned Todo"));
                                message.stop_reason = pi_ai::StopReason::Stop;
                            }
                            producer.end(Some(message)).await;
                        });
                        stream
                    })
                });
                Session::new(pi_coding::SessionOptions {
                    model: request.model,
                    cwd: std::env::current_dir().expect("cwd"),
                    system_prompt: request.system_prompt,
                    thinking_level: ThinkingLevel::Off,
                    api_key: String::new(),
                    compaction: None,
                    stream_options: Default::default(),
                    tools: Some(request.orchestration_tools),
                    before_tool_call: None,
                    after_tool_call: None,
                    stream_fn: Some(stream_fn),
                    auth_resolver: None,
                    auth_manager: None,
                })
            })
        });
        let definition = pi_coding::AgentDefinition {
            name: "task".to_owned(),
            description: "execute a Todo DAG item".to_owned(),
            system_prompt: "complete the assigned Todo item".to_owned(),
            tools: Some(Vec::new()),
            autoload_skills: Vec::new(),
            model: None,
            thinking_level: Some(ThinkingLevel::Off),
            max_turns: None,
            max_tool_calls: None,
            timeout_secs: None,
            disallowed_tools: Vec::new(),
            capability_ceiling: None,
            source: pi_coding::AgentDefinitionSource::Bundled,
            path: None,
            trusted: true,
            kind: pi_coding::AgentDefinitionKind::Agent,
            personality: None,
            soft_budget: None,
            knowledge_roots: Vec::new(),
            user_proxy: false,
        };
        let mut config = pi_coding::OrchestrationConfig::new(
            pi_coding::AgentCatalog::from_agents(vec![definition]),
            artifact_dir,
        );
        config.max_concurrency = max_concurrency;
        config.idle_ttl = None;
        config.parent_model = parent_model;
        (
            pi_coding::OrchestrationRuntime::new(config, factory).expect("orchestration runtime"),
            releases,
        )
    }

    fn todo_panel_row_texts(backend: &ratatui::backend::TestBackend) -> Vec<String> {
        let buffer = backend.buffer();
        let width = usize::from(buffer.area.width);
        buffer
            .content
            .chunks(width)
            .map(|row| {
                row.iter()
                    .map(|cell| cell.symbol())
                    .collect::<String>()
                    .trim_end()
                    .to_string()
            })
            .collect()
    }

    #[tokio::test]
    async fn mounted_todo_panel_converges_rows_and_header_after_terminal_job_updates() {
        use ratatui::backend::TestBackend;
        use tokio::sync::broadcast::error::TryRecvError;

        let cwd = tempfile::tempdir().expect("cwd");
        let agent = tempfile::tempdir().expect("agent dir");
        let session_dir = tempfile::tempdir().expect("session dir");
        let resources = pi_coding::ResourceManager::new({
            let mut options = pi_coding::ResourceManagerOptions::new(cwd.path());
            options.agent_dir = agent.path().to_path_buf();
            options.project_trust_override = Some(true);
            options.disable_extensions = true;
            options.disable_skills = true;
            options.disable_prompt_templates = true;
            options.disable_themes = true;
            options.disable_context_files = true;
            options
        })
        .expect("resources");
        let (session, faux) = test_session_with(cwd.path(), None, None, Vec::new());
        session.set_session_dir(session_dir.path().to_path_buf());
        session
            .attach_resources(resources.clone())
            .await
            .expect("attach resources");
        session
            .start_new_recording()
            .expect("start orchestration recording");
        let model = session.model().expect("session model");
        let (runtime, releases) = gated_todo_runtime(cwd.path(), 3, model);
        let fixture = TestApplicationFixture {
            application: Application::new(session).await,
            _cwd: None,
            _agent: agent,
            _session: session_dir,
            _faux: faux,
            _resources: resources,
        };
        fixture
            .application
            .attach_orchestration(runtime)
            .await
            .expect("attach gated orchestration");
        let application = &fixture.application;
        let mut events = application.subscribe();
        let mut state = todo_test_state(Vec::new());
        application
            .set_todos(vec![TodoPhase {
                name: "Build".to_owned(),
                tasks: vec![
                    todo_item("plan", "Plan", TodoStatus::Pending, false, &[]),
                    todo_item("implement", "Implement", TodoStatus::Pending, false, &[]),
                    todo_item("verify", "Verify", TodoStatus::Pending, false, &[]),
                ],
            }])
            .expect("set todos");

        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                loop {
                    match events.try_recv() {
                        Ok(event) => state.apply_live_application_event(&application, event),
                        Err(TryRecvError::Empty) => break,
                        Err(TryRecvError::Lagged(count)) => {
                            panic!("application event receiver lagged by {count} during setup")
                        }
                        Err(TryRecvError::Closed) => {
                            panic!("application event receiver closed during setup")
                        }
                    }
                }
                let todo_state = application.todo_state();
                let tasks = todo_state
                    .phases
                    .iter()
                    .flat_map(|phase| &phase.tasks)
                    .collect::<Vec<_>>();
                let runtime = application
                    .orchestration_runtime()
                    .expect("orchestration runtime");
                let jobs = runtime.jobs(None);
                let in_progress = tasks.len() == 3
                    && tasks.iter().all(|task| task.status == TodoStatus::InProgress)
                    && tasks.iter().any(|task| task.content == "Plan")
                    && tasks.iter().any(|task| task.content == "Implement")
                    && tasks.iter().any(|task| task.content == "Verify");
                let task_ids = tasks
                    .iter()
                    .map(|task| task.id.as_str())
                    .collect::<HashSet<_>>();
                let running = jobs.len() == 3
                    && jobs.iter().all(|job| job.status == JobStatus::Running)
                    && jobs.iter().all(|job| {
                        job.todo_task_id
                            .as_deref()
                            .is_some_and(|task_id| task_ids.contains(task_id))
                    });
                if in_progress && running {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("timed out waiting for three InProgress tasks and Running jobs");

        loop {
            match events.try_recv() {
                Ok(event) => state.apply_live_application_event(&application, event),
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Lagged(count)) => {
                    panic!("application event receiver lagged by {count} before mount")
                }
                Err(TryRecvError::Closed) => {
                    panic!("application event receiver closed before mount")
                }
            }
        }

        let mut mouse = TestCodeReviewMouse::default();
        state
            .open_todo_dag_panel(&application, &mut mouse)
            .expect("open todo");
        assert_eq!(
            state.todo_dag_panel.as_ref().map(TodoDagPanel::surface),
            Some(TodoSurface::Todo)
        );

        let backend = TestBackend::new(120, 30);
        let mut terminal = Terminal::new(backend).expect("terminal");
        terminal
            .draw(|frame| {
                render_todo_dag_panel(
                    frame,
                    state.todo_dag_panel.as_ref().expect("panel"),
                    crate::theme::DARK,
                )
            })
            .expect("initial render");
        let initial_rows = todo_panel_row_texts(terminal.backend());
        assert!(
            initial_rows.iter().any(|row| row.contains("Todo · Tasks")),
            "Tasks surface title missing: {initial_rows:?}"
        );
        assert!(
            initial_rows.iter().any(|row| {
                row.contains("› Main session")
                    && row.contains("[main]")
                    && row.contains("active · ✓ 0 completed · 3 open · 3 active · 0 waiting")
            }),
            "active header missing: {initial_rows:?}"
        );
        for line in [
            "● Plan · in progress",
            "● Implement · in progress",
            "● Verify · in progress",
        ] {
            assert_eq!(
                initial_rows.iter().filter(|row| row.contains(line)).count(),
                1,
                "expected one initial row {line:?}: {initial_rows:?}"
            );
        }
        for name in ["Plan", "Implement", "Verify"] {
            assert!(
                initial_rows
                    .iter()
                    .all(|row| !row.contains(&format!("✓ {name}"))),
                "completed marker leaked for {name} before terminal jobs: {initial_rows:?}"
            );
        }
        assert_eq!(state.main_todo_status, MainTodoStatus::Running);
        assert!(matches!(
            state
                .todo_dag_panel
                .as_ref()
                .and_then(TodoDagPanel::selected_dag)
                .map(|dag| &dag.execution),
            Some(TodoDagExecutionLabel::Main(TodoDagExecutionStatus::Active))
        ));

        {
            let gates = releases.lock().expect("todo child gates");
            for id in ["Todo1", "Todo2", "Todo3"] {
                gates
                    .get(id)
                    .unwrap_or_else(|| panic!("missing release gate for {id}"))
                    .cancel();
            }
        }

        let mut completed_jobs = 0usize;
        let mut saw_completed_todo_updated = false;
        let mut last_todo_updated_status = None;
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            loop {
                match events.try_recv() {
                    Ok(event) => {
                        match &event {
                            ApplicationEvent::Orchestration(
                                pi_coding::OrchestrationEvent::JobUpdated { job, .. },
                            ) if job.status == JobStatus::Completed => {
                                completed_jobs += 1;
                            }
                            ApplicationEvent::TodoUpdated {
                                phases,
                                execution_status,
                                ..
                            } => {
                                if phases.iter().flat_map(|phase| &phase.tasks).any(|task| {
                                    task.status == TodoStatus::Completed
                                }) {
                                    saw_completed_todo_updated = true;
                                }
                                last_todo_updated_status = Some(*execution_status);
                            }
                            _ => {}
                        }
                        state.apply_live_application_event(&application, event);
                    }
                    Err(TryRecvError::Empty) => {
                        if application.todo_dag_outcome().status
                            == TodoDagExecutionStatus::Settled
                            && completed_jobs == 3
                        {
                            break;
                        }
                        tokio::task::yield_now().await;
                    }
                    Err(TryRecvError::Lagged(count)) => {
                        panic!("application event receiver lagged by {count} after terminal jobs")
                    }
                    Err(TryRecvError::Closed) => {
                        panic!("application event receiver closed after terminal jobs")
                    }
                }
            }
        })
        .await
        .expect("timed out waiting for settled Todo DAG via live events");

        assert_eq!(completed_jobs, 3);
        assert!(
            saw_completed_todo_updated,
            "expected a TodoUpdated payload with a newly completed task after mount"
        );
        assert_eq!(
            last_todo_updated_status,
            Some(TodoDagExecutionStatus::Active),
            "last TodoUpdated must stay Active; Settled is written only by the outer refresh"
        );
        assert_eq!(
            application.todo_dag_outcome().status,
            TodoDagExecutionStatus::Settled
        );
        assert!(matches!(
            state
                .todo_dag_panel
                .as_ref()
                .and_then(TodoDagPanel::selected_dag)
                .map(|dag| &dag.execution),
            Some(TodoDagExecutionLabel::Main(TodoDagExecutionStatus::Settled))
        ));

        terminal
            .draw(|frame| {
                render_todo_dag_panel(
                    frame,
                    state.todo_dag_panel.as_ref().expect("panel"),
                    crate::theme::DARK,
                )
            })
            .expect("final render");
        let final_rows = todo_panel_row_texts(terminal.backend());
        assert!(
            final_rows.iter().any(|row| {
                row.contains("settled · ✓ 3 completed · 0 open · 0 active · 0 waiting")
            }),
            "settled header missing: {final_rows:?}"
        );
        for line in [
            "✓ Plan · completed",
            "✓ Implement · completed",
            "✓ Verify · completed",
        ] {
            let matching = final_rows
                .iter()
                .filter(|row| row.contains(line))
                .collect::<Vec<_>>();
            assert_eq!(
                matching.len(),
                1,
                "expected one settled row {line:?}: {final_rows:?}"
            );
            assert!(
                matching
                    .iter()
                    .all(|row| !row.contains('●') && !row.contains('○')),
                "settled row still shows an open marker: {matching:?}"
            );
        }
        assert_eq!(state.main_todo_status, MainTodoStatus::Succeeded);
        assert!(state.todo_phases.iter().flat_map(|phase| &phase.tasks).all(
            |task| task.status == TodoStatus::Completed
        ));
        let selected = state
            .todo_dag_panel
            .as_ref()
            .and_then(TodoDagPanel::selected_dag)
            .expect("selected dag");
        assert!(
            selected
                .phases
                .iter()
                .flat_map(|phase| &phase.tasks)
                .all(|task| task.status == TodoStatus::Completed)
        );
        assert_eq!(
            selected.counts(),
            crate::todo_dag_panel::TodoDagCounts {
                completed: 3,
                open: 0,
                active: 0,
                waiting: 0,
            }
        );

        application.cleanup().await;
    }


