    #[tokio::test]
    async fn todo_bare_and_list_mount_both_subpages_after_child_load() {
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;
        application
            .session()
            .start_new_recording()
            .expect("start test recording");
        let mut state = todo_test_state(Vec::new());
        let mut mouse = TestCodeReviewMouse::default();
        let parent_session_id = application
            .session()
            .recorder_info()
            .expect("recorded parent session")
            .0;
        let child = pi_coding::TodoChildManifestEntry {
            child_session_id: "child-1".to_owned(),
            label: Some("worker".to_owned()),
            created_at: 1,
            status: pi_coding::TodoChildStatus::Idle,
            parent_entry_id: None,
            parent_revision: 0,
            kind: pi_coding::TodoChildKind::Todo,
        };
        state.todo_child_parent_session_id = Some(parent_session_id.clone());

        for (label, arg) in [("/todo", None), ("/todo list", Some("list"))] {
            state.todo_child_panel = None;
            state.todo_child_open_pending = None;
            state.editor.set_text(label);
            assert!(
                dispatch_todo_command(&application, &mut state, &mut mouse, arg)
                    .expect("dispatch list"),
                "{label} must be consumed by the unified /todo dispatch"
            );
            finish_submitted_slash_command(&mut state);
            assert!(
                state.editor.is_empty(),
                "{label} must clear submitted slash text"
            );
            // The unified overlay owns both domains: the Tasks subpage is
            // mounted immediately and the Child list is pending in the
            // background. Tasks stays focused on open.
            assert!(
                state.todo_dag_panel.is_some(),
                "{label} must mount the Tasks subpage"
            );
            assert_eq!(
                state.todo_overlay_page,
                TodoOverlayPage::Dag,
                "{label} must focus the Tasks subpage on open"
            );
            let (_, request_generation) = match state.todo_child_open_pending.clone() {
                Some(pending) => pending,
                None => panic!("{label} must produce todo_child_open_pending"),
            };

            state.apply_background(BackgroundEvent::TodoChildCommandFinished {
                open_page: true,
                request_generation,
                effect: crate::todo_child_commands::TodoChildCommandEffect {
                    message: "listed".to_owned(),
                    is_success: true,
                    parent_session_id: Some(parent_session_id.clone()),
                    child_session_id: None,
                    should_refresh: true,
                    children: Some(vec![child.clone()]),
                    refresh_error: None,
                },
                detail: None,
            });
            assert!(
                state.todo_child_panel.is_some(),
                "{label} must mount the Child subpage after background completion"
            );
            assert!(
                state.todo_dag_panel.is_some(),
                "{label} must keep the Tasks subpage so one overlay owns both domains"
            );
            assert!(page_overlay_open(&state));
            assert_eq!(state.status, "listed");
        }

        application.cleanup().await;
    }

