    #[test]
    fn wrap_styled_line_keeps_cjk_zwj_and_combining_clusters() {
        let family = "\u{1f468}\u{200d}\u{1f469}\u{200d}\u{1f467}\u{200d}\u{1f466}";
        let combining = "e\u{301}";
        let family_mid = family
            .char_indices()
            .nth(1)
            .map(|(index, _)| index)
            .expect("ZWJ family has more than one scalar");
        let combining_mid = combining
            .char_indices()
            .nth(1)
            .map(|(index, _)| index)
            .expect("combining cluster has a mark");
        let payload = format!("界面{family}{combining}");
        let line = Line::from(vec![
            Span::styled("界".to_owned(), Style::default().fg(Color::Red)),
            Span::styled("面".to_owned(), Style::default().fg(Color::Magenta)),
            Span::styled(
                family[..family_mid].to_owned(),
                Style::default().fg(Color::Green),
            ),
            Span::styled(
                family[family_mid..].to_owned(),
                Style::default().fg(Color::Cyan),
            ),
            Span::styled(
                combining[..combining_mid].to_owned(),
                Style::default().fg(Color::Blue),
            ),
            Span::styled(
                combining[combining_mid..].to_owned(),
                Style::default().fg(Color::Yellow),
            ),
        ]);
        let rows = wrap_styled_line(line, 2);
        let rejoined: String = rows
            .iter()
            .flat_map(|row| row.spans.iter().map(|span| span.content.as_ref()))
            .collect();
        assert_eq!(rejoined, payload);
        let clusters: Vec<&str> = rejoined.graphemes(true).collect();
        assert!(clusters.contains(&"界"), "{clusters:?}");
        assert!(clusters.contains(&"面"), "{clusters:?}");
        assert!(clusters.contains(&family), "ZWJ family split: {clusters:?}");
        assert!(
            clusters.contains(&combining),
            "combining mark split: {clusters:?}"
        );
        for row in &rows {
            let text: String = row.spans.iter().map(|span| span.content.as_ref()).collect();
            let width = UnicodeWidthStr::width(text.as_str());
            let first = text
                .graphemes(true)
                .next()
                .map(UnicodeWidthStr::width)
                .unwrap_or(0);
            assert!(
                width <= 2 || first > 2,
                "row exceeded wrap width without an oversized cluster: {text:?}"
            );
            let row_clusters: Vec<&str> = text.graphemes(true).collect();
            if text.contains('\u{200d}') {
                assert!(
                    row_clusters.contains(&family),
                    "ZWJ family split across rows: {text:?}"
                );
            }
            if text.contains('\u{301}') {
                assert!(
                    row_clusters.contains(&combining),
                    "combining cluster split across rows: {text:?}"
                );
            }
        }
        assert_eq!(display_width(family), 2);
        assert_eq!(display_width(combining), 1);
        assert_eq!(display_width("界"), 2);
        let truncated = truncate_status_text(&format!("{family}{combining}界面"), 3);
        assert!(!truncated.contains('\u{FFFD}'));
        let truncated_clusters: Vec<&str> =
            truncated.trim_end_matches('…').graphemes(true).collect();
        for cluster in truncated_clusters {
            assert!(
                payload.graphemes(true).any(|source| source == cluster),
                "truncation split a cluster: {truncated:?}"
            );
        }
    }

    #[test]
    fn wrap_styled_line_keeps_sgr_split_zwj_and_combining_clusters() {
        let family = "\u{1f468}\u{200d}\u{1f469}\u{200d}\u{1f467}\u{200d}\u{1f466}";
        let combining = "e\u{301}";
        let family_mid = family
            .char_indices()
            .nth(1)
            .map(|(index, _)| index)
            .expect("ZWJ family has more than one scalar");
        let combining_mid = combining
            .char_indices()
            .nth(1)
            .map(|(index, _)| index)
            .expect("combining cluster has a mark");
        let ansi = format!(
            "\u{1b}[31m{}\u{1b}[32m{}\u{1b}[0m\u{1b}[34m{}\u{1b}[35m{}\u{1b}[0m",
            &family[..family_mid],
            &family[family_mid..],
            &combining[..combining_mid],
            &combining[combining_mid..]
        );
        let lines = ansi_styled_lines(&ansi, Style::default(), 2);
        let rejoined: String = lines
            .iter()
            .flat_map(|line| line.spans.iter().map(|span| span.content.as_ref()))
            .collect();
        let clusters: Vec<&str> = rejoined.graphemes(true).collect();
        assert!(
            clusters.contains(&family),
            "ZWJ family split across SGR: {clusters:?}"
        );
        assert!(
            clusters.contains(&combining),
            "combining mark split across SGR: {clusters:?}"
        );
        for line in &lines {
            let text: String = line
                .spans
                .iter()
                .map(|span| span.content.as_ref())
                .collect();
            let width = UnicodeWidthStr::width(text.as_str());
            let first = text
                .graphemes(true)
                .next()
                .map(UnicodeWidthStr::width)
                .unwrap_or(0);
            assert!(
                width <= 2 || first > 2,
                "ANSI wrap split a cluster across rows: {text:?}"
            );
            let row_clusters: Vec<&str> = text.graphemes(true).collect();
            if text.contains('\u{200d}') {
                assert!(
                    row_clusters.contains(&family),
                    "ZWJ family split across ANSI rows: {text:?}"
                );
            }
            if text.contains('\u{301}') {
                assert!(
                    row_clusters.contains(&combining),
                    "combining cluster split across ANSI rows: {text:?}"
                );
            }
        }
    }

    #[tokio::test]
    async fn todo_slash_ops_start_done_drop_clear_transition_state() {
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;
        let mut state = todo_test_state(Vec::new());
        let mut mouse = TestCodeReviewMouse::default();
        application
            .set_todos(
                pi_coding::parse_todo_markdown(
                    "# Plan\n- [ ] write the code\n- [ ] review the code\n- [ ] ship the build",
                )
                .expect("seed markdown"),
            )
            .expect("seed todos");

        fn task_status(phases: &[TodoPhase], content: &str) -> TodoStatus {
            phases
                .iter()
                .flat_map(|phase| &phase.tasks)
                .find(|task| task.content == content)
                .expect("seeded task")
                .status
        }

        // `/todo start <exact task>` (spaces included) marks it in progress.
        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("START review the code")
            )
            .expect("dispatch uppercase start")
        );
        assert_eq!(
            task_status(&application.todo_state().phases, "review the code"),
            TodoStatus::InProgress
        );
        assert_eq!(
            task_status(&state.todo_phases, "review the code"),
            TodoStatus::InProgress,
            "state mirror must follow the application"
        );

        // `/todo done <exact task>` completes it.
        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("done review the code")
            )
            .expect("dispatch done")
        );
        assert_eq!(
            task_status(&application.todo_state().phases, "review the code"),
            TodoStatus::Completed
        );
        assert_eq!(
            task_status(&state.todo_phases, "review the code"),
            TodoStatus::Completed
        );

        // `/todo drop <exact task>` abandons it (slash op stays `drop`; the
        // status is `abandoned`).
        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("drop ship the build")
            )
            .expect("dispatch drop")
        );
        assert_eq!(
            task_status(&application.todo_state().phases, "ship the build"),
            TodoStatus::Abandoned
        );
        assert_eq!(
            task_status(&state.todo_phases, "ship the build"),
            TodoStatus::Abandoned
        );

        // `/todo clear` removes every task through the application.
        assert!(
            dispatch_todo_command(&application, &mut state, &mut mouse, Some("clear"))
                .expect("dispatch clear")
        );
        assert!(
            application
                .todo_state()
                .phases
                .iter()
                .flat_map(|phase| &phase.tasks)
                .next()
                .is_none(),
            "clear must empty the plan"
        );
        assert!(
            state
                .todo_phases
                .iter()
                .flat_map(|phase| &phase.tasks)
                .next()
                .is_none(),
            "state mirror must empty too"
        );
        assert!(
            state.status.contains("Todo list cleared"),
            "clear must surface the summary: {}",
            state.status
        );

        application.cleanup().await;
    }

    #[tokio::test]
    async fn todo_slash_ops_unknown_missing_and_blocking_show_usage_or_note() {
        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;
        let mut state = todo_test_state(Vec::new());
        let mut mouse = TestCodeReviewMouse::default();
        application
            .set_todos(
                pi_coding::parse_todo_markdown("# Plan\n- [ ] write the code")
                    .expect("seed markdown"),
            )
            .expect("seed todos");

        // Malformed DAG verbs use the shared parser's exact per-verb usage.
        for (argument, usage) in [
            ("start", "usage: /todo start <task>"),
            ("done", "usage: /todo done <task>"),
            ("drop", "usage: /todo drop <task>"),
            ("clear extra", "usage: /todo clear"),
        ] {
            state.composer_error = None;
            assert!(
                dispatch_todo_command(&application, &mut state, &mut mouse, Some(argument))
                    .expect("dispatch malformed DAG verb")
            );
            assert_eq!(state.composer_error.as_deref(), Some(usage), "{argument}");
        }
        assert_eq!(
            application
                .todo_state()
                .phases
                .iter()
                .flat_map(|phase| &phase.tasks)
                .count(),
            1,
            "malformed ops must not mutate the plan"
        );

        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("frobnicate the plan")
            )
            .expect("dispatch unknown")
        );
        assert!(
            state
                .composer_error
                .as_deref()
                .is_some_and(|message| message.contains("Usage: /todo")),
            "unknown op must show usage"
        );

        state.composer_error = None;
        assert!(
            dispatch_todo_command(&application, &mut state, &mut mouse, Some("list extra"))
                .expect("dispatch malformed list")
        );
        assert!(
            state
                .composer_error
                .as_deref()
                .is_some_and(|message| message.contains("usage: /todo list")),
            "list with a tail must use the child parser's exact usage"
        );
        assert!(
            state.todo_child_panel.is_none(),
            "malformed list must not open the Child page"
        );

        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("# Replaced\n- [ ] markdown task"),
            )
            .expect("dispatch markdown")
        );
        assert_eq!(application.todo_state().phases[0].name, "Replaced");
        assert_eq!(
            application.todo_state().phases[0].tasks[0].content,
            "markdown task"
        );

        // Legacy block/unblock verbs are no longer Todo operations.
        let before = application.todo_state().phases;
        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("block write the code")
            )
            .expect("dispatch unknown block verb")
        );
        let note = state.composer_error.as_deref().expect("usage note");
        assert!(
            note.contains("Usage: /todo"),
            "removed block verb must show current usage: {note}"
        );
        assert_eq!(
            application.todo_state().phases,
            before,
            "unknown verb must not mutate the plan"
        );

        // A task reference that does not exist fails actionably through the
        // application's own resolver.
        assert!(
            dispatch_todo_command(
                &application,
                &mut state,
                &mut mouse,
                Some("done no such task")
            )
            .expect("dispatch missing task")
        );
        assert!(
            state
                .composer_error
                .as_deref()
                .is_some_and(|message| message.contains("not found")),
            "missing task must surface the application error"
        );

        application.cleanup().await;
    }

