    #[tokio::test]
    async fn commit_dispatch_direct_ref_opens_panel_and_rejects_extra_operands() {
        let repo = init_hermetic_git_repo();
        let application = test_application(repo.path()).await;
        let mut mouse = TestCodeReviewMouse::default();

        // One operand: the review page opens and the requested Commit scope
        // is stored verbatim; the core loader resolves and pins it when the
        // snapshot lands.
        let mut state = todo_test_state(Vec::new());
        state.cwd_path = repo.path().to_path_buf();
        dispatch_commit_command(&application, &mut state, Some("HEAD"), &mut mouse)
            .await
            .expect("dispatch /commit HEAD");
        assert!(state.code_review_panel.is_some());
        assert!(state.panel.is_none());
        assert_eq!(
            state.code_review_scope,
            ReviewScope::Commit {
                commit: "HEAD".to_owned(),
                label: String::new(),
            }
        );
        state.shutdown_code_review().await;

        // More than one operand is a usage error: no page opens and no git
        // commit/checkout path exists behind this command.
        let mut state = todo_test_state(Vec::new());
        state.cwd_path = repo.path().to_path_buf();
        dispatch_commit_command(&application, &mut state, Some("HEAD~1 HEAD"), &mut mouse)
            .await
            .expect("dispatch /commit with two refs");
        assert!(state.code_review_panel.is_none());
        assert!(state.panel.is_none());
        let usage = state.composer_error.as_deref().expect("usage status");
        assert!(
            usage.contains("Usage: /commit"),
            "extra operands must surface usage: {usage}"
        );

        application.cleanup().await;
    }

    #[tokio::test]
    async fn commit_picker_bare_dispatch_lists_commits_and_enter_pins_exact_id() {
        let repo = init_hermetic_git_repo();
        let application = test_application(repo.path()).await;
        let mut mouse = TestCodeReviewMouse::default();
        let mut state = todo_test_state(Vec::new());
        state.cwd_path = repo.path().to_path_buf();

        dispatch_commit_command(&application, &mut state, None, &mut mouse)
            .await
            .expect("dispatch bare /commit");
        let panel = state.panel.as_ref().expect("commit picker opens");
        assert_eq!(panel.title, "Recent commits");
        assert!(panel.items.is_empty(), "rows arrive via background event");
        assert_eq!(state.status, "Loading recent commits…");
        let generation = state.commit_picker_generation;

        let list = crate::code_review::list_recent_commits(repo.path(), 100)
            .expect("recent commit list");
        state.apply_background(BackgroundEvent::CommitListLoaded {
            generation,
            cwd: repo.path().to_path_buf(),
            result: Ok(list),
        });
        assert_eq!(state.status, "Ready");
        let panel = state.panel.as_ref().expect("picker stays open after fill");
        assert!(panel.help.is_empty());
        assert_eq!(panel.items.len(), 1, "the fixture repo has one commit");
        let output = std::process::Command::new("git")
            .args(["rev-parse", "HEAD"])
            .current_dir(repo.path())
            .env("GIT_CONFIG_NOSYSTEM", "1")
            .env("GIT_CONFIG_GLOBAL", "/dev/null")
            .output()
            .expect("rev-parse HEAD");
        assert!(output.status.success(), "rev-parse HEAD failed");
        let head = String::from_utf8(output.stdout)
            .expect("utf8 commit id")
            .trim()
            .to_owned();
        let selected = panel.selected_item().expect("selected row").clone();
        assert_eq!(
            selected.label,
            format!("{} init", &head[..COMMIT_PICKER_SHA_CHARS]),
            "row must show shortsha plus subject: {}",
            selected.label
        );
        assert!(
            selected.description.starts_with("Pi Test · "),
            "row must show author and date: {}",
            selected.description
        );
        let PanelValue::CommitReview(commit) = selected.value.clone() else {
            panic!("row value must carry the commit id");
        };
        assert_eq!(commit, head, "Enter must carry the full commit id");
        assert!(state.code_review_panel.is_none());

        // The same function the panel Enter arm calls: opens the review page
        // bound to the exact id, not a movable ref.
        open_commit_review_selection(&application, &mut state, commit, &mut mouse)
            .await
            .expect("open commit review from picker selection");
        assert!(state.panel.is_none(), "picker closes on selection");
        assert!(state.code_review_panel.is_some());
        assert_eq!(
            state.code_review_scope,
            ReviewScope::Commit {
                commit: head,
                label: String::new(),
            }
        );

        state.shutdown_code_review().await;
        application.cleanup().await;
    }

    #[tokio::test]
    async fn commit_review_refresh_rebinds_to_accepted_snapshot_scope() {
        let cwd = PathBuf::from("repo");
        let fixture = tempfile::tempdir().expect("app fixture");
        let application = test_application(fixture.path()).await;
        let mut state = todo_test_state(Vec::new());
        state.cwd_path = cwd.clone();
        let requested = ReviewScope::Commit {
            commit: "main".to_owned(),
            label: String::new(),
        };
        state.code_review_panel = Some(CodeReviewPanel::loading(cwd.clone(), requested.clone()));
        let controller = CodeReviewController::fork_from(&application)
            .await
            .expect("fork review controller");
        state.code_review_controller = Some(controller);
        state.code_review_scope = requested;
        state.code_review_load_generation += 1;
        let generation = state.code_review_load_generation;
        let controller_generation = state.code_review_controller_generation;
        state.code_review_load_in_flight = Some((controller_generation, generation, cwd.clone()));

        // The core loader resolved `main` once and returned the pinned
        // immutable id; refresh must adopt that scope, not the branch ref.
        let accepted = crate::code_review::ReviewSnapshot {
            root: cwd.clone(),
            scope: ReviewScope::Commit {
                commit: "pinned-full-id".to_owned(),
                label: "abc → pinned-full-id".to_owned(),
            },
            snapshot_id: "accepted-snapshot".to_owned(),
            files: Vec::new(),
            truncated: false,
            total_insertions: 0,
            total_deletions: 0,
            summary_complete: true,
            error: None,
        };
        state
            .apply_background_async(BackgroundEvent::CodeReviewSnapshotLoaded {
                controller_generation,
                generation,
                cwd: cwd.clone(),
                snapshot: accepted,
                paging: ReviewPagingState::default(),
            })
            .await;

        assert_eq!(
            state.code_review_scope,
            ReviewScope::Commit {
                commit: "pinned-full-id".to_owned(),
                label: "abc → pinned-full-id".to_owned(),
            },
            "refresh must be bound to the accepted snapshot scope, not the requested ref"
        );
        assert!(state.code_review_load_in_flight.is_none());
        state.shutdown_code_review().await;
        application.cleanup().await;
    }

