    /// Brute-force reference for `overflow_commit_batch`: re-renders the
    /// remaining tail fresh each step (the pre-fix algorithm) and pops while
    /// the fresh render exceeds the viewport and more than one live entry
    /// remains. The incremental implementation must return the same batch
    /// length without re-rendering per step.
    fn overflow_commit_batch_reference(state: &TuiState, width: u16, viewport_rows: u16) -> usize {
        if state.transcript_top_row.get().is_some() || state.hydration_prefix_pending() > 0 {
            return 0;
        }
        let theme = state.themes.theme();
        let width = width.max(1);
        let settled_end = state.settled_end();
        let live_entries = state
            .transcript
            .len()
            .saturating_sub(state.committed_entries);
        let mut end = state.committed_entries;
        loop {
            let mut remaining = assemble_transcript_entries(
                &state.transcript[end..],
                state.show_thinking,
                state.expand_tools,
                theme,
                width,
            );
            if !state.streaming_thinking.is_empty() || !state.streaming_text.is_empty() {
                let mut content = Vec::new();
                if !state.streaming_thinking.is_empty() {
                    content.push(ContentBlock::thinking(state.streaming_thinking.clone()));
                }
                if !state.streaming_text.is_empty() {
                    content.push(ContentBlock::text(state.streaming_text.clone()));
                }
                render_transcript_entry(
                    &mut remaining,
                    &TranscriptEntry {
                        kind: TranscriptKind::Assistant,
                        content,
                        tool_name: None,
                        tool_card: None,
                        is_error: false,
                        is_partial: true,
                    },
                    state.show_thinking,
                    state.expand_tools,
                    theme,
                    width,
                );
            }
            let rows = wrapped_line_count(&remaining, width);
            if rows > usize::from(viewport_rows.max(1))
                && end < settled_end
                && live_entries.saturating_sub(end - state.committed_entries) > 1
            {
                end += 1;
            } else {
                break;
            }
        }
        end - state.committed_entries
    }

    /// Correctness identity for `overflow_commit_batch`: the incremental
    /// row-count implementation must return the same batch length a fresh
    /// per-step re-render would, across separator-sensitive viewports. Uses
    /// SHORT cards (one content row each) so the 1-row inter-entry separator
    /// is significant relative to the viewport — the case the pre-fix
    /// incremental math got wrong by leaving a stale leading separator in the
    /// running total and over-committing one entry when the remaining tail was
    /// ≈ viewport. The sweep covers every viewport from 1 up to the full tail
    /// so the boundary where fresh-remaining == viewport is always exercised.
    #[test]
    fn overflow_commit_batch_matches_fresh_render_across_separator_sensitive_viewports() {
        // Short assistant cards (1 content row) + a user card (padding rows)
        // so both separator-suppression paths (inter-entry blank, user-card
        // bottom edge) are exercised.
        let mut state = todo_test_state(Vec::new());
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text("prompt")],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        for i in 0..6 {
            state.push_entry(TranscriptEntry {
                kind: TranscriptKind::Assistant,
                content: vec![ContentBlock::text(format!("answer {i}"))],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            });
        }
        for &width in &[40u16, 80, 120] {
            // Tail height varies with width; sweep every viewport so the
            // exact boundary (fresh remaining == viewport) is hit.
            let tail_rows = wrapped_line_count(
                &assemble_transcript_entries(
                    &state.transcript[state.committed_entries..],
                    state.show_thinking,
                    state.expand_tools,
                    state.themes.theme(),
                    width,
                ),
                width,
            );
            for vp in 1..=(tail_rows + 2) {
                let got = state
                    .overflow_commit_batch(width, u16::try_from(vp).unwrap_or(u16::MAX))
                    .len();
                let want = overflow_commit_batch_reference(
                    &state,
                    width,
                    u16::try_from(vp).unwrap_or(u16::MAX),
                );
                assert_eq!(
                    got, want,
                    "width={width} vp={vp}: incremental batch {got} != fresh-render reference {want} \
                     (separator-sensitive over-commit regression)",
                );
            }
        }
        // Streaming block is never popped: it stays in the running total and
        // the reference must still agree.
        state.streaming_text = "live delta".to_owned();
        for &vp in &[1u16, 2, 3, 5, 8, 12] {
            let got = state.overflow_commit_batch(80, vp).len();
            let want = overflow_commit_batch_reference(&state, 80, vp);
            assert_eq!(got, want, "streaming vp={vp}: {got} != {want}");
        }
    }

    /// Scaling bench for `overflow_commit_batch`: forces the loop to pop one
    /// settled entry at a time (viewport_rows = 1) so per-iteration work
    /// dominates. Each assistant entry carries multi-paragraph markdown that
    /// wraps to several rows. The n=256/n=64 time ratio must stay well below
    /// the quadratic 16× (pre-fix was 14.6× / 3.74s); a linear implementation
    /// is ~4×. Run with
    /// `cargo test --package pi-cli --lib overflow_commit_batch_scaling -- --nocapture --ignored`.
    #[test]
    #[ignore]
    fn overflow_commit_batch_scaling() {
        let mk = |n: usize| -> TuiState {
            let mut state = todo_test_state(Vec::new());
            for i in 0..n {
                let body = format!(
                    "# Heading {i}\n\nParagraph one explains the change with **bold** and *italic* detail that wraps across several terminal rows at width 80 so the markdown renderer and the wrapped-line counter both do real work per entry.\n\n- item alpha\n- item beta\n- item gamma\n\n```\nlet v: usize = parse(42);\n```"
                );
                state.push_entry(TranscriptEntry {
                    kind: TranscriptKind::Assistant,
                    content: vec![ContentBlock::text(body)],
                    tool_name: None,
                    tool_card: None,
                    is_error: false,
                    is_partial: false,
                });
            }
            state
        };
        let timings: Vec<(usize, std::time::Duration)> = [64usize, 128, 256]
            .iter()
            .map(|&n| {
                let state = mk(n);
                let start = std::time::Instant::now();
                let batch = state.overflow_commit_batch(80, 1);
                let elapsed = start.elapsed();
                assert_eq!(batch.len(), n - 1);
                (n, elapsed)
            })
            .collect();
        for (n, t) in &timings {
            eprintln!("overflow_commit_batch(n={n}, viewport=1): {t:?}");
        }
        let r = timings[2].1.as_secs_f64() / timings[0].1.as_secs_f64();
        eprintln!("n=256 / n=64 time ratio = {r:.2} (linear ≈ 4x; pre-fix quadratic was 14.6x)");
        assert!(r < 8.0, "expected sub-quadratic scaling, got ratio {r:.2}");
    }

