    #[test]
    fn inline_commit_clears_live_composer_before_scrollback_advances() {
        use ratatui::backend::TestBackend;

        let mut terminal = Terminal::with_options(
            TestBackend::new(20, 5),
            TerminalOptions {
                viewport: Viewport::Inline(5),
            },
        )
        .expect("inline terminal");
        terminal
            .draw(|frame| {
                Paragraph::new(
                    [
                        "live transcript",
                        "╭── π working",
                        "╰─",
                        "transient status",
                        "transient overlay",
                    ]
                    .join("\n"),
                )
                .render(frame.area(), frame.buffer_mut());
            })
            .expect("draw mutable live frame");

        // Production commit ordering: clear mutable viewport pixels before
        // ratatui scrolls the full-height inline area to insert durable rows.
        clear_inline_viewport(&mut terminal).expect("clear mutable live viewport");
        terminal
            .insert_before(2, |buffer| {
                Paragraph::new("committed user\ncommitted assistant").render(buffer.area, buffer);
            })
            .expect("insert durable transcript rows");

        let retained = terminal
            .backend()
            .scrollback()
            .content
            .chunks(20)
            .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
            .collect::<Vec<_>>();
        assert!(
            retained.iter().all(|row| !row.contains("╭── π")
                && !row.contains("╰─")
                && !row.contains("transient")),
            "mutable composer/status rows must not enter scrollback: {retained:#?}"
        );
    }

    #[test]
    fn live_viewport_size_change_blanks_previous_live_frame() {
        use ratatui::backend::TestBackend;

        let mut terminal = Terminal::with_options(
            TestBackend::new(20, 5),
            TerminalOptions {
                viewport: Viewport::Inline(5),
            },
        )
        .expect("inline terminal");
        terminal
            .draw(|frame| {
                Paragraph::new(
                    [
                        "live transcript",
                        "╭── π working",
                        "╰─",
                        "transient status",
                        "transient overlay",
                    ]
                    .join("\n"),
                )
                .render(frame.area(), frame.buffer_mut());
            })
            .expect("draw mutable live frame");
        let painted = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(
            painted.contains("live transcript") && painted.contains("transient"),
            "precondition: live frame painted: {painted}"
        );

        let mut last_size = terminal.size().expect("size");
        terminal.backend_mut().resize(28, 5);
        let changed = apply_live_viewport_size_change(&mut terminal, &mut last_size)
            .expect("size-change path");
        assert!(changed, "backend size change must be observed");
        assert_eq!(
            last_size,
            Size {
                width: 28,
                height: 5
            }
        );

        let blanked = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(
            !blanked.contains("live transcript")
                && !blanked.contains("╭── π")
                && !blanked.contains("transient"),
            "size change must blank the previous live frame: {blanked:?}"
        );
        terminal.backend().assert_scrollback_empty();

        // Overlay-dismiss clearing uses the same CurrentLine blanking.
        terminal
            .draw(|frame| {
                Paragraph::new("settings overlay chrome\nCtrl-S apply")
                    .render(frame.area(), frame.buffer_mut());
            })
            .expect("draw overlay frame");
        clear_inline_viewport(&mut terminal).expect("overlay dismiss clear");
        let dismissed = terminal
            .backend()
            .buffer()
            .content
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(
            !dismissed.contains("settings overlay") && !dismissed.contains("Ctrl-S apply"),
            "overlay dismiss must blank the live area: {dismissed:?}"
        );
        terminal.backend().assert_scrollback_empty();
    }

