    #[test]
    fn working_and_compaction_animate_only_while_active() {
        // Busy states animate the OMP-style status line above the input box;
        // the static footer header never changes frame to frame.
        fn header(state: &TuiState) -> String {
            composer_border_lines(state, 90, crate::theme::DARK)[0]
                .spans
                .iter()
                .map(|span| span.content.as_ref())
                .collect::<String>()
        }
        fn status(state: &TuiState) -> String {
            composer_status_line(state, 90, crate::theme::DARK)
                .spans
                .iter()
                .map(|span| span.content.as_ref())
                .collect::<String>()
        }
        let mut state = todo_test_state(Vec::new());
        state.is_streaming = true;
        let footer_first = header(&state);
        let working_first = status(&state);
        state.animation_frame = 1;
        let working_second = status(&state);
        assert_ne!(working_first, working_second, "working status must animate");
        assert!(
            working_first.contains("Working"),
            "working label: {working_first}"
        );
        assert_eq!(
            footer_first,
            header(&state),
            "footer must stay static while streaming"
        );

        state.is_streaming = false;
        state.is_compacting = true;
        let compacting_first = status(&state);
        state.animation_frame = 2;
        let compacting_second = status(&state);
        assert_ne!(
            compacting_first, compacting_second,
            "compacting status must animate"
        );
        assert!(
            compacting_first.contains("Compacting"),
            "compacting label: {compacting_first}"
        );

        state.is_compacting = false;
        let idle_first = status(&state);
        state.animation_frame = 3;
        let idle_second = status(&state);
        assert_eq!(idle_first, idle_second, "idle status line must be stable");
        assert!(
            idle_first.is_empty(),
            "idle status line must be blank: {idle_first:?}"
        );
        assert!(!state.has_active_animation());
    }

    #[test]
    fn job_and_todo_updates_preserve_scrolled_anchor_and_oldest_sentinel() {
        let mut state = todo_test_state(Vec::new());
        for i in 0..96 {
            state.push_entry(TranscriptEntry {
                kind: TranscriptKind::Assistant,
                content: vec![ContentBlock::text(if i == 0 {
                    "STABLE OLDEST SENTINEL".to_owned()
                } else {
                    format!("history row {i}")
                })],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            });
        }
        let mut job = pi_coding::JobSnapshot {
            id: "stable-job".to_owned(),
            agent_id: "Child".to_owned(),
            agent: "task".to_owned(),
            parent_id: "Main".to_owned(),
            description: Some("history stability".to_owned()),
            todo_task_id: None,
            workflow_id: None,
            workflow_generation: None,
            status: pi_coding::JobStatus::Running,
            created_at: 1,
            started_at: Some(1),
            finished_at: None,
            result: None,
            soft_budget_exhausted: false,
        };
        state.apply(ApplicationEvent::Orchestration(
            pi_coding::OrchestrationEvent::JobUpdated {
                group_id: "stable-group".to_owned(),
                job: job.clone(),
            },
        ));
        state.committed_entries = 64;
        state.hydration_flushed_entries = 64;
        state.transcript_render_start.set(64);
        let height = 10usize;
        let render = |state: &mut TuiState| -> (Vec<String>, usize) {
            let mut renderer = TerminalImageRenderer::default();
            let mut candidates = Vec::new();
            let mut image_context = TranscriptImageContext {
                renderer: &mut renderer,
                candidates: &mut candidates,
                config: ImageDisplayConfig {
                    show_images: false,
                    width_cells: 50,
                },
                viewport_columns: 80,
                viewport_rows: u16::try_from(height).unwrap(),
                cell_size: TerminalCellSize::default(),
            };
            let (lines, starts) =
                render_transcript_lines(state, crate::theme::DARK, 80, &mut image_context);
            let total_rows = wrapped_line_count(&lines, 80);
            let scroll = transcript_scroll_offset(state, &starts, total_rows, height);
            let plain = lines
                .iter()
                .map(|line| {
                    line.spans
                        .iter()
                        .map(|span| span.content.as_ref())
                        .collect::<String>()
                })
                .collect();
            (plain, scroll)
        };
        let _ = render(&mut state);
        for _ in 0..128 {
            state.page_transcript(-1);
            let _ = render(&mut state);
            if state.transcript_render_start.get() == 0 && state.scroll_anchor.get().0 == 0 {
                break;
            }
        }
        let (plain_before, scroll_before) = render(&mut state);
        let anchor_before = state.scroll_anchor.get();
        let top_before = state.transcript_top_row.get();
        assert!(
            plain_before[scroll_before..(scroll_before + height).min(plain_before.len())]
                .iter()
                .any(|line| line.contains("STABLE OLDEST SENTINEL"))
        );

        for tick in 2..66 {
            state.apply(ApplicationEvent::TodoUpdated {
                phases: Vec::new(),
                completed_tasks: Vec::new(),
                execution_status: pi_coding::TodoDagExecutionStatus::Dormant,
                failure_reason: None,
            });
            job.started_at = Some(tick);
            state.apply(ApplicationEvent::Orchestration(
                pi_coding::OrchestrationEvent::JobUpdated {
                    group_id: "stable-group".to_owned(),
                    job: job.clone(),
                },
            ));
            assert_eq!(state.scroll_anchor.get(), anchor_before);
            assert_eq!(state.transcript_top_row.get(), top_before);
        }

        let (plain_after, scroll_after) = render(&mut state);
        assert_eq!(state.scroll_anchor.get(), anchor_before);
        assert_eq!(state.transcript_top_row.get(), top_before);
        assert!(
            plain_after[scroll_after..(scroll_after + height).min(plain_after.len())]
                .iter()
                .any(|line| line.contains("STABLE OLDEST SENTINEL"))
        );
        assert_eq!(state.committed_entries, 64);
    }

    #[test]
    fn tool_and_bash_updates_preserve_scrolled_anchor_and_oldest_sentinel() {
        use pi_agent::AgentToolResult;
        let mut state = todo_test_state(Vec::new());
        for i in 0..96 {
            state.push_entry(TranscriptEntry {
                kind: TranscriptKind::Assistant,
                content: vec![ContentBlock::text(if i == 0 {
                    "STABLE OLDEST SENTINEL".to_owned()
                } else {
                    format!("history row {i}")
                })],
                tool_name: None,
                tool_card: None,
                is_error: false,
                is_partial: false,
            });
        }
        state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionStart {
            tool_call_id: "stable-tool".to_owned(),
            tool_name: "read".to_owned(),
            arguments: serde_json::json!({"path": "stable.rs"}),
        }));
        state.apply(ApplicationEvent::Session(
            pi_coding::SessionEvent::BashExecutionEnd {
                message: pi_ai::BashExecutionMessage {
                    command: "echo stable".to_owned(),
                    output: "first".to_owned(),
                    exit_code: Some(0),
                    cancelled: false,
                    truncated: false,
                    full_output_path: None,
                    timestamp: 1,
                    exclude_from_context: None,
                },
            },
        ));
        state.committed_entries = 64;
        state.hydration_flushed_entries = 64;
        state.transcript_render_start.set(64);
        let height = 10usize;
        let render = |state: &mut TuiState| -> (Vec<String>, usize) {
            let mut renderer = TerminalImageRenderer::default();
            let mut candidates = Vec::new();
            let mut image_context = TranscriptImageContext {
                renderer: &mut renderer,
                candidates: &mut candidates,
                config: ImageDisplayConfig {
                    show_images: false,
                    width_cells: 50,
                },
                viewport_columns: 80,
                viewport_rows: u16::try_from(height).unwrap(),
                cell_size: TerminalCellSize::default(),
            };
            let (lines, starts) =
                render_transcript_lines(state, crate::theme::DARK, 80, &mut image_context);
            let total_rows = wrapped_line_count(&lines, 80);
            let scroll = transcript_scroll_offset(state, &starts, total_rows, height);
            let plain = lines
                .iter()
                .map(|line| {
                    line.spans
                        .iter()
                        .map(|span| span.content.as_ref())
                        .collect::<String>()
                })
                .collect();
            (plain, scroll)
        };
        let _ = render(&mut state);
        for _ in 0..128 {
            state.page_transcript(-1);
            let _ = render(&mut state);
            if state.transcript_render_start.get() == 0 && state.scroll_anchor.get().0 == 0 {
                break;
            }
        }
        let (plain_before, scroll_before) = render(&mut state);
        let anchor_before = state.scroll_anchor.get();
        let top_before = state.transcript_top_row.get();
        assert!(
            top_before.is_some(),
            "reader must be parked before in-place card updates"
        );
        assert!(
            plain_before[scroll_before..(scroll_before + height).min(plain_before.len())]
                .iter()
                .any(|line| line.contains("STABLE OLDEST SENTINEL"))
        );

        for tick in 2..66 {
            state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionUpdate {
                tool_call_id: "stable-tool".to_owned(),
                tool_name: "read".to_owned(),
                arguments: serde_json::json!({"path": "stable.rs"}),
                partial_result: AgentToolResult::text(format!("partial {tick}")),
            }));
            state.apply(ApplicationEvent::Session(
                pi_coding::SessionEvent::BashExecutionEnd {
                    message: pi_ai::BashExecutionMessage {
                        command: "echo stable".to_owned(),
                        output: format!("tick {tick}"),
                        exit_code: Some(0),
                        cancelled: false,
                        truncated: false,
                        full_output_path: None,
                        timestamp: 1,
                        exclude_from_context: None,
                    },
                },
            ));
            assert_eq!(state.scroll_anchor.get(), anchor_before);
            assert_eq!(state.transcript_top_row.get(), top_before);
        }

        state.apply(ApplicationEvent::Agent(AgentEvent::ToolExecutionEnd {
            tool_call_id: "stable-tool".to_owned(),
            tool_name: "read".to_owned(),
            result: AgentToolResult::text("final body"),
            is_error: false,
        }));
        assert_eq!(state.scroll_anchor.get(), anchor_before);
        assert_eq!(state.transcript_top_row.get(), top_before);

        let (plain_after, scroll_after) = render(&mut state);
        assert_eq!(state.scroll_anchor.get(), anchor_before);
        assert_eq!(state.transcript_top_row.get(), top_before);
        assert!(
            plain_after[scroll_after..(scroll_after + height).min(plain_after.len())]
                .iter()
                .any(|line| line.contains("STABLE OLDEST SENTINEL"))
        );
        assert_eq!(state.committed_entries, 64);
    }

