    #[test]
    fn composer_header_hides_default_idle_status_but_keeps_meaningful_activity() {
        let mut state = todo_test_state(Vec::new());
        state.model = "faux/faux-1".to_owned();
        state.cwd = "<workspace>".to_owned();

        fn header(state: &TuiState) -> String {
            composer_border_lines(state, 120, crate::theme::DARK)[0]
                .spans
                .iter()
                .map(|span| span.content.as_ref())
                .collect::<String>()
        }
        fn status(state: &TuiState) -> String {
            composer_status_line(state, 120, crate::theme::DARK)
                .spans
                .iter()
                .map(|span| span.content.as_ref())
                .collect::<String>()
        }

        for idle in [
            "",
            "Ready",
            "Enter submit · Shift+Enter/Ctrl+J newline · Esc abort · Ctrl+D quit",
        ] {
            state.status = idle.to_owned();
            let top = header(&state);
            assert!(top.contains("⬢ faux/faux-1"), "metadata must remain: {top}");
            assert!(
                top.contains("◑ off"),
                "thinking metadata must remain: {top}"
            );
            assert!(
                top.contains("📁 <workspace>"),
                "cwd metadata must remain: {top}"
            );
            assert!(
                !top.contains("Ready"),
                "default idle status must be hidden: {top}"
            );
            assert!(
                !top.contains("Enter submit"),
                "key help belongs in welcome and /help: {top}"
            );
            assert!(
                !top.contains("⟲"),
                "footer must never carry an activity segment: {top}"
            );
            assert_eq!(display_width(&top), 120);
            assert!(status(&state).is_empty(), "idle status line must be blank");
        }

        // Meaningful transient status moves to the status line above the input
        // box; the compact footer keeps only static metadata.
        state.status = "Usage: /import <path.jsonl>".to_owned();
        let footer = header(&state);
        let line = status(&state);
        assert!(line.contains("Usage: /import <path.jsonl>"), "{line}");
        assert!(
            line.contains("⟲"),
            "status keeps the static activity glyph: {line}"
        );
        assert!(
            !footer.contains("Usage: /import <path.jsonl>"),
            "footer must not carry status text: {footer}"
        );

        state.status = "Ready".to_owned();
        state.is_streaming = true;
        let first = status(&state);
        state.animation_frame = 1;
        let second = status(&state);
        assert!(
            first.contains("Working"),
            "streaming must render activity: {first}"
        );
        assert!(
            first.contains("⟦esc⟧"),
            "streaming is abortable and must hint Esc: {first}"
        );
        assert!(
            !first.contains("Ready"),
            "busy activity replaces idle status: {first}"
        );
        assert_ne!(first, second, "streaming activity must animate");
        assert!(
            !header(&state).contains("working"),
            "footer stays static while streaming"
        );
    }

    #[test]
    fn composer_header_thinking_tag_shows_level_only_even_when_hidden_and_labeled() {
        // The compact top header tag carries only the thinking level — never
        // the `hidden`/`hid` suffix nor an extension-supplied hidden-thinking
        // label — regardless of `show_thinking`.
        let mut state = todo_test_state(Vec::new());
        state.model = "faux/faux-1".to_owned();
        state.cwd = "<workspace>".to_owned();
        state.thinking_level = ThinkingLevel::High;

        fn header(state: &TuiState) -> String {
            composer_border_lines(state, 120, crate::theme::DARK)[0]
                .spans
                .iter()
                .map(|span| span.content.as_ref())
                .collect::<String>()
        }

        // show_thinking = true: plain level.
        state.show_thinking = true;
        state.extension_hidden_thinking_label = Some("quietly thinking".to_owned());
        let top = header(&state);
        assert!(top.contains("◑ high"), "level tag expected: {top}");
        assert!(
            !top.contains("quietly"),
            "extension label must not squeeze into the header: {top}"
        );

        // show_thinking = false, no extension label: level only, no `hid`.
        state.show_thinking = false;
        state.extension_hidden_thinking_label = None;
        let top = header(&state);
        assert!(top.contains("◑ high"), "level tag expected: {top}");
        assert!(
            !top.contains("hid") && !top.contains("hidden"),
            "hidden state must not appear in the compact header: {top}"
        );

        // show_thinking = false + extension hidden label: still level only.
        state.extension_hidden_thinking_label = Some("quietly thinking".to_owned());
        let top = header(&state);
        assert!(top.contains("◑ high"), "level tag expected: {top}");
        assert!(
            !top.contains("quietly") && !top.contains("hid") && !top.contains("hidden"),
            "header must show only the level: {top}"
        );
    }

    #[test]
    fn transient_status_line_reserved_above_composer_even_when_idle() {
        use ratatui::backend::TestBackend;

        let mut state = todo_test_state(Vec::new());
        state.model = "faux/faux-1".to_owned();
        state.cwd = "<workspace>/project".to_owned();
        let mut terminal = Terminal::with_options(
            TestBackend::new(100, 24),
            TerminalOptions {
                viewport: Viewport::Inline(24),
            },
        )
        .expect("inline terminal");
        let mut images = TerminalImageRenderer::default();
        let mut draw_rows = |terminal: &mut Terminal<TestBackend>, state: &TuiState| {
            terminal
                .draw(|frame| {
                    let _ = render(frame, state, &mut images);
                })
                .expect("draw");
            terminal
                .backend()
                .buffer()
                .content
                .chunks(100)
                .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
                .collect::<Vec<_>>()
        };
        let footer_index = |rows: &[String]| {
            rows.iter()
                .position(|row| row.contains("╭── π"))
                .expect("footer row")
        };

        // Idle: the row directly above the composer border is reserved and
        // blank, so the input box never sits flush against content above.
        let idle = draw_rows(&mut terminal, &state);
        let footer = footer_index(&idle);
        assert!(
            footer > 0,
            "footer must never be the first live row: {idle:#?}"
        );
        assert!(
            idle[footer - 1].trim().is_empty(),
            "idle status row above footer must be blank: {:?}",
            idle[footer - 1]
        );

        // Active transient status: the text renders on the status line above
        // the footer, truncated to the row width, followed by a blank gap row
        // before the composer border, and never in the footer row.
        let session_root = tempfile::tempdir().expect("session root");
        let session_path = session_root
            .path()
            .join(".pi/agent/sessions/workspace-session-000001");
        let status_prefix = format!("Resumed {}", session_path.display());
        state.status = format!(
            "{status_prefix}{}",
            "/with/a/much/longer/chain/of/directories/pushing/past/the/row/width/limit".repeat(3)
        );
        let active = draw_rows(&mut terminal, &state);
        let footer = footer_index(&active);
        let status_row = &active[footer - 2];
        assert!(
            status_row
                .trim_start()
                .starts_with(&format!("⟲ {status_prefix}")),
            "{status_row}"
        );
        // OMP spacing: a blank gap row sits ABOVE the status text too, so the
        // text never sits flush against content above (gap · text · gap).
        assert!(
            active[footer - 3].trim().is_empty(),
            "gap row above active status must be blank: {:?}",
            active[footer - 3]
        );
        assert_eq!(
            display_width(status_row),
            100,
            "status line fills exactly one row"
        );
        assert!(
            status_row.contains('…'),
            "long status must truncate: {status_row}"
        );
        assert!(
            active[footer - 1].trim().is_empty(),
            "active status text must be followed by a blank gap row: {:?}",
            active[footer - 1]
        );
        assert!(
            !active[footer].contains("Resumed"),
            "footer must not carry long activity text: {}",
            active[footer]
        );

        // Abortable activity: spinner + working text + ⟦esc⟧ hint, footer static.
        state.status = String::new();
        state.extension_working_message = Some("Reading theme palette definition".to_owned());
        state.extension_working_visible = true;
        state.is_streaming = true;
        let busy = draw_rows(&mut terminal, &state);
        let footer = footer_index(&busy);
        let busy_status = &busy[footer - 2];
        assert!(
            busy_status.contains("Reading theme palette definition"),
            "{busy_status}"
        );
        assert!(
            busy_status.contains("⟦esc⟧"),
            "streaming must hint Esc: {busy_status}"
        );
        assert!(
            busy[footer - 1].trim().is_empty(),
            "busy status text must be followed by a blank gap row: {:?}",
            busy[footer - 1]
        );
        assert!(
            !busy[footer].contains("Reading theme"),
            "footer stays static while busy: {}",
            busy[footer]
        );
    }

    #[test]
    fn long_unsupported_agent_warning_uses_bounded_notice_not_composer_chrome() {
        use ratatui::backend::TestBackend;

        let mut state = todo_test_state(Vec::new());
        state.model = "faux/faux-1".to_owned();
        state.cwd = "<workspace>/project".to_owned();
        state.thinking_level = ThinkingLevel::Medium;
        state.status = "Ready".to_owned();
        let warning = "agent `legacy-reviewer` declares unknown tools: computer, imaginary_tool; ignoring them (OMP-compatible — the declared tool is not injected); supported child tools: read, bash, edit, write";
        state.apply_startup_warnings(vec![format!("Warning: {warning}")]);

        assert_eq!(state.composer_error.as_deref(), Some(warning));
        assert!(state.composer_error_is_warning);
        assert_eq!(
            state.status, "Ready",
            "warnings must not replace compact runtime status"
        );
        assert!(
            state.transcript.is_empty(),
            "startup warnings must not become durable transcript rows"
        );

        let composer = composer_border_lines(&state, 120, crate::theme::DARK)
            .into_iter()
            .map(|line| {
                line.spans
                    .into_iter()
                    .map(|span| span.content.into_owned())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        assert!(
            !composer[0].contains("⟲"),
            "Ready activity must be hidden: {composer:#?}"
        );

        let notice = composer_error_toast_lines(&state, 120, crate::theme::DARK);
        let notice_text = notice
            .iter()
            .map(|line| {
                line.spans
                    .iter()
                    .map(|span| span.content.as_ref())
                    .collect::<String>()
            })
            .collect::<Vec<_>>();
        assert_eq!(
            notice.len(),
            usize::from(composer_error_toast_height(&state, 120))
        );
        assert!(notice.len() <= MAX_COMPOSER_ERROR_HEIGHT);
        assert!(notice_text.iter().all(|line| display_width(line) == 120));
        assert!(
            notice_text[0].starts_with("Warning: agent `legacy-reviewer`"),
            "{notice_text:#?}"
        );
        // Word-wrap on word boundaries: no row may split a token mid-word
        // (the `invali`/`d` or `an a`/`vailable` character-chop failure mode).
        let clean = format!("Warning: {warning}");
        let reconstructed = notice_text
            .iter()
            .map(|line| line.trim_end())
            .collect::<Vec<_>>()
            .join(" ");
        assert_eq!(
            reconstructed, clean,
            "word-wrap must preserve every token intact: {notice_text:#?}"
        );
        let row0 = notice_text[0].trim_end();
        assert!(
            row0.len() == clean.len() || clean.as_bytes().get(row0.len()) == Some(&b' '),
            "row 0 must end at a word boundary, not mid-token: {notice_text:#?}"
        );
        assert!(
            notice_text.iter().all(|line| {
                !line.starts_with('╭') && !line.starts_with('│') && !line.starts_with('╰')
            }),
            "full box must not render: {notice_text:#?}"
        );
        assert!(
            notice_text
                .iter()
                .all(|line| !line.contains("Dismissed when"))
        );
        assert_eq!(
            notice[0].spans[0].style.fg,
            Some(crate::theme::DARK.warning)
        );
        assert!(
            notice
                .iter()
                .flat_map(|line| &line.spans)
                .all(|span| { span.style.bg == Some(crate::theme::DARK.custom_message_bg) })
        );

        let backend = TestBackend::new(120, 18);
        let mut terminal = Terminal::new(backend).unwrap();
        let mut images = TerminalImageRenderer::default();
        terminal
            .draw(|frame| {
                let _ = render(frame, &state, &mut images);
            })
            .unwrap();
        let screen = terminal
            .backend()
            .buffer()
            .content
            .chunks(120)
            .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
            .collect::<Vec<_>>();
        assert_eq!(
            screen
                .iter()
                .filter(|row| row.contains("declares unknown tools"))
                .count(),
            1,
            "{screen:#?}"
        );
        let warning_row = screen
            .iter()
            .position(|row| row.contains("declares unknown tools"))
            .expect("warning row");
        let composer_row = screen
            .iter()
            .position(|row| row.contains("π") && row.contains("faux/faux-1"))
            .expect("composer row");
        assert!(warning_row < composer_row, "{screen:#?}");

        state.record_accepted_prompt("continue");
        assert!(state.composer_error.is_none());
    }

    #[test]
    fn run_failure_is_ephemeral_and_never_committed() {
        let mut state = todo_test_state(Vec::new());
        state.apply(ApplicationEvent::RunFailed {
            message: "runtime exploded secret detail".to_owned(),
        });

        // Stream errors route to the single status row, not the separate
        // error-toast band, and never replace the compact runtime `status`.
        assert_eq!(
            state.stream_error.as_deref(),
            Some("runtime exploded secret detail")
        );
        assert!(
            state.composer_error.is_none(),
            "stream errors must not consume a separate toast band"
        );
        assert_eq!(
            state.status, "",
            "error text lives in stream_error, not compact runtime status"
        );
        assert!(state.transcript.is_empty());
        assert!(state.settled_commit_batch().is_empty());
        assert!(state.overflow_commit_batch(80, 12).is_empty());

        // The status row renders the failure as a single bounded Error line.
        let line = rendered_line_text(&composer_status_line(&state, 40, crate::theme::DARK));
        assert!(
            line.starts_with("Error: ") && line.contains("runtime exploded"),
            "status row: {line:?}"
        );
        assert!(!line.contains('\n'), "single-row status: {line:?}");
    }

    #[test]
    fn run_failure_occupies_exactly_one_status_row_without_layout_jump() {
        use ratatui::backend::TestBackend;
        // The reserved status section is sized from composer_status_line:
        // active text (Error — like the Working… it replaces) reserves 3 rows
        // (gap · text · gap); there is no separate error-toast band, so a
        // failed stream leaves the exact same chrome layout as an active one.
        let mut state = todo_test_state(Vec::new());
        state.is_streaming = true;
        state.status = "Working".to_owned();
        let active_error_section = tui_layout_heights(&state, 40, 24, 0, 0, 0).error;
        let active_status_section = tui_layout_heights(&state, 40, 24, 0, 0, 0).status;

        state.apply(ApplicationEvent::RunFailed {
            message: "invalid type: null, expected a sequence".to_owned(),
        });
        let failed_error_section = tui_layout_heights(&state, 40, 24, 0, 0, 0).error;
        let failed_status_section = tui_layout_heights(&state, 40, 24, 0, 0, 0).status;

        // Working… (3-row status, 0-row error band) → Error (also 3-row status,
        // 0-row error band): identical occupied rows, no layout jump.
        assert_eq!(
            (failed_error_section, failed_status_section),
            (active_error_section, active_status_section),
            "stream failure must not add a toast band or change status height"
        );

        // On the real screen: the Error text lives on the status row directly
        // above the composer border, not on a separate toast row above it.
        let mut terminal = Terminal::with_options(
            TestBackend::new(40, 24),
            TerminalOptions {
                viewport: Viewport::Inline(24),
            },
        )
        .expect("inline terminal");
        let mut images = TerminalImageRenderer::default();
        terminal
            .draw(|frame| {
                let _ = render(frame, &state, &mut images);
            })
            .expect("draw");
        let rows = terminal
            .backend()
            .buffer()
            .content
            .chunks(40)
            .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
            .collect::<Vec<_>>();
        let error_rows: Vec<usize> = rows
            .iter()
            .enumerate()
            .filter(|(_, row)| row.contains("invalid type"))
            .map(|(i, _)| i)
            .collect();
        assert_eq!(
            error_rows.len(),
            1,
            "exactly one status row carries the Error; rows: {rows:#?}"
        );
        // The composer border row is just below the status text + gap.
        let composer_border = rows
            .iter()
            .position(|row| row.trim_start().starts_with('╭'))
            .expect("composer border row");
        assert!(
            (composer_border as isize - error_rows[0] as isize).abs() <= 2,
            "Error must sit immediately above the composer border (gap·text): {rows:#?}"
        );
    }

    #[test]
    fn resume_notice_is_status_only_and_expires() {
        let mut state = todo_test_state(Vec::new());
        state.set_transient_status("Resumed 3 messages".to_owned());

        assert!(
            state.transcript.is_empty(),
            "resume notice must not become a transcript entry"
        );
        assert!(state.settled_commit_batch().is_empty());
        let line = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            line.contains("Resumed 3 messages"),
            "resume notice owns the reserved status row: {line}"
        );
        assert!(state.status_expires_at.is_some());

        let past =
            std::time::Instant::now() + TRANSIENT_STATUS_TTL + std::time::Duration::from_millis(1);
        state.expire_transient_status(past);
        assert!(state.status_expires_at.is_none());
        assert!(state.status.is_empty() || is_idle_status_text(&state.status));
        let expired = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            !expired.contains("Resumed 3 messages"),
            "expired resume notice must leave the reserved row: {expired}"
        );
    }

    #[test]
    fn working_shows_when_no_transient_notice() {
        let mut state = todo_test_state(Vec::new());
        state.is_streaming = true;
        state.status = "Working".to_owned();
        let working = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            working.contains("Working"),
            "activity when idle of transients: {working}"
        );

        state.set_transient_status("Resumed 3 messages".to_owned());
        let transient = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            transient.contains("Resumed 3 messages"),
            "transient notice beats Working: {transient}"
        );

        let past =
            std::time::Instant::now() + TRANSIENT_STATUS_TTL + std::time::Duration::from_millis(1);
        state.expire_transient_status(past);
        let after = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            after.contains("Working"),
            "Working returns after transient expiry: {after}"
        );
        assert!(
            !after.contains("Resumed 3 messages"),
            "expired notice gone: {after}"
        );
    }

    #[test]
    fn pre_text_stream_error_is_status_only_not_transcript() {
        // A serde abort on the first chunk yields an assistant with empty
        // content plus an error_message. That failure must occupy the reserved
        // status row and must never become a top-of-transcript System Error.
        let mut state = todo_test_state(Vec::new());
        let mut assistant = pi_ai::AssistantMessage::pending(&Model::default());
        assistant.content = vec![];
        assistant.error_message = Some("invalid type: null, expected a sequence".to_owned());
        assistant.stop_reason = pi_ai::StopReason::Error;
        state.push_message(Message::Assistant(assistant));

        assert!(
            state.transcript.is_empty(),
            "error must not become a top transcript entry"
        );
        assert_eq!(
            state.stream_error.as_deref(),
            Some("invalid type: null, expected a sequence")
        );
        let line = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            line.starts_with("Error: ") && line.contains("invalid type"),
            "status row: {line}"
        );

        let past =
            std::time::Instant::now() + TRANSIENT_STATUS_TTL + std::time::Duration::from_millis(1);
        state.expire_transient_status(past);
        assert!(state.stream_error.is_none());
        let expired = rendered_line_text(&composer_status_line(&state, 80, crate::theme::DARK));
        assert!(
            !expired.contains("invalid type"),
            "expired error leaves the row: {expired}"
        );
    }

