    #[test]
    fn slash_t_ranks_prefix_hits_before_settings() {
        let mut state = todo_test_state(Vec::new());
        state.editor.set_text("/t");
        state.refresh_completions();
        let values = state
            .completions
            .items
            .iter()
            .map(|item| item.value.as_str())
            .collect::<Vec<_>>();
        // `/todo-child` is gone: `/todo` is the single public Todo command, so
        // the /t prefix hits are exactly these five (in catalog order), with
        // subsequence matches (e.g. /settings) ranking after every prefix hit.
        let prefix_hits = ["/theme", "/thinking", "/todo", "/tree", "/trust"];
        assert!(
            values.iter().all(|value| *value != "/todo-child"),
            "/todo-child must not appear in /t completions: {values:?}"
        );
        let prefix_positions = prefix_hits
            .iter()
            .map(|expected| {
                values
                    .iter()
                    .position(|value| value == expected)
                    .unwrap_or_else(|| {
                        panic!("prefix hit {expected} missing from /t completions: {values:?}")
                    })
            })
            .collect::<Vec<_>>();
        assert!(
            prefix_positions
                .windows(2)
                .all(|window| window[0] < window[1]),
            "/t must rank prefix hits in catalog order before subsequence matches: {values:?}"
        );
        assert_eq!(
            state.completions.selected().map(|item| item.value.as_str()),
            Some("/theme"),
            "first prefix hit must be selected: {values:?}"
        );
        assert!(
            values.iter().any(|value| *value == "/settings"),
            "subsequence /settings remains listed after prefix hits: {values:?}"
        );
        let settings = values
            .iter()
            .position(|value| *value == "/settings")
            .expect("settings remains a subsequence match");
        assert!(
            settings > *prefix_positions.last().unwrap(),
            "settings must not outrank /t prefix hits: {values:?}"
        );
    }
