    #[test]
    fn vt100_render_stress_keeps_cjk_long_lines_and_tiny_frames_in_bounds() {
        use ratatui::backend::TestBackend;

        let mut state = todo_test_state(Vec::new());
        state.model = "faux/faux-1".to_owned();
        state.cwd = "<workspace>/项目".to_owned();
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::User,
            content: vec![ContentBlock::text(
                "请把这段中文和全角标点渲染进有限列宽：。！？",
            )],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::Assistant,
            content: vec![ContentBlock::text(format!(
                "CJK wrap 中文宽度 {} and an unbreakable token {}",
                "寬".repeat(40),
                "A".repeat(200)
            ))],
            tool_name: None,
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        state.push_entry(TranscriptEntry {
            kind: TranscriptKind::System,
            content: vec![ContentBlock::text("kept recent turns")],
            tool_name: Some("Compaction summary".to_owned()),
            tool_card: None,
            is_error: false,
            is_partial: false,
        });
        state.editor.set_text("draft 中文");

        let mut images = TerminalImageRenderer::default();
        for (width, height) in [(80u16, 24u16), (40, 12), (20, 8), (4, 3), (1, 1)] {
            let backend = TestBackend::new(width, height);
            let mut terminal = Terminal::new(backend).unwrap();
            terminal
                .draw(|frame| {
                    let _ = render(frame, &state, &mut images);
                })
                .unwrap();
            let buf = terminal.backend().buffer();
            let row_width = usize::from(buf.area.width);
            let rows = buf
                .content
                .chunks(row_width)
                .map(|row| row.iter().map(|cell| cell.symbol()).collect::<String>())
                .collect::<Vec<_>>();
            assert_eq!(
                rows.len(),
                usize::from(height),
                "frame row count at {width}x{height}"
            );
            for row in buf.content.chunks(row_width) {
                assert_eq!(
                    row.len(),
                    usize::from(width),
                    "vt100 cell overflow at {width}x{height}"
                );
            }
            if width >= 80 && height >= 24 {
                assert!(
                    rows.iter()
                        .any(|row| row.contains("compacted") || row.contains("Compaction")),
                    "compaction divider missing at {width}x{height}: {rows:?}"
                );
                assert!(
                    rows.iter().any(|row| row.contains('╭')),
                    "composer missing at {width}x{height}"
                );
            }
        }
    }

