    #[test]
    fn scoped_model_selector_highlight_follows_models_column_focus() {
        use ratatui::backend::TestBackend;

        let models = vec![
            scoped_model_fixture_model(
                "anthropic",
                "claude-haiku-4-5",
                "Claude Haiku 4.5",
                200_000,
                1.0,
                5.0,
                true,
            ),
            scoped_model_fixture_model(
                "deepseek",
                "deepseek-v4-flash",
                "DeepSeek V4 Flash",
                128_000,
                0.0,
                0.0,
                false,
            ),
        ];
        let selected_bg = crate::theme::DARK.selected_bg;
        let mut terminal = ratatui::Terminal::new(TestBackend::new(100, 20)).unwrap();
        let draw = |terminal: &mut ratatui::Terminal<ratatui::backend::TestBackend>,
                    selector: &ScopedModelSelector| {
            terminal
                .draw(|frame| render_scoped_model_selector(frame, selector, crate::theme::DARK))
                .unwrap();
            terminal
                .backend()
                .buffer()
                .content
                .chunks(100)
                .map(|row| {
                    row.iter()
                        .map(|cell| (cell.symbol().to_owned(), cell.style()))
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>()
        };
        let mut selector = ScopedModelSelector::new(models, None);
        // Providers column focus: the ● provider row carries the highlight.
        let rows = draw(&mut terminal, &selector);
        let provider_row = rows
            .iter()
            .find(|row| row.iter().any(|(symbol, _)| symbol == "●"))
            .expect("provider radio row");
        assert!(
            provider_row
                .iter()
                .any(|(_, style)| style.bg == Some(selected_bg)),
            "focused provider row must be highlighted"
        );
        // Models column focus: the highlight moves to the ✓ model row.
        selector.focus_models();
        let rows = draw(&mut terminal, &selector);
        let model_row = rows
            .iter()
            .find(|row| row.iter().any(|(symbol, _)| symbol == "✓"))
            .expect("model row");
        assert!(
            model_row
                .iter()
                .any(|(_, style)| style.bg == Some(selected_bg)),
            "focused model row must be highlighted"
        );
    }

    #[tokio::test]
    async fn scoped_model_selector_keys_switch_columns_and_move_within_them() {
        use crossterm::event::KeyCode;

        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application(cwd.path()).await;

        let models = vec![
            scoped_model_fixture_model(
                "anthropic",
                "claude-haiku-4-5",
                "Claude Haiku 4.5",
                200_000,
                1.0,
                5.0,
                true,
            ),
            scoped_model_fixture_model(
                "anthropic",
                "claude-fable-5",
                "Claude Fable 5",
                1_000_000,
                10.0,
                50.0,
                true,
            ),
            scoped_model_fixture_model(
                "deepseek",
                "deepseek-v4-flash",
                "DeepSeek V4 Flash",
                128_000,
                0.0,
                0.0,
                false,
            ),
        ];
        let mut state = todo_test_state(Vec::new());
        state.scoped_model_selector = Some(ScopedModelSelector::new(models, None));
        let key = |code| KeyEvent::new(code, KeyModifiers::NONE);
        let handle = |state: &mut TuiState, code| {
            handle_scoped_model_selector_key(&application, state, key(code)).unwrap();
        };

        handle(&mut state, KeyCode::Right);
        let selector = state.scoped_model_selector.as_ref().unwrap();
        assert_eq!(selector.column(), ModelColumn::Models);
        assert_eq!(
            selector.selected_id(),
            Some("anthropic/claude-haiku-4-5".to_owned())
        );

        handle(&mut state, KeyCode::Down);
        handle(&mut state, KeyCode::Down);
        let selector = state.scoped_model_selector.as_ref().unwrap();
        assert_eq!(
            selector.selected_id(),
            Some("anthropic/claude-haiku-4-5".to_owned())
        );

        handle(&mut state, KeyCode::Left);
        let selector = state.scoped_model_selector.as_ref().unwrap();
        assert_eq!(selector.column(), ModelColumn::Providers);
        assert_eq!(selector.provider_selected(), 0);

        handle(&mut state, KeyCode::Down);
        let selector = state.scoped_model_selector.as_ref().unwrap();
        assert_eq!(selector.provider_selected(), 1);
        handle(&mut state, KeyCode::Right);
        let selector = state.scoped_model_selector.as_ref().unwrap();
        assert_eq!(selector.column(), ModelColumn::Models);
        assert_eq!(
            selector.selected_id(),
            Some("deepseek/deepseek-v4-flash".to_owned())
        );
    }
    #[tokio::test]
    async fn scoped_model_selector_save_persists_canonical_scoped_models() {
        use crossterm::event::KeyCode;

        let cwd = tempfile::tempdir().expect("cwd");
        let application = test_application_with_settings(
            cwd.path(),
            serde_json::json!({
                "scopedModels": ["faux/stale"],
                "enabledModels": ["faux/legacy"],
            }),
        )
        .await;

        let fresh = scoped_model_fixture_model("faux", "fresh", "Fresh", 128_000, 0.0, 0.0, false);
        let mut state = todo_test_state(Vec::new());
        state.scoped_model_selector = Some(ScopedModelSelector::new(
            vec![fresh.clone()],
            Some(vec![fresh]),
        ));

        handle_scoped_model_selector_key(
            &application,
            &mut state,
            KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.status, "Saved model selection");

        let manager = application.settings_manager().expect("settings manager");
        let global = manager.global_settings();
        assert_eq!(
            global.scoped_models.as_deref(),
            Some(["faux/fresh".to_owned()].as_slice()),
            "save must overwrite the stale canonical scopedModels value"
        );
        assert!(
            global.enabled_models.is_none(),
            "save must drop the legacy enabledModels alias"
        );
        assert_eq!(
            global.scoped_model_patterns(),
            Some(["faux/fresh".to_owned()].as_slice()),
            "the runtime accessor must resolve the freshly saved scope"
        );

        let reloaded =
            pi_coding::SettingsManager::load_phase_one(cwd.path(), application._agent.path())
                .expect("reload settings");
        let persisted = reloaded.settings();
        assert_eq!(
            persisted.scoped_models.as_deref(),
            Some(["faux/fresh".to_owned()].as_slice()),
            "canonical scopedModels must survive a restart"
        );
        assert!(persisted.enabled_models.is_none());
    }

