    #[test]
    fn model_change_during_active_turn_marks_next_turn_until_settled() {
        let mut state = todo_test_state(Vec::new());
        let active =
            scoped_model_fixture_model("provider-a", "active", "Active", 128_000, 0.0, 0.0, false);
        update_tui_model(&mut state, "provider-b/next".to_owned(), Some(&active));
        assert_eq!(
            state.active_turn_model.as_deref(),
            Some("provider-a/active")
        );
        assert_eq!(state.next_turn_model.as_deref(), Some("provider-b/next"));
        let header = composer_header_line(&state, 100, crate::theme::DARK, Style::default());
        let header_text = header
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(header_text.contains("provider-a/active"), "{header_text}");
        assert!(!header_text.contains("provider-b/next"), "{header_text}");
        assert!(!header_text.contains(" next"), "{header_text}");
        assert!(!header_text.contains('→'), "{header_text}");
        let narrow = composer_header_line(&state, 24, crate::theme::DARK, Style::default());
        let narrow_text = narrow
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(
            UnicodeWidthStr::width(narrow_text.as_str()) <= 26,
            "{narrow_text}"
        );

        state.apply(ApplicationEvent::AgentSettled);
        assert!(state.active_turn_model.is_none());
        assert!(state.next_turn_model.is_none());
    }
